INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (5, '我已经困在这个鬼镇里好几个星期了，除了虫子和野草之外什么吃的都没有！我想吃点正常的食物，即使要多花点钱也无所谓。$B$B给我找点美食来，我就给你大笔的奖赏。$B$B听说夜色镇血鸦旅店的厨师格鲁奥做的黑蟹蛋糕很不错……') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (69, '哎呀！我上次肯定漏掉这个了。斯塔文的档案中的第一个地址下面还有另一个地址，这个地址被擦掉了一点。看起来好象他还去过闪金镇的狮王之傲旅店。你愿意的话就去那里查查看吧，$N。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (78, '我知道有人可以帮你。我以前领导暴风城卫队的时候，经常去夜色镇的血鸦旅店喝酒。那儿的老板斯密茨对当地的情况了如指掌。把这张东西给他，看看他对此有什么说法。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (93, '我可以告诉你个秘密——黑“蟹”蛋糕实际上是用蜘蛛腿做的！听起来是有点恶心，不过这种蛋糕的味道绝对一流！给我找点粘糊的蜘蛛腿来，我很快就能给你做好。$B$B听说结网毒蜘蛛身上很容易拿到这种东西——它们的巢穴就在东北部的丘陵和小河之间，暮色森林里的其它蜘蛛身上也有这东西。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (107, '威廉·匹斯特肯定有能让这两个年轻人见面的办法！$B$B把这个便笺拿去交给威廉，他现在正住在闪金镇的狮王之傲旅店。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (123, '这是一张日程表，记录了某个人被称作“收货人”的人在某天某时会收到从艾尔文森林的矿洞运来的一车黄金。$B$B根据日程表所述，这个收货人好像就住在艾尔文森林东部的布莱克威尔南瓜田附近。$B$B这件事非常重要，你必须向闪金镇的治安官杜汉报告。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (133, '我住得离镇子太远了，根本得不到保护。那些食尸鬼和行尸走肉还没有把我吃掉简直是个奇迹！其实昨天还有一群噬骨者来敲击我房子四周的墙！$B$B我得做个假人，一个用来吓唬食尸鬼的“稻草人”。我需要食尸鬼的肋骨来制作这个假人。你可以从食腐者、噬骨者、食脑者、腐烂者和瘟疫食尸鬼身上拿到这东西。$B$B给我带足够的肋骨来，我就会给你一些奖赏。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (147, '如果这个“收货人”是私自从我们的矿洞里开采黄金的话，那么他就是在偷窃王国的金库！把他就地正法，然后把他的交易日程表上提到的戒指带给我。也许这枚戒指能告诉我们这个“收货人”是在为谁工作……$B$B那张交易日程表上说“收货人”就藏在布莱克威尔南瓜田里，你应该到那儿去找他。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (158, '我需要一瓶叫做僵尸酒的饮料。夜色镇血鸦旅店的店主斯密茨应该有些存货。$B$B最近晚上寒风刺骨，我得来点僵尸酒，好让我的血液重新沸腾起来。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (184, '这是西部荒野一片农田的地契，由西奥多·法布隆和他的妻子弗娜·法布隆联名签署。地契背面还有潦草的字样：$B$B“我们到法布隆家里走了一遭，弄到了他的地契。我们觉得你可以很轻易地照着这张样本给自己也造出几份地契来。$B$B法布隆家的人不会找我们的麻烦，我最后一次看到他们的时候，他们的四轮货车坏在了路上。”$B$B你认为法布隆夫妻俩可能正在到处找这张地契……') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (192, '接下来的部分可就比较困难了。一个真正的猎豹能手必须要有能力杀死深喉猎豹这种荆棘谷中最危险的生物。去杀死十只深喉猎豹，向我们证明你的猎豹能力吧！$B$B如果你很难找到它们的踪迹的话，就埋伏起来等它们出现……') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (196, '让我们来看看你能不能对付下一个挑战吧。这附近栖息着一种非常狡猾的迅猛龙，我们叫它丛林捕猎者。它们远比你之前捕猎的目标更难追踪和猎杀。猎杀十只丛林捕猎者，然后我就会告诉你这里最惹眼的目标是什么。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (240, '完成了——格鲁奥烹制的黑“蟹”蛋糕！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (264, '太过分了！他因为那该死的十字军离开了我，说什么“圣光是我们用来与亡灵抗争的最重要的东西。”$B$B那么，他的孩子呢？我呢？我日复一日地等他……一直在默默地支持着他那该死的职责！$B$B看看“公正”带给你的一切，$N！他已经死了，而我却成了他曾经想要消灭的东西！$B$B把这个垃圾放到他那修在瑟伯切尔的坟墓上吧。我不想再跟他有任何联系了！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (281, '不久之前，有一艘名叫“盲眼公主”的商船遭到了一群鱼人的袭击。尽管这艘船完完整整地逃了出来，但船甲板上放着的货物都被那些该死的鱼人给拖下水抢走了，其中甚至包括一座十分宝贵的泰瑞纳斯·米奈希尔的雕像。我们希望有人能把这座雕塑给抢回来。$B$B到海岸边的鱼人村落里去，仔细找找看有没有木箱、木桶，或者其他丢失货物的踪迹。在那里找到米奈希尔雕像，然后回来向我复命。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (283, '木桶发出了轻微的嘶嘶声。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (299, '在迅猛龙大举入侵之前，我找到了一块名叫戈奥兹之石的巨大石碑。我翻译好的文字被分成了四部分，散落在挖掘场中的四个不同的地方。这些文字描述的是一个“神圣的计划”和一个“注定的命运”。$B$B我们应该马上把它们都收集起来，而不是继续在这里浪费时间。但是我已经很老了，恐怕没办法再杀出去跟那些凶猛的野兽作战了。但是你不同，你年轻而强壮。$B$B到挖掘场里去搜索这四片失落的石板：阿度斯石板、莫德尔石板、高尔姆石板和奈尔鲁石板。它们应该被藏在某些古董器物里，另外你也得留意土壤松动的地方。把它们拿回来给我，这样我才能揭开这个秘密！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (315, '我正在寻求可以酿制出完美的酒的方法。我知道我能酿造出来，我缺的只是一份正确的酿酒配方……$B$B霜鬃巨魔在东边的山坡上种植了一种叫做微光草的植物，他们通常在奇怪的部族仪式上用到它。我们矮人还没有发现这种草有什么用途，不过它的口味非常特别……我要把这种植物用在我的酒里！$B$B从霜鬃先知那里给我弄一些微光草来，或者你也可以从巨魔用来装微光草的篮子里偷一些。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (328, '尽管在这些档案文件里都没有提到列兵索尔森，但你发现在赫罗德的一本帐薄后面绑着一只小小的黄铜钥匙。$B$B你还在研究他的其它笔记时发现了其中有一小部分提到，在一个“安全的保险箱”中装有大量的文件。这个保险箱应该在库尔森营地后山的某处洞穴之中，他们管那里叫“储藏室”。$B$B如果你能找到这个保险箱并用这把黄铜钥匙打开它的话，或许里面的文件有助于找到导致索尔森身份暴露的内鬼。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (330, '你给我的便笺上的签名只有一个字母“M”……我也不知道这代表谁。$B$B但是……这便笺同时也告诉我们，这个人应该是上周与索尔森一同巡逻的同伴。所以，只要知道上周谁和索尔森一起巡逻过，那他就应该是内鬼没错了！$B$B去找塞斯曼下士问一问，他是负责制订巡逻时间表的人，可以告诉你那个时候索尔森和谁在一起。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (335, '维沙克公爵最近正在贵族议会中兴风作浪，他似乎知道一些我们的事情，而且还游说其他议员们，要他们通过他提出的对这里进行一次全面调查的提案。我有一个计划，能让维沙克迷上些别的什么东西……但我需要你的帮助。$B$B在夜色镇郊区的斯塔文的花园里生长着一种名叫蒂罗亚之泪的白色小花，去给我弄一朵来。另外我还需要一些麝鼠根，那种东西只生长在湿地，就在巨石水坝下的瀑布底部。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (336, '维沙克公爵与所有人一样有自己的弱点，他对酒的爱好胜过一切。更可恶的是，这个蠢货整天想着把我们这个小小的酒馆给弄关门了，而他自己却呆在楼上整夜整夜地喝个不停，至于那些像滚雪球一样越攒越多的账单，他是肯定不会付的。好吧，让我们看看维沙克会有多喜欢我们给他准备的这种特制佳酿：黑爪烈酒。这一定会很有意思的，$N。$B$B把这个带给他，看看他的反应如何，我觉得这傻瓜可能会在祈愿厅里当场开喝。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (337, '这本书的封面已经有被刮坏的痕迹，还沾上了泥污，但是书脊上“暴风城的历史”的字样仍然清晰可见。打开书的第一页，可以看到上面盖着暴风城图书馆的印章。$B$B看起来似乎有人从图书馆借出了这本书却从来没有归还……') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (342, '啊，第四章，大结局！多么精彩的结局啊！$B$B第四章里我们只丢了3页，也就是第25页，第26页和第27页。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (343, '我正要作一次关于“坚韧的灵魂”的演讲，我想引用一本关于金属学的著作《金属的延展性》里的一些段落。暴风城堡里的皇家图书馆里应该有这本书的副本。你能把它拿来给我吗？如果可以的话，圣光定会保佑你的！$B$B皇家图书馆很大，但首席管理员米尔顿·西弗对每一个书架上有些什么书都了如指掌。告诉他我需要什么，他就会把书找给你的。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (348, '我病了…病得……非常厉害……$B$B我…染上了…荆棘谷热疫…致死的疾…疾病……$B$B……只…只有吃下…野人莫…莫…莫克…的心脏…才…才有救…那…是…一只残忍而…狡猾的…野兽。$B$B……巫医安巴格瓦巫师…是…唯一会…召唤…它…的人……$B$B找到…住在南边…海岬…洞穴…里的安巴格瓦……$B$B……快点…我就要死了…就要死了……') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (351, '你发现了一个奇怪的蛋形金属物体。随便拨弄了几下之后，它居然打开了，变成了一个看起来像是由侏儒创造的那种机器装置！一个噼里啪啦的声音从这个蛋形机器装置中传了出来。$B$B“我的名字叫奥格索普，我的母体机器人不见了！如果你能帮我找到它的话，我会奖励你的！请把这个定向器带到我的母体机器人那里。我现在已经为你勘探出了它的所在地！它现在就在塔纳利斯的大裂口那里！”') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (417, '莫里·铁钻在他的日记中写道，他受到了一头名叫癞爪的巨型冰爪熊的袭击。他赶走了这只野兽，不过自己也已遍体鳞伤。$B$B从莫里尸体上的伤痕判断，癞爪一定又折回来杀死了他。$B$B然而，莫里在他的日记中写下了他最后的遗愿：$B$B杀死癞爪，为我复仇。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (427, '执行官阿伦大人提供给我们的文件中指出，我们将无法避免与那些卑劣的血色十字军进行一场战争。我们已经知道了他们穿越提瑞斯法林地所走的那条小径的确切位置。$B$B但亡灵卫兵还有其它艰巨的任务，巫妖王的军队正在夜色中逐渐壮大起来。我们需要一些像你这样的志愿者来把那群血色十字军送进坟墓。$B$B顺着镇外的道路向西走，穿过索利丹农场到废塔那里去，杀死10名血色十字军战士。以此来证明你有足够的能力为黑暗女王陛下服务。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (439, '在一大堆尸体中间，有一只裸露的手。这是一只女人的手，虽因瘟疫而导致皮肤上布满红痘，但仍然十分白皙。$B$B她的手上戴着一只戒指。你从尸体的手上取下这只戒指，看到戒指内环中有一道铭文：$B$B“赠予黛丽娅”') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (441, '黛丽娅有个丈夫叫拉林夫，他现在居住在幽暗城。如果居住在布瑞尔的这位黛丽娅就是这只戒指的主人，想必他应该知道。$B$B拉林夫就在幽暗城的贸易区。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (460, '你看上去跟那帮腐皮豺狼人不一样，这真好。我都快绝望了……$B$B我叫奥拉瑞克，过去曾是图勒的大管家兼保镖。他用他的魔法“保护”了我，使我免受“亡灵瘟疫”的影响，但他的魔法也让我变成了这个半死不活的样子。而且，自从图勒创造了那群该死的腐皮豺狼人之后，他竟然砍了我的头……还把我的头给那群豺狼人当球踢！$B$B拜托，把我带到我的身体那儿去。那群豺狼人大概是把它埋在了芬里斯城堡的马厩旁……') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (485, '你发现了一个奇怪的蛋形金属物体。随便拨弄了几下之后，它居然自动打开了，变成了一个看来是由侏儒制造的机器装置！一个奇怪的声音从这个蛋形机器装置中传了出来。$B$B“我的名字叫奥格索普，我的母体机器人不见了！如果你能帮我找到它，我就会奖励你的！请把这个定向器带到那个母体机器人那里。别担心，我现在已经检测到了它的所在地！它现在就位于藏身石那一带的河水源头附近！”') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (492, '亡灵卫兵们说，他们又抓住了一个愚蠢的矮人巡山人。在对这个俘虏做出“妥善”处理之前，卫兵们似乎打算把他先关在恐惧之末旅店的地下室里。$B$B不如你帮我跑一趟，去看看这位可怜的俘虏喜欢不喜欢我为他特制的饮料吧。那饮料里只掺了一丁点黑暗女王想在整个艾泽拉斯大陆上使用的那种东西……') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (494, '嘘！安静点，仔细听我说，$C。$B$B我被派到这个地方来监视希尔斯布莱德镇里的人类的动向，你必须把我的口信带给塔伦米尔的高级执行官达萨利亚，跟她说一句：$B$B“西边传来乌鸦的第三声叫声。”$B$B沿着大路往东走，注意看路标。快点！赶快去塔伦米尔，这件事情很紧急！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (507, '匹瑞诺德一定要被除掉，这个卑鄙的家伙绝不能继续在这世上逍遥了。他的领地就在北边的洛丹米尔湖岸上。去完成这个任务，$N，别忘了把酋长想要的项链也拿到手，然后再回到这里来。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (565, '我，伟大的巴图罗，将为你做一件闻名世界、全联盟皆知的雪人毛皮披风！$B$B不信你就到处跑跑看，能不能再找件更棒的。每个人都会说：“巴图罗，没有比这更好的披风了！”当然，当然没有。$B$B巴图罗需要一个毛布卷，一件由技艺高超的制皮匠缝制的山地披风，一股细线，当然还要有雪人的毛皮！把这些东西带给我，我就让你看看我的本事！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (577, '嗯，这些靴子已经基本定型，接下来就要开始打磨表面了。但你带来的皮似乎少了点，做不出足够的鞋垫来。$B$B“那现在我们得干什么呢，崔斯里克？”你肯定会马上问这种问题，哈哈，你跟崔斯里克说话可真不幸啊，因为我马上就要给你派活干啦！$B$B没人会去观察鞋垫的，所以我们只要找点又厚又便宜的鳄鱼皮就行了。纳菲瑞提湖旁边的那种钳嘴鳄鱼就不错。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (597, '这是一张藏宝海湾的地图，上面用红笔标叉的地方就是你现在站的位置。$B$B图上潦草的写着几行字：$B$B“你们的任务就是悄悄地在此地扎营，等待南方指挥部发出信号后再开始攻击。如果任何人试图阻碍你们，格杀勿论。”') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (606, '若是有一件事我不能忍，那就是有人不肯付赌债！这儿有很多人欠我的钱。你觉得能帮我去讨么？$B$B首先，是码头上的“病鬼”菲利普。上星期后他就欠我好大一笔，我要讨回来！不过咱们得吓唬他才行。$B$B出城打几只老迈的薄雾谷猩猩来。弄几副好下水，给“病鬼”捎去。别让他知道这是动物身上的，让他自己想象去。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (609, '我这儿的白条已经少了许多啦，但还是有许多没信誉的家伙欠着我的钱。$B$B接下来，我们得对付“畸形足”玛雷·维尔金斯、火柴棍乔乔，还有拇指苏克。$B$B这帮家伙的债欠了好久，我看他们是不想还了！后来，我听说他们被什么人给骗到丛林里去了。我当然不关心他们到底会怎么样——我要的是我的钱！$B$B他们应该就在东北方的阿博拉兹废墟和朱布瓦尔废墟里。找到他们，把我的钱拿回来。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (610, '我老爸派你来的？我还以为那怪老头已经早就放弃掉我了呢。$B$B我之所以离家出走确实不是他的错，他只是不应该为我安排好一条乏味的人生道路，并希望我欣然接受它。我怎么能忍受整天读着那些发霉的书本，整天和那帮灰头发加驼背的乏味老头法师们在一起！$B$B如果你需要我的匕首，你可能得从一个叫“帅小伙子”邓肯的血帆海盗那里夺回来。我想你只要教训教训他，他就会屈服的。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (636, '这本书叙述了元素公主密斯莱尔和她被囚禁在阿拉希高地下面的故事。$B$B它还叙述了高地里的一处秘密的水晶岩层。这些被称为“密斯莱尔水晶碎片”的东西是囚禁大地公主的监狱的窗户。$B$B如果某个勇敢的人能找到密斯莱尔水晶碎片，那么$g他:她;\r\n就有可能和她交谈……') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (637, '你手中的这封信湿淋淋的，已经面目全非了，只有几页像是得到了精心保护的信纸上的字迹还能辨认。$B$B这封信是写给铁炉堡的萨拉·巴鲁女士的，开头写着，“亲爱的萨拉……”') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (648, '那个侏儒的声音再次从那个机器人中传了出来：$B$B“我需要你帮忙把OOX-17/TN移动到一个安全的开阔地，这样它才可以启动起飞程序。它自带隐形系统，但是我需要一点时间来远程启动这个系统。请你把这个机器人从现在的位置护送到热砂港去！那里是个非常理想的起飞点，有足够的空间作为机器人起飞的跑道！”$B$B“将它护送到那里，然后再到藏宝海湾来找我！奥格索普·奥布诺提斯——完毕！”') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (704, '阿戈莫德送来的最后一份报告让我感到十分困惑，现在他死了，我就更难受了！他提到挖掘队在奥达曼附近的挖掘场找到了一些“远古的石罐”。我担心是他找到的罐子影响了石腭怪，就像这里发现的小石像一样。$B$B我要你去找到那些罐子，把它们拿回来以供研究。到奥达曼挖掘场去收集那些罐子吧，完成之后再回到我这里来。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (720, '<在地图上有一行用粉笔潦草写下的文字>$B$B“雷杜尔，$B他们把我带到了奥达曼，请速来援助。$B——铁趾”') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (738, '勘察员阿戈莫德曾是荒芜之地的挖掘场负责人，就是西南边的那座挖掘场。我说“曾是”，是因为……嗯，最近几周我都没有得到他的任何消息。请你帮我找到阿戈莫德并拿到他的报告。$B$B我最后一次得到的消息是：阿戈莫德在荒芜之地最南边的挖掘场——那是苦痛堡垒附近的一个不起眼的小地方。你先去那里找找看吧。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (739, '阿戈莫德留下的足迹表明他是从西边走过来的。从沙石上的斑斑血迹不难看出，矮人阿戈莫德爬行了好一段距离。$B$B爬到这里的时候，他终于被死神带走了。$B$B经过仔细察看，你在旁边的沙石中发现了几个潦草写下的字迹：“莫达洛克”。$B$B字迹就在阿戈莫德的手边。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (775, '任何能够完成大地之母仪祭的$R都可以赢得整个雷霆崖的尊重。$B$B你的最后一个任务是去见见我们的伟大首领凯恩·血蹄，他就住在雷霆崖最高的那座台地上。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (819, '张贴在酒桶一角的纸条上写着：“老陈 - $B$B祝汝精神得提升，祝汝精神永提升。”') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (835, '加兹鲁维跟我说过：“雷兹拉克呀，有一件事情你必须铭记，那就是如果你想把事情做好，就得亲力而为。”$B$B我不能让那些商队全都有来无回，所以我得自己解决这件事才行。枯水谷在烈风峡谷的东边，那里的鹰身人多到数不胜数，只要把它们全都给做了，那条路就彻底安全了。$B$B当然，加兹鲁维还教过我另一点，那就是“有钱能使磨推鬼”。那么，你愿意帮我的忙吗，$N？') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (836, '那个侏儒的声音再次从那个机器人中传了出来：$B$B“我需要你帮忙把OOX-09/HL移动到一个安全的开阔地，这样它才可以启动起飞程序。它自带隐形系统，但是我需要一点时间来远程启动这个系统。请你把这个机器人从现在的位置护送到望海崖去！那里是个非常理想的起飞点，有足够的空间作为机器人起飞的跑道！”$B$B“将它护送到那里，然后再到藏宝海湾来找我！奥格索普·奥布诺提斯——完毕！”') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (864, '“搞定了，现在能量源已经被安全卸载，而你的数据也被完全保留下来了。好了，接下来就只有祝你一路顺风了，希望你的科学实验一切顺利。”$B$B那个地精转身开始继续做加基森水业公司的事情。你小心翼翼地把封好的实验工具包收起来，然后准备把它带回幽暗城。药剂师金格正在那里等着你向他进行回报。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (865, '贫瘠之地的迅猛龙比其它地区的更加聪明狡猾，我想它们的智慧就来自它们的角！如果是这样的话，我可以将它们的角磨成粉末，制成“智慧饮料”，然后就能卖个大价钱！！！$B$B我想你应该能帮我的忙……从赤鳞镰爪龙身上弄一些完整的迅猛龙角来，它们就栖息在贫瘠之地的南部以及靠近灰谷森林边界的贫瘠之地北部。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (894, '风险投资公司最近在北边设立了小型的研究设备，就在淤泥沼泽的西南部。我对他们在做的东西并不了解，只知道他们正在试验一种名叫“主动式负载平衡器”的装备。$B$B那个主动式负载平衡器到底是什么东西呢？不管它是什么，我都想研究研究它，所以我需要找个人来帮我把它弄到手。$B$B我手里有控制系统操作手册的副本，你应该知道该怎么把那什么平衡器卸下来。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (895, '通缉令！$B$B巴隆·朗绍尔，破浪号的船长$B$B吉尔尼斯的朗绍尔船长统领南海海盗横行海上，现因海盗罪名指控被通缉。领取奖赏者必须提供足以证明自己杀掉了巴隆·郎绍尔的证据！$B$B——加兹鲁维') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (908, '暮光之锤已经进入了黑暗深渊中的月光神殿废墟里去了，他们的目标肯定是要强迫元素生物来对付我们。如果我们不及早采取对策的话，这个地区就将永远被他们控制。\r\n\r\n到黑暗深渊去找到废墟中的深渊之石，它应该在靠近水边的地方。深渊之石里面是深渊之核——那里面记载了所有元素生物的历史。如果我拥有了它，我和大地之环就能阻止他们了！ ') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (909, '被击败的水元素留下了一个奇怪的水球，你猜想这东西可能是为水元素提供能量的。一股看起来就很恶心的水流在球体内翻腾喷溅，而球体本身似乎不受任何自然力的影响。$B$B如果说有人能对这个东西有所了解，那就只能是大地之环的耶努萨克雷了。他就在灰谷的佐拉姆加前哨站里。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (1001, '细小的声音噼里啪啦地从机器内部传出来。$B$B“这里是维兹班恩！下一个传声盒在奥伯丁北部海岸上的某个地方。我的记性有时候不太好，不好意思！$B$B那台传声盒的编号是411，需要3颗蛇颈龙的眼球来修理。你可能得跳进漆黑冰冷的大海深处去寻找黑海岸鱼龙……真抱歉……$B$B就像上次一样，只要你给传声盒带去维修所需的物资，它就会给你吐出报酬的。*打嗝*……什么？没事，我很好！”') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (1002, '传声盒突然静了下来，然后你听见维兹班恩又开始说话。$B$B“下一个传声盒的编号是323。它在奥伯丁北部，不过……我的麦酒哪儿去了？什么？哦，在路上，小桥边，你不会找不到它的。”$B$B维兹班恩咕哝咕哝地说了一些不连贯的话，然后你听见大口喝酒的声音。$B$B“这个传声盒需要月夜猛虎的牙齿来维修……需要6颗。”') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (1003, '在一阵什么东西沸腾和油滴四溅的奇怪声音之后，你听见维兹班恩颤抖的声音从机器中传出。$B$B“顺着这条路，在遥远的南方就能找到下一个传僧盒。里应该不难发现它……就在路边上……在栅栏附近。我想我把它藏在矮……矮树丛里了。呵呵呵……没错，传声盒525号得有从那些灰斑蓟熊身上扒下来的灰色头皮才能维修。对，灰色的……呵呵呵……”$B$B当机器停止下来的时候，你听到更多类似吞咽的声音。然后，突然之间，它又启动了。$B$B“4块！”') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (1031, '安妮莉亚把手放在你的肩头上，慢慢地把你拉近她的身边。她艰难地喘着气，抬手指向北方的拱门。在她的气息渐渐变得微弱，眼睛慢慢地闭上之前，安妮莉亚留下了最后一句话：“被他夺走了……加萨里斯……”她临终时还在想着要让塞纳留斯的树枝回到树妖的手中。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (1204, '我正在研究一道叫作“泥石龟蟹汤”的菜，现在我还需要一些原料……唉，我觉得我真是不适合在尘泥沼泽里长途跋涉！$B$B那么，$N，你能帮我去打猎吗？首先，我需要泥石龟的舌头，这些海龟经常在海岸附近出没。$B$B不过我要的还不是一般的舌头！听说有些泥石龟的舌头是分叉的……$B$B他们说那样的舌头吃起来味道特别好，而且我也很喜欢给我的菜里加点特别的风味……') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (1251, '有一面被烧毁旅店的大火熏黑了的铁盾牌和倒塌的烟囱连在一起，这根烟囱是树荫旅店烧毁之后留下的几段残砖断瓦中的一部分。$B$B这面铁盾牌可以从烟囱的砖上拿下来。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (1252, '地上闪过的一道光芒把你的视线引到碎石的下面。你拨开了碎石，发现灰尘下有一枚白色的徽章，表面上印有金色的船锚，那是塞拉摩的标记。$B$B锚的下面刻着“帕瓦尔·雷瑟上尉”的字样。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (1253, '有一面被烧毁旅店的大火熏黑了的铁盾牌和倒塌的烟囱连在一起，这根烟囱是树荫旅店烧毁之后留下的几段残砖断瓦中的一部分。$B$B这面铁盾牌可以从烟囱的砖上拿下来。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (1260, '我在为餐馆编写新的菜谱，这套新菜谱里都是本地特产的菜色，以“海湾”为主题。我想，蓝色隐士旅店的客人一定会很喜欢这个的！$B$B我让我侄子摩根到塞拉摩去收集当地的食谱了，那地方就在尘泥沼泽的边界地带。现在我得知道他目前都找到了些什么。$B$B去塞拉摩的路很长，起码对我来说是太长了些。不过像你这么个年轻的$C对这种长途旅行一定会欣然往之的，对吧？') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (1268, '有几排蹄印从树荫旅店那仍然冒着烟的废墟中延伸出来。大部分蹄印都埋在沼泽地的松软泥土里没法辨认，不过至少还有一些是可以看清的。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (1269, '地上闪过的一道光芒把你的视线引到碎石的下面。你拨开了碎石，发现灰尘下有一枚白色的徽章，表面上印有金色的船锚，那是塞拉摩的标记。$B$B锚的下面刻着“帕瓦尔·雷瑟上尉”的字样。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (1284, '有几排蹄印从树荫旅店那仍然冒着烟的废墟中延伸出来。大部分蹄印都埋在沼泽地的松软泥土里没法辨认，不过至少还有一些是可以看清的。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (1638, '你已经展示了作为一个战士应有的天赋，$N。但是你现在还很年轻，还有很多东西需要学习。$B$B去和哈里·伯加德谈谈吧——他通常都在暴风城旧城区的猪和哨声旅店里。哈里是个老兵，也是个优秀的老师。他能教你许多一生受用的知识。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (2158, '每个冒险家在疲惫的时候都需要休息——而休息和放松的最佳去处就是狮王之傲旅店！$B$B我的好朋友法雷是那里的旅店老板。告诉他是我介绍你去的，也许他还会给你些特别优惠呢。$B$B如果你要去狮王之傲旅店的，沿着大路往南走就没错了！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (2198, '你找到了一条破碎的项链，但是破旧不堪的外表并不能掩饰它高超的制作工艺。项链已经破碎，原本应该镶在项链上的三块宝石不见了。在项链的内侧印有铁炉堡的徽记，旁边还刻着三个小字：“TdK”。$B$B如果你想要了解这条项链背后的故事，你就必须找到它的主人。也许那个徽记和小字就是线索……') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (2204, '你现在需要去为项链找到它的“精神”力量，奥达曼无疑最适合的地方。据说那里有很多的石人跑来跑去，对吗？那么，杀死他们当中最强大、最邪恶的那个石人，然后把他身上的能量源夺过来！我敢保证可以把那能量源里的能量重新注入到项链之中。$B$B如果没有那样的能量源，想要修复项链根本是不可能的。取得能量源之后尽快回到铁炉堡来找我，然后我们就能把项链完全恢复到原来的状态啦！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (2260, '你已经是个很有名气的$C了，$N。事实上，暴风城的情报机构点名要你去为他们效力。$B$B这次旅行会很辛劳，而且一路上危机四伏，不过我想谁也不会轻易放弃在暴风城军情七处训练的机会。$B$B一个崭新的世界在等着你，$N。到暴风城的旧城区去,和军情七处总部里的“剃刀”雷吉克谈一谈吧，祝你好运。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (2278, '财宝室的中间是四块巨大的白金圆盘，每块圆盘上都刻满了各种各样的未知文字和图案。你的手触摸这些圆盘的时候，你感到了一丝震动。就在你接触圆盘的一瞬间，一个巨大的石头守卫者的形象出现在了你的面前。$B$B“你好。我是知识的守卫者。土灵的创造者所留下的一切有关这个种族的知识都已经存储在了这张诺甘农圆盘上了。”$B$B你发掘到了迄今为止这个世界上最宝贵的知识财富！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (2298, '然后我们就到了那里，准备执行第三阶段的计划。突然，一伙麦格尼手下的家伙闯了进来，他们自称是来搜查的，二话不说就要抓人。$B$B但是没人敢在我霍夫丹·黑须面前动粗！于是双方唇枪舌剑地开始吵，结果你的名字就被不知道哪个白痴吼了出来！$B$B我的意见？赶紧骑上狮鹫离开铁炉堡，到暴风城去。到旧城区里去找我的一个老朋友，他的名字叫“剃刀”雷吉克。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (2766, '你发现了一个奇怪的蛋形金属物体。随便拨弄了几下之后，它居然自动打开了，变成了一个看来是由侏儒制造的机器装置！一个奇怪的声音从这个蛋形机器装置中传了出来。$B$B“我的名字叫奥格索普，我的母体机器人不见了！如果你能帮我找到它，我就会奖励你的！请把这个定向器带到那个母体机器人那里。别担心，我现在已经检测到了它的所在地！它现在就位于深痕谷中的一个山洞里！”') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (2767, '那个侏儒的声音再次从那个机器人中传了出来：$B$B“我需要你帮忙把OOX-22/FE移动到一个安全的开阔地，这样它才可以启动起飞程序。它自带隐形系统，但是我需要一点时间来远程启动这个系统。请你把这个机器人从现在的位置护送到被遗忘的海岸去！那里是个非常理想的起飞点，有足够的空间作为机器人起飞的跑道！”$B$B“将它护送到那里，然后再到藏宝海湾来找我！奥格索普·奥布诺提斯——完毕！”') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (2873, '我欠藏宝海湾的“海狼”马克基雷一些朗姆酒，那是打赌输的，但我现在一瓶朗姆酒都没有了！科尔戈船长偷了我最后一船货，他把它们藏在南边的那个戒备森严的海盗镇里。$B$B如果你能找到我的那批朗姆酒并把它们给我拿回来的话，那我就可以向马克基雷证明，藏宝海湾的那些酒跟我的朗姆酒比起来只能被称作垃圾！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (2876, '这卷轴上面记载着热砂港和藏宝湾之间的船运时刻表，包括过去和未来计划中的船运批次和船名，一些船的旅程旁有个大大的红叉记号，剩下的旁边有类似“华丽的战利品”和“坚固的战舰”之类的字样。$B$B热砂港那里的人一定非常想看看这个文件。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (2941, '我一生中研究了许多课题，最近我迷上了遍布辛特兰海滩地区的钳嘴龟。我特别想看到一只名叫加莫里塔的大型钳嘴龟，本来呢，我想要自己去一趟，但繁重的研究工作让我不得不留在这里。如果能搞到一张它的画像就好了。$B$B把这封信交给塔纳利斯的克格尔·曲藤。她为我发明了一种可以快速抓取图像的装置，我想她把那个东西叫做“快照”……') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (2951, '这个装置屹立于那些竭力保护房间的侏儒中，装置上有一块小金属牌，上面写着“超级清洁器5200型”，还有一段文字：$B$B：“污垢和残渣让你的东西看起来污秽不堪？超级清洁器5200型会使它重现光芒！将你想要清理的物品放入清洁器中，然后向槽里投入三枚银币。稍候片刻，你的珍宝就会重新变得洁净而耀眼！”') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (2967, '你打开了底座，白金圆盘又一次突然出现在你的背包里。$B$B你从石头守卫那里获取了许多信息，而且白金原盘又回到了你的手中，现在你应该回雷霆崖向纳拉·蛮鬃汇报这个大发现了。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (3364, '嘿！我之前应该把这可口的热酒交给安威玛尔的德南·弗卡特，现在我终于想起来该把东西送过去了！但是我肯定没法在酒变凉之前把酒送给他！$B$B你看起来挺灵敏的，也许你能……这杯热酒只能保温5分钟，而且德南要的可不是冰镇热酒，所以你一定要赶快！安威玛尔就在这里的东北面，那个在山壁上凿出来的大洞里。$B$B不要忘了把我的杯子带回来！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (3366, '这块碎片透出异样的绿色光芒，虽然它完全是一块固体，但是却让人感觉好像有一股烟从碎片中冒出来。你情不自禁地注视着这块水晶的深处，这时你突然觉得这其中必定包含着许多曲折的故事。\r\n\r\n也许你应该去棘齿城看看那里有没有人知道这块碎片的来历。 ') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (3373, '当你接触宝石的时候，一个雄浑的声音回响在你的脑际。$B$B“凡人，请聆听我的请求。我是绿龙军团的伊兰尼库斯，这座被诅咒的神庙的守护者。我的任务是阻止这些巨魔召唤出上古的邪神，但是现在看来，我失败了。我把我的精华力量注入了这块宝石中，我能感到自己对梦境的控制正在陷入混乱。请你帮帮我——把这块宝石放入我的巢穴中，让那里的魔法净化我心智中的污点，那样我才能够安息。”') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (3374, '你碰触了一下誓言石，伊萨里奥斯的声音通过这块石头直接和你进行对话。$B$B“一旦你拿起誓言石，就表示你会帮助我，并且准备帮助伊瑟拉的绿龙拯救伊兰尼库斯的灵魂。我们所要做的第一件事情，就是将禁锢着伊兰尼库斯自由心智的宝石交给我。”$B$B“快一点吧，$N，我们要共同努力来拯救一个值得拯救的灵魂。”') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (3377, '你愿意帮我的忙吗？无论怎样，请先听听我的故事吧。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (3454, '现在，火炬必须与它的拥有者建立联结。拿起火炬，$N。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (3482, '这个盒子的表面已经非常老旧了,因为它他酸中泡了很久了--它一定在那只巨大的秃鹫胃里呆了很久,$B$B把盒子翻过来,在它底部有个符记,在这符记下面写的是:“Kr..el Ko.l..ard ”') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (3502, '嗯，见识了你的贪婪之后，我感到恶心。$B$B不管怎样，我可不会跟你的贪欲纠缠不清。$B$B你每交给我一块有瑕疵的德莱尼水晶碎片，我就给你更多的垃圾。我的垃圾都被你收走了。在德拉诺，我们称这种情况为“双赢”。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (3702, '你愿意听听黑铁矮人的简要历史吗？') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (3861, '“咕咕嘎……咕咕嘎……咕咕！$B$B咕咕嘎……咕咕嘎……咕咕。”$B$B小鸡抬头看着你，然后伸出爪子探到地面上。你认为它是在拼写某个单词，但是又不确定是什么单词。S-A-L-D-E-A-N…C-o-o-C-e-l-y…是指萨丁农场吗？在你发出询问之前，小鸡转过身子，做它自己的事儿去了。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (4004, '你杀了我的丈夫！我的孩子诞生之后将会没有父亲。$B$B<茉艾拉公主直指着你。>$B$B我向你保证，这个孩子会成为铁炉堡的下一任统治者。你和你的同类将会因为今天的所做所为而付出代价。$B$B<你认为茉艾拉公主也许是受到了索瑞森的法术影响才变成这样。>$B$B让我独自留在这里，$R。你的酋长一定正在急切地想要知道他管闲事的结果。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (4083, '鬼魂之杯飘在空中,缓慢的时起时落...就像一个濒死的心脏.') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (4265, '当你触及虫茧时，虫茧裂开了一个小口，里面有一个暗夜精灵，他居然还活着。虽然他处于深度昏迷中，但看起来并没有缺胳膊少腿。当你帮助他从虫茧中时，他惊醒了过来。$B$B“感谢艾露恩——你救了我的命，朋友！我……我是拉斯卡尔。我被这些虫子麻痹，并被封在这只虫茧里。你能帮我逃离这儿，然后去羽月要塞报告一下我已经脱险的消息吗？我没事，但我们必须离开这儿，要快！”$B$B看起来你已经找到了失踪的信使！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (4361, '你必须把这个消息带给麦格尼陛下，$N。他会知道接下来该怎么做的！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (4451, '这把小小的黄铜钥匙看起来可真简单……它唯一与众不同的地方是刻在钥匙头部的一句话：$B$B“黑铁厕所——请勿复制。”$B$B你完全不明白这是什么意思，也不明白这钥匙是干什么用的。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (4513, '我需要更多的样品，$N。但是——我不知道怎么搞到那些——嗯，纯净的样品，不过什么是纯净的样品呢？我也不知道。你拿来的这些都是已经被腐化的……就好像整个费伍德森林一样。这让我意识到一个重要的问题：看来软泥怪会适应周围的环境。我需要一些未经污染的样品以证实这一点。但是哪里有呢？哪里？！$B$B啊！$N，拿着这些容器，如果你找到未被污染的软泥怪，就把它交给我。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (4542, '勇敢的旅行者，半人马已经加强了对这个地区的攻势。乱风岗必须马上得知这个新的麻烦！到东南方的乱风岗去，找到峭壁卫兵图林·长角，把这个十万火急的消息通知给他。$B$B多加小心，避开附近的恐怖图腾氏族……他们最近对我们有一些很奇怪的举动。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (4601, '这个装置屹立于那些竭力保护房间的侏儒中，装置上有一块小金属牌，上面写着“超级清洁器5200型”，还有一段文字：$B$B：“污垢和残渣让你的东西看起来污秽不堪？超级清洁器5200型会使它重现光芒！将你想要清理的物品放入清洁器中，然后向槽里投入三枚银币。稍候片刻，你的珍宝就会重新变得洁净而耀眼！”') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (4602, '这个装置屹立于那些竭力保护房间的侏儒中，装置上有一块小金属牌，上面写着“超级清洁器5200型”，还有一段文字：$B$B：“污垢和残渣让你的东西看起来污秽不堪？超级清洁器5200型会使它重现光芒！将你想要清理的物品放入清洁器中，然后向槽里投入三枚银币。稍候片刻，你的珍宝就会重新变得洁净而耀眼！”') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (4641, '你终于长大啦，$N……你可以以部落的名义参加战斗了，为酋长的荣誉而战吧！$B$B嗯……$B$B<卡尔图克打量了你一番。>$B$B你会很出色的。$B$B毫无疑问，你的目标是找到一条巨龙或是一个恶魔，然后赤手空拳地打败它，但是从比较弱的对手开始可能是个比较明智的选择。$B$B<卡尔图克笑了起来。>$B$B去向高内克报告吧，他可以为你这样的年轻$C指派一项适合你的任务。你可以在西边的大兽穴中找到高内克。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (4766, '我的一个手下——玛亚拉·布莱特文被派到燃烧平原去调查索瑞森废墟。在那座被摧毁的城市里，黑铁矮人也许隐藏了什么有价值的东西……能放在我的家族博物馆里的东西。$B$B玛亚拉说她发现了一些东西，不过一时半会还拿不到它，那东西不在索瑞森，而是在黑石塔里。$B$B我不清楚具体的细节，不过如果你感兴趣的话，那就去燃烧平原跟玛亚拉谈谈吧。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (4771, '我已经将黎明先锋放到你拿来的那个装龙蛋的容器里了。你的任务是把它带到通灵学院去。$B$B亡灵法师维克图斯在那儿向一群天灾军团的学者传授知识……把黎明先锋放在名叫观察室的房间里,它会自动攻击房间里面的亡灵，如果运气好的话，它就能一举毁掉他们！$B$B这样一来，杀死维克图斯就不是问题了。你明白了吗？') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (4783, '下一件必需的材料只有在石爪山西面的凄凉之地才能找到。$B$B在大灾变之后，这片区域仍处于混乱之中。你的力量和智慧都将在此得到考验——你将面对满怀仇恨的生物，以及可怕的燃烧军团。$B$B到凄凉之地的东北部去寻找怨怒萨特，取回它们的血。然后从玛诺洛克集会所的次级地狱火身上弄到一块次级地狱火石。$B$B我们将在制作披风的过程中用到这两种东西。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (4841, '$N，现在我委托你去消灭那些半人马，让他们感受我们的怒气。进攻乱风岗北面的半人马营地！让怒火指引你的武器！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (4881, '牛头人卡纳提·灰云胆敢在千针石林建立营地，简直是胆大妄为。我们必须杀了他，铲除他的营地，消灭他的所有同伴。我们将在升降梯西南方的小岗哨中会合，然后出发。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (4983, '把这份报告交给雷克斯洛特。它可以让我恢复好名声，并且肯定会让K.E.F.在对付这些兽人时占据战略上的优势。$B$B跟你一起回去？我有太多的工作要做。快走吧，他们急需这些报告！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (4986, '牛头人德鲁伊那毫无生气的手紧紧地抓着一根看上去极为结实的橡木枝，树皮上刻着一些德鲁伊教派的文字。$B$B当你握着这根树枝时，你发现原本应该冰冷的树枝摸上去却非常温暖。巨树泰达希尔的画面清晰地浮现在你的脑海里，然后是达纳苏斯。“塞纳里奥议会”这几个字也涌到了你的唇边。你现在很清楚要把这根树枝带到哪儿去了。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (4987, '牛头人德鲁伊那毫无生气的手紧紧地抓着一根看上去极为结实的橡木枝，树皮上刻着一些德鲁伊教派的文字。$B$B当你握着这根树枝时，你发现原本应该冰冷的树枝摸上去却非常温暖。莫高雷地区的雷霆崖的画面清晰地浮现在你的脑海里，然后是达纳苏斯。“塞纳里奥议会”这几个字也涌到了你的唇边。你现在很清楚要把这根树枝带到哪儿去了。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (5021, '“在我被困在这里之前，这个包裹一定得送……送出去！”$B$B一个惊恐的女人的哭声在这所房子里穿梭回荡。你看到一个女人的灵魂瑟缩在楼上的角落里，看上去她并不完全熟悉周围的环境，她只是隐约地感觉到了你的存在。$B$B“你是来帮我送包裹的吗？趁事情还没有变得更加糟糕……求你了，帮帮我！我本来是要骑马离开这里的，包裹应该还在我的马旁边……是不是已经太迟了？”') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (5051, '这个可怜的灵魂在继续喃喃自语：$B$B“我好冷，约翰，把你的护符给我，这样我们就可以在一起了！快点，约翰，要在瘟疫把我们变成可恶的野兽之前！我看不到你，约翰……但是我知道你就在附近。我能感觉到你在我身旁……”$B$B也许如果你能找到另一半护符并把两半拼凑起来，就能组合成詹妮丝·费尔斯通的灵魂寻求的东西。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (5481, '主人需要草。我们的手太大，没有办法捡。你可以帮我们，我们不伤害你。我们需要阴暗草。这里有许多这样的草，路边也有。$B$B拿到草之后，把它交给布瑞尔墓地的主人，霍兰德。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (5534, '什么？！什么？！$B$B你还不满足？你知道那些炸药有多贵吗？它们可以卖到……哦，算了。好吧，你想要赚点钱？做生意应该是这样的：首先你要证明自己是个有价值的雇员，然后你会因为勤奋工作而被奖励。$B$B如果你是个“有价值”的雇员，那么就到埃达拉斯废墟去，帮我把那些血精灵正在寻找的符石给拿回来，显然你得去跟废墟中的纳迦们打交道。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (5723, '在奥格瑞玛城的地下，那些被称为穴居人的生物正在从充满岩浆的管道深处源源不断地涌出来。玛加萨心怀仁爱，试图与这些生物和平相处，但是他们却对她派出的外交官大开杀戒。她绝不允许牛头人受到这样的待遇，现在她将穴居人看作是整个部落的威胁。$B$B她希望你在穴居人毁灭部落之前消灭他们——找到怒焰裂谷，把他们全都杀掉。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (5742, '你干得很好，朋友。休息一下，然后听听我的自我介绍。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (6135, '到现在为止，你已经完成了我分配的所有任务，虽然并不是非常及时。$B$B我想你认为自己已经准备好接受真正的挑战了。很好……很好，蠢货，也许你需要一些更加棘手的任务。$B$B苍白的恶魔蝙蝠——暗翼蝠——就在这里的北方游荡。消灭它，把它的毛皮给我带回来，你会得到奖赏的。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (6283, '限制血怒鹰身人的数量还不够，要解决它们的问题，唯一的方法就是杀了它们的领袖，血怒撕裂者！$B$B她是那些邪恶生物的女王。只要杀了她，鹰身人的数量就一定会减少。$B$B回到焦炭谷去，你可以在西部的山岭中找到她。她可不好对付，但是如果你完成这个任务的话，我也会给你可观的奖励。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (6523, '谢谢你救了我！我们必须赶快离开，不然很快就会被发现的。请护送我回到阿帕拉耶营地去。到了那里，我就知道回去的路了。$B$B我的父亲玛卡巴·扁蹄得知我安全回家之后一定会很高兴的。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (6564, '皱巴巴的便笺上潦草地写着：$B$B“对，通知所有的祭司把水晶带到我这里来，水元素的灵魂蕴含其中，它们能够很好地帮助我们的水占师进行召唤仪式。$B$B通过控制水晶中的力量，我们就可以取悦阿库麦尔。终有一天，我们会获得足够的力量，把阿库麦尔带回到我们身边，整个世界都将要迎接一个伟大的新时代！一个由上古之神统治的时代！”') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (6983, '有有有有个名叫格林奇的家伙，他他他偷走了我们的礼礼礼品，$N。要小小小心！是他让我在这冰冰冰冰天雪地里乱作一团！$B$B如果你要跟跟跟他对抗的话，你就就就需要帮助。我看到他在雪雪雪怪出没的地方徘徊，他他他他肯定就在那附附附近！找找找回礼品，$N，带带带回铁炉堡的烟林牧场零售店去，告告告诉他们想办法给我解冻！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (7043, '有有有有个名叫格林奇的家伙，他他他偷走了我们的礼礼礼品，$N。要小小小心！是他让我在这冰冰冰冰天雪地里乱作一团！$B$B如果你要跟跟跟他对抗的话，你就就就需要帮助。我看到他在雪雪雪怪出没的地方徘徊，他他他他肯定就在那附附附近！找找找回礼品，$N，带带带回铁炉堡的烟林牧场零售店去，告告告诉他们想办法给我解冻！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (7181, '雷矛部族并不是我们在这个地区唯一的威胁，士兵。我们在这座山谷中面对的是两股敌人的攻击——野蛮而原始的冰斧巨魔也在和我们进行争斗。$B$B它们的领袖是血怒者科尔拉克，一个残酷而又狡猾的混蛋。$B$B如果能干掉他，那对于整个冰斧巨魔族来说都会是一次致命的打击。杀了科尔拉克，你就将获得奖励！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (7282, '他一定要摆脱他正在遭受的痛苦，士兵！他根本不知道自己在干什么，他已经成为了女妖之王的傀儡。$B$B现在就出发，穿过战火纷飞的战场，深入霜狼氏族的腹地。找到我的兄弟，杀掉他。这样他的痛苦才能结束。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (7383, '然而泰达希尔并不是一切都尽如人意。范达尔·鹿盔对于世界之树的计划正如他自己所希望的那样一步步展开了，但是还有一个小问题，这个问题或许会给泰达希尔带来一些麻烦。$B$B不过我不打算介入此事。你得去一趟最后一口月亮井，就在这里西北面的神谕林地里，就在神谕之树的树干下面，那是我们的第一口也是最强大的一口月亮井。在那里灌一瓶水，然后回来向我报告。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (7402, '根据诺雷格·雷矛中尉的命令，所有雷矛部族的士兵都要杀掉$g他:她;\r\n在战场上看到的每一个兽人。$B$B带回兽人的獠牙来作为完成任务的证明。$B$B另外别忘了戴手套。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (7622, '你必须完成我没有能够做到的事情：拯救那些未能逃出斯坦索姆的农夫。$B$B他们将向着光明前进，你的职责就是保证他们的存活。如果过多的农夫倒下，那我们仍将继续被诅咒，而你则会可耻地失败。$B$B你所学到的每项技能、每句祷言和每个法术都会经受考验。愿圣光护佑你，$N。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (7640, '我在香炉中放了一撮东瘟疫之地恐惧谷中的腐烂泥土。你可以用它来找到出现灵魂异动的区域。寻找绿色的光芒渗入地表的地方——那里就是物质世界和灵魂世界结合的边缘，在那里用香炉将邪恶的灵魂召唤出来。$B$B当你对那里的灵魂进行了足够的审判之后，就可以继续下一步了。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (7721, '如果我想要在被遗忘的海岸这里开一家可以正常经营的工程学商店，那我就必须先解决这些讨厌的元素生物——它们简直是无法无天！$B$B幸运的是，我发现这些元素生物身上有一种可以给我的超级压缩器提供动力的理想材料——我希望你可以好好地教训它们，拿到我要的东西！把它们身上的水元素核心给我拿来！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (7729, '监工斯克兰格正在寻找一些优秀的冒险者深入灼热峡谷。$B$B如果你对此感兴趣的话，就到灼热峡谷去，杀死你见到的所有黑铁工头和黑铁奴隶贩子。$B$B当你全身都沾满那些家伙的鲜血之后，就回到监工斯克兰格那儿去。$B$B你自己应该知道什么叫“全身沾满他们的鲜血”，所以别问来问去的。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (7787, '你已经击败了逐风者，那么，拿上风吻之刃，让那个叛徒德米提恩用你提供的材料唤醒雷霆之怒吧。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (7907, '你现在已经收集到了野兽套牌的所有卡片，与前8张的背面图案完全一样的第9张卡片神秘地出现在你手中。在这张卡片上写着，“将这些卡片拿到暗月马戏团去，你就将获得奖励。”你听说暗月马戏团每过几个月就会路过一次莫高雷和闪金镇，因此你也许需要等待一段时间才能看到他们。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (7927, '你现在已经收集到了入口套牌的所有卡片，与前8张的背面图案完全一样的第9张卡片神秘地出现在你手中。在这张卡片上写着，“将这些卡片拿到暗月马戏团去，你就将获得奖励。”你听说暗月马戏团每过几个月就会路过一次莫高雷和闪金镇，因此你也许需要等待一段时间才能看到他们。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (7928, '你现在已经收集到了督军套牌的所有卡片，与前8张的背面图案完全一样的第9张卡片神秘地出现在你手中。在这张卡片上写着，“将这些卡片拿到暗月马戏团去，你就将获得奖励。”你听说暗月马戏团每过几个月就会路过一次莫高雷和闪金镇，因此你也许需要等待一段时间才能看到他们。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (7929, '你现在已经收集到了元素套牌的所有卡片，与前8张的背面图案完全一样的第9张卡片神秘地出现在你手中。在这张卡片上写着，“将这些卡片拿到暗月马戏团去，你就将获得奖励。”你听说暗月马戏团每过几个月就会路过一次莫高雷和闪金镇，因此你也许需要等待一段时间才能看到他们。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (7937, '“东谷的财宝正等着你。”$B$B你抚摸着手中的塔罗牌，感到一丝暖意。你紧紧地握住它，眼前浮现出艾尔文森林冬谷伐木场的影像。你专注地观察着，发现马厩附近有一堆干草。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (7938, '“死亡矿井中的财宝正等着你。”$B$B你抚摸着手中的塔罗牌，感到一丝暖意。你紧紧地握住它，眼前浮现出位于西部荒野月溪镇的死亡矿井的影像。你专注地观察着，发现蜿蜒的道路尽头是一道发光的门……通往矿洞中心的门。你穿过大门，不知从哪儿冒出一个奇怪的箱子。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (7944, '“哀嚎洞穴中的财宝正等着你。”$B$B你抚摸着手中的塔罗牌，感到一丝暖意。你紧紧地握住它，眼前浮现出了位于贫瘠之地十字路口西南方的一处洞穴的影像。你专注地观察着，发现蜿蜒的道路尽头是一道发光的门……通往洞穴中心的门。你穿过大门，不知从哪儿冒出了一个奇怪的箱子。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (7945, '“灰月洞穴外的财宝正等着你。”$B$B你抚摸着手中的塔罗牌，感到一丝暖意。你紧紧地握住它，眼前浮现出莫高雷灰月洞穴的影像。你专注地观察着，发现洞穴入口附近有一块树桩。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (8072, '卡瓦萨尔是一位声名远播的赞达拉狂妄者。相传他首次对敌作战时穿着一件织入了“疯狂之纹”的特殊衬肩。他以极快的速度挥舞着两把匕首，全身都处于衬肩和匕首的双重保护之下，滴水不漏。今天，狂妄者把衬肩看作自己在整个部族中的地位的标志。$B$B把权力珍宝交给我，我就把衬肩送给你，它会令敌人闻风丧胆。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (8121, '$N，随着阿拉希盆地的战事进展，你的事迹已经传遍了战场。你的所做所为让我确信你一定可以完成现在我要给你的任务。$B$B现在是给阿拉索联军一个信号的时候了。我们将会向他们展示，他们在阿拉希盆地的防守是多么脆弱。我们要通过同时占领阿拉希盆地的四个战略点来让他们明白这一点。$B$B如果你可以完成这个任务，$N，你将赢得污染者的尊敬。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (8227, '在散落的鱼饵和滚轴之中是一卷光滑的测量卷尺。卷尺上的标签写着：$B$B“纳特·帕格，尘泥沼泽。”') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (8251, '艾萨拉的血精灵正在寻求一种碾磨他们获得的魔法物品的方法，通过这种方法所获得的粉末与普通的分解法术所获得的材料是不同的。$B$B当我派我的学徒去交换这种粉末的时候，血精灵们毫不犹豫地把他干掉了。因此，他们必须付出代价。$B$B谈判结束，$N。找到艾萨拉北部的这些血精灵，然后使用更具“说服力”的方法来获得他们的那些闪光尘埃。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (8286, '当他出现时，我已经奄奄一息，濒临死亡。他对着我受伤的身体呼了一口气，便耐心地等待着时间的沙砾清理我的伤口。$B$B他说，“如果必须这样的话，你将永远活下去。”这样，我成为了一名守望者。$B$B看那片沙漠，第二场战争就要来临了。你必须找到青铜龙的栖身之所。去时光之穴看看主人回来了没有。我必须确认这一点才能有所行动。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (8305, '你已经知道了故事的一半，现在是了解另一半的时候了。我和我的下属的行事方法大相径庭。返回希利苏斯，去甲虫之台吧。别害怕你所见的事物……别忘记你学到的东西。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (8465, '除了来自南面的死木熊怪的堕落威胁之外，东面的冬泉熊怪同样也同样是我们的心头大患。如果你愿意继续帮助我们的话，就去和要塞另外一头的萨尔法谈谈吧。沿着左边的这条路一直走下去。$B$B你要小心，如果我里面的兄弟对你表示敌意，他们也许会攻击你。尽快通过那里，避免纠纷。你每杀死一个木喉熊怪——即便是出于自卫——都会极大地降低你在木喉熊怪中的声望。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (8470, '你找到了一根死木仪祭图腾。图腾本身没有什么雕刻的痕迹，但是一种让人绝望的感觉却在其中不断地散发。如果有什么东西导致了死木熊人的堕落的话，那么这件东西貌似就是罪魁祸首了。$B$B木喉要塞中的某个熊人一定会用它……当然，你首先需要赢得和他们交谈的声望。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (8550, '据说每一代人都需要面对一次决定性的试炼。恐怕安其拉之战将是我们这一辈人所要经历的残酷考验。我们要做好准备，了解自己的实力究竟如何。我在这里志愿帮忙收集宁神花，我们会用它们制作战争所需的药水。我希望你来这里是为了帮助我们，如果是这样的话，那么我需要你帮我带回大量的这种草药。你会帮助我吗，牧师？') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (8552, '这条精致的腰带的边上刺着两个字母“HS”。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (8584, '如果说我有一些原则是你应该了解的，那就是：永远不要管我的闲事！我所做的事情都是你无法理解的。比如说：你知道精神电能整流器是什么吗？显然你不知道！这就是为什么我来负责我们的项目规划，而你负责满世界跑腿。$B$B我之前说过，如果你想继续下去的话，那么我们需要一只500磅重的鸡。$B$B到加基森去跟迪尔格·奎克里弗谈谈——他知道如何让你找到合适的品种。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (8585, '传说菲拉斯恐怖之岛的那群名叫奇美洛克的奇美拉族群是最鲜美多汁的食物！现在它们之中出现了一个首领，它的肉在经过巧妙的烹调之后可以变成一盘极品大餐！$B$B去恐怖之岛杀掉拉克麦拉，然后把它的肉带回来。这就可以满足那个侏儒了，而我则需要你带一些奇美洛克的腰肋肉给我。$B$B我会给你那500磅的肉鸡和一些别的什么东西作为交换。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (8607, '我相信你来找我是想要帮助我收集东西？很好！不管怎么样，我接受所有的帮助，并且我需要你帮忙去收集厚魔纹绷带。最好是新做的，但不是必须。把它们交给我，$C，我会给你适当的奖励的。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (8620, '我就知道，我最大的敌人，维维尔博士又开始玩他那老一套了！现在，由于你在冬泉谷的失败，维维尔把我的书给毁掉了！你现在还怎么拯救世界，大英雄？$B$B我收集到的仅存的《龙语傻瓜教程：第二卷》被撕成8份，散落在世界各地！如果你可以收集到这些遗失的章节，那么就用这个魔法书封面把它们合在一起，然后给我带回来。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (8729, '我和你说过坏消息了吗?它的名字叫巨齿鲨:100尺长，死亡和毁灭的化身。我想我忘记和你说这个了。$B$B根据我的超级精准千里眼提供的讯息，你会在艾萨拉的海岸找到最合适使用这个浮标的地方，就在风暴海湾。$B$B你要寻找一个大漩涡，就是附近都是沉船的地方。$B$B另外，我希望你带上你的朋友。$B$B如果你成功的话，那么把权杖碎片带给安纳克罗斯。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (8736, '我们必须尽量控制伊兰尼库斯，我们要让他获得救赎，而不是摧毁他。$B$B泰兰妲已经在赶来帮助我们的路上了。我们必须守住巨龙的攻击，保护永夜港免遭伤害。$B$B做好准备!你和你的盟友是我们唯一的希望。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (8790, '亚雷戈斯认为，在一定情况下，因上古之神和他们的仆从之间的冲突而产生的元素也会对他们本身造成致命的威胁。凡人，我指的是源质。$B$B将其拉帝王徽记和这种元素交给我，我就能为武器注入巨大的力量。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (8904, '这场突然爆发的爱情流行感冒一定有问题。这可真讨厌，我们的防御力量被大大削弱了！这是对我们安全状况的一个重大威胁。$B$B那么多人都染了这种病，整天做些奇怪的事，这就已经很糟糕了。更糟的是，这种情况现在已经蔓延向了我们的卫兵，本来他们应该绝对免疫这类诱惑的。$B$B到幽暗城的卫兵中间去打探打探，给我抓一个已经走火入魔的卫兵出来。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (8946, '我的爱人在赶来营救我的途中不幸丧命，这是多么悲惨的命运。不过既然你说自己有跟灵魂交谈的能力……$B$B把这个小盒子交给他，告诉他我过得很好。让他的灵魂不要继续在世间游荡了，我已经无法承受内心的伤痛。$B$B再见，$N。你心肠真好，我会永远记得你的。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (9136, '我会为那些进入纳克萨玛斯宫殿的勇士们打造一套名为梦游者的护甲。他们能为我提供大多数材料，但是我还需要来自艾泽拉斯某种植株的蛮荒之叶。$B$B你或许认为这项任务太过容易，但是蛮荒之叶是打造梦游者套装的必备材料。$B$B如果你能完成任务，我还会让你挑选一枚银色黎明徽记或是十字军徽记作为奖励。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (9200, '工匠文书的持有者在完成订单后可以挑选一枚徽记作为奖励。$B$B订单AL-473：$B$B10份特效法力药水。$B$B所有的成品应送到东瘟疫之地圣光之愿礼拜堂的马队管理者布鲁斯·石锤处。$B$B物品若有任何损坏，订单无效。$B$B银色黎明物资官员梅兹') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (9208, '赞扎可以使用适当的材料对你的装备进行古老的魔法增强处理！你听说过野性戒卫吗？啊，你当然没有听说过。你满脑子都是那些低级的暗夜精灵的魔法。$B$B给我拿来一份暗夜精灵的秘药，我也许能重新为你附魔。去吧，我会把野性戒卫作为奖励送给你的。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (9209, '赞扎可以使用适当的材料对你的装备进行古老的魔法增强处理！你听说过野性戒卫吗？啊，你当然没有听说过。你满脑子都是那些低级的暗夜精灵的魔法。$B$B给我拿来一份暗夜精灵的秘药，我也许能重新为你附魔。去吧，我会把野性戒卫作为奖励送给你的。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (9210, '赞扎可以使用适当的材料对你的装备进行古老的魔法增强处理！你听说过野性戒卫吗？啊，你当然没有听说过。你满脑子都是那些低级的暗夜精灵的魔法。$B$B给我拿来一份暗夜精灵的秘药，我也许能重新为你附魔。去吧，我会把野性戒卫作为奖励送给你的。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (9367, '仲夏就要来了！$B$B每一年，按照传统，各大城市里都会选出护火者来照看我们城中的篝火。当火焰燃烧在艾泽拉斯世界的各处时，我们就可以通过这种世上最热诚也最明亮的事物向夏天这个季节表示敬意。$B$B事实上，若你不介意的话，我有个任务要交给你。我还不知道是否所有城市里的火焰都已经点起了。到各大城市去吧，让那里的火焰温暖你的身躯，当然，首先要确认它们已经被点燃了！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (9388, '今天，全世界上各处有无数的火焰在熊熊燃烧着，$N。那些最狡诈的火焰往往都是绿色的，如果不小心照看的话，它们很快就会灭掉。为我们的护火者确认一下卡利姆多上的几处翡翠烈焰是否还在燃烧着，好吗？$B$B你能在贫瘠之地的棘齿城、黑海岸的主宰之剑、银翼岗哨附近的桥，以及石爪山尘风峡谷的路旁去寻找这样的篝火堆。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (9389, '仲夏火焰节的传统就是建起一座金字塔状的火焰。有些人说绿色的火焰是最好的，因为它们最难以维持燃烧，而且有着如此美丽的颜色。$B$B你去为我们的护火者确认一下东部王国的绿色火焰是否都在正常燃烧吧。它们分别座落于湿地的丹莫德，银松森林的焚木村旁，西部荒野能望见灯塔的悬崖边，以及希尔斯布莱德那座被废弃的哨塔边。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (9422, '不久以前，我们开始吸收希利苏斯沙漠中水晶资源的力量。过去，开采过程中唯一遇到的危险不过是那些以沙漠为家的野兽，以及沙漠的干旱和炎热。$B$B但现在联盟似乎也开始争夺这些我们先发现的东西了。现在看来，我们正在展开一场竞赛，双方都想要彻底占领这些资源，并防止它们落入对方的手中。$B$B我需要一切可以依靠的力量，希望你能帮助我。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (9664, '欢迎来到瘟疫之地，$N。正如你所知，被遗忘者和他们的盟友控制着西边的土地，并与我们互相抗衡。联盟的指挥官们决定在东部建立数个新的据点，以加强我们在敌人外圈的包围网。$B$B洛丹伦战争后期被废弃的那些哨塔正好用来达成这个目标。不过，这些地方都非常危险，我们需要你的帮助。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (9665, '被遗忘者的密探发现，最近联盟试图在东瘟疫之地利用那些废弃的哨塔建立一系列的据点。$B$B现在，情况非常急迫，我们显然不能允许他们在我们东部边界的一系列重要地点建立这样的据点，因此我们必须击退联盟的这次进犯，并把他们赶出那些已经被占据的哨塔，同时，我们还要将那些哨塔占领下来，以应对以后的进攻。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (20001, '这是我以前从未见过的，$N。$B就像光的本质从这个球体中散发出来，灰烬使者从天灾军团的魔爪中解放出来后，留下了一件奇怪的东西。$BI真的抽不出任何时间来帮助你。即使恐怖堡垒被攻陷，我们还有很长的路要走。虽然大巫妖已经被打败了，但我们还没有找到他的护身符。$B银色黎明一片混乱，伤亡惨重，我们其余的人都累坏了。虽然你在这里找不到帮助，但我知道把你送到哪里，我相信他能帮上忙。$B在这里寻找提里奥·弗丁，在西边的东瘟疫之地。$B我真的很抱歉，祝你好运。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (20002, '<提里奥默默地检查了一会儿球体>$B以圣光之名！$B这个纯净的本质，这个光的原始能量，这绝对是亚历山德罗斯本人！$B他休眠的灵魂变成了这个球体，但目的是什么？$b我无法理解这一点，但也许我们可以试着唤醒他。我不确定这里的用词是否正确。但我们怎么能做到呢？$B熟悉的东西可能会起作用。$B听$n。赛丹·达索汉是最早的圣骑士之一，我和亚历山德罗斯的朋友，在某个时候他疯了。这在当时被证明是由于某种恶魔的影响。$B当雷诺杀死他的父亲时，赛丹拿走了灰烬使者的披风作为战利品。$b同时，如果我的信息是正确的，瑞文戴尔男爵骄傲地穿着亚历山德罗斯的斗篷作为嘲弄。$B你的任务是冒险进入斯坦索姆，找到这些曾经属于灰烬使者的物品。带上宝球，我相信你会有反应的。在此期间，我会努力理解这种情况。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (20004, '亚历山德罗斯深深地凝视着你的眼睛。>$B所以，把我从永恒的不死中解放出来的人，也是传达我的信息的人。灯光指引我走这条路。$B听好了，$n.我是亚历山德罗斯·莫格莱尼，灰烬使者。曾经是现在卑鄙的血色十字军的一员。$B一个圣骑士，一个丈夫，一个父亲，现在只不过是一个鬼魂。我的精神是不安的，在我的正义得到满足之前，我不能也不会继续前进。是的，你已经听到了，这不是圣光的正义，而是灰烬使者的正义。$bi我愿意向你提供信息，这些信息将让你成为伟大事业的一部分。这一信息将彻底终结血色十字军。是的，令人惊讶的是，你还没有结束它们。$bi向在战斗中打败我的人，向解放我灵魂的人，祈求谦卑。向灰烬使者鞠躬，让我感觉到我在我们世界的凡人中的传奇还没有消失。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (20005, '在我离开尘世的躯壳之后，光向我展示了许多不同的东西。$B我的生活，我的使命，我的未来。$b我现在全部的希望就是终结血色十字军。$b布丽奇特·阿比迪斯已经撤退到血色修道院。她下令招募更多的人，并设计了一种新的混合物，可以立即消灭不死生物。$B从她决定躲在房间里冥想的那天起，她的计划似乎就没有生效。你看，光有它自己的路径，对我们来说很神秘。她是为了一个愚蠢的目的而拥有更多的权力。在提尔之手的东边，血色十字军准备向北进发，等待他们的领袖回来，这样他们就可以开始了。$B但在她冥想期间，一股黑暗力量渗透进了修道院，并永远折磨着已经狂热的头脑。$B他们再也看不出活人和亡灵之间的区别了。他们对暗影魔法的使用来自一种不同的力量，一种可以等同于光本身的力量。$b是时候决定你是否准备好证明自己的勇气了。$B纳克萨玛斯确实是一个威胁，但这里的力量可以很好地超越那里。你准备好了吗$n？') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (39983, '你想让我释放囚犯？尽管我很感激你的慷慨捐赠，但我恐怕不能这样做！大酋长不会对不听从命令的士兵手软。我受到荣誉的约束，必须履行我的职责。我们士兵忠诚而勇敢。我什么都不怕。也许除了大蛇，我讨厌蛇。幸好这里没有。等等，我们在说什么？我忘了。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (39984, '我自由了！谢谢你，我的朋友。恐怕我目前没有什么可以报答你的，因为大酋长的暴徒拿走了我所有的东西，但我的商业伙伴马洛斯·卡托斯会补偿你。来到我们在藏宝海湾的新办公室见我们吧，那是大洋彼岸的自由贸易港口，我们在那里远离政府的过度干预。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (39986, '你能相信执掌暴风城的暴君官僚们做了什么吗？他们宣布贝壳币的投资要受到征税！这太可恶了！在这些规定下，我们不可能继续在这座城市经营。必须采取一些行动！你愿意帮助我们改变他们的想法吗？去暴风城堡，与那里的立法者交谈。通过让他们尝到贝壳币带来的繁荣，帮助他们朝着正确的方向迈进。五金币应该足够了。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (39989, '这太可恶了！我不在乎那个酗酒的主教或者一些贪婪的领主对你承诺了什么。暴风城王国不是用来出售的！我会稍后处理那些腐败的家伙。我不会让暴风城的市民成为你们金字塔骗局的受害者。去告诉你的资助者，法律已经生效了。他们不能再利用易受骗的人们的希望和绝望了。现在离开我的视线。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40004, '我们有危险，莫妮卡。敌人正从四面八方侵入温特莱克斯的领地。如果我们要生存，我们必须反击。奥特兰克属于我们，而不是格诺人，矮人或者兽人！$B$B通过攻击东边的野爪营地来证明你是一个真正的战士。杀了他们，我会给你很大的奖赏，配得上冠军。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40005, '我喜欢侏儒。又嫩又好吃。我正在为部落的其他人做煮侏儒炖菜，但我没有主料！拿着这根绳子，去给我找个活的侏儒来。首先要确保它的血，这样它的汁液才能流动，它的肉才能充分嫩化。砍！砍！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40006, '我饿得能吃下一整头牛。不幸的是，奥特兰克山谷没有奶牛。但最近一些球探发现了更大的东西。美味的牛头人在南方的兽人中疯狂地奔跑。如果你抓到其中一个，我们可以养活整个部落！你必须尽快去打猎，赶在牛头人离开之前。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40107, '$B$B启动解锁序列。$B$B板存在，正在扫描以进行项目验证。$B$B板身份验证完成，正在解锁大门。$B$B激活门卫迎接客人。 ') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40114, '时间到了。就像大地之母告诉我的那样。我们不知道我们会在奥丹姆发现什么，如果危险的派系试图进入。那么我们就更有理由采取极端的预防措施。$B$bi敦促你避免我对主战派所犯的错误。在你离开之前，找到值得信赖的盟友，他们会陪你去星门。不知道在那里等待你和我的是什么。我会努力让我们的朋友安息。这是我为弥补我的错误所能做的最起码的事。现在走吧，愿风永远在你身后。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40115, '$B$B启动解锁序列。$B$B板存在，正在扫描以进行项目验证。$B$B板身份验证完成，正在解锁大门。$B$B激活门卫迎接客人。 ') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40120, '野生动物的入侵已经成为我和我妻子的一个问题。过去，我们与森林里的动物和平相处，虽然现在看来，我们必须时刻警惕我们的行动，并注意森林中跟踪的捕食者的眼睛。$B$B鬼爪特别麻烦，几天来一直在我们的房子里徘徊，寻找软弱的迹象。我没有给它们任何东西，但我担心某些东西可能会驱使野生动物以更具侵略性的方式行动。$B$B不管怎样，给我收集五张他们的毛皮。减少人数，这样他们就不会厚颜无耻地发动攻击。你可以在森林周围找到鬼爪狼。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40121, '该地区鬼爪狼的首领被命名为幽灵猎手。他是一头凶猛的野兽，在该地区领导着一群狼群，意图危险。如果要实现自然的平衡，就必须杀死野兽。$B$B你应该在法拉西姆湖西北和佐拉姆斯特兰德东南的山上找到他。祝你打猎好运。幽灵追踪者是一只聪明的野兽，直到今天我都不知道。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40122, '很久以前，我从艾萨拉的一位同事那里得到消息，说强大的能量正在抑制该地区的魔法。如果这样的威胁能够在达拉然附近形成，那么我们的大部分法术、魔法和保护都将失效。$B$bi希望你去那里旅行。评估这是否会威胁到达拉然本身，看看是否需要采取行动。你可以找到位于埃尔达拉斯遗址南部的法师布罗姆利，他在山脊线上扎营。找到他并得到答案。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40174, '好的伙计。到目前为止，你做得很好，但在离开这个烂港口之前，我们还有一些事情要做。如果我们想让这些白痴在面对血帆海盗时永远没有机会，我们也必须对他们的弹药做手脚。他说，我要给你一瓶“特殊”的水，你必须把你能找到的任何一桶炸药都倒进去。$B$B了解了？') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40213, '这条项链让我恢复了很多以前的力量。如果你在旅途中注意的话，你就会发现我的真实身份。现在你真正知道我是谁了，我们将朝着我的最终目标努力。$B$BI能够引导我的能量并找到腐败的源头。虽然我们可以很好地面对，并用我的项链的力量召唤它给我们，我首先要报复那些抛弃了对我的崇拜的人。$B$b祖尔哈祖曾经是一个我称之为家的地方，正是在那里，巨魔们称我为神。他们练习我的魔法，跟随我到世界的尽头。$B$B前往西北部的祖尔哈祖，杀死首领黑暗大师哈扎吉、冠军拉加齐和酋长沃赫佐。人们也应该受苦，从他们那里得到10个哈祖里护身符，它们将是很好的装饰品。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40225, '虽然我很感激这次送货，但我知道这意味着什么。我很久以前就承诺过要遵守协议。我希望他掠夺我给他的地区，以换取一些货物和信息。$B$B他正在寻找杀害杰德的凶手，就是前一段时间拆散我们老船员的那个人，现在他已经完成了他的使命，我也会这么做。我不是老鼠，我守信用。$B$B组织这次袭击来拆散我们的人名叫沃利·怀斯克拉克，他现在和那些辛迪加男孩混在一起，虽然我相信\'滑\'知道这一点。一旦你告诉“斯利普”这就是幕后黑手，他无疑会想要报复。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40253, '欢迎来到我的寒舍，我在这个塔尖上履行了我的职责，并将继续这样做。现在路石已经重建，我们可以开始让我们在该地区的存在更加广为人知。$B$B西南方向是辛玛洛神殿，坐落在埃达拉斯废墟中，目前居住着扭曲的纳迦。在辛玛洛神殿里，隐藏着他们永远不会发现的秘密，而我需要你去揭开。$B$B在神殿深处，你会发现一块独特的石头，上面刻着一种更古老语言的明亮符文。这块石头，被称为阿山石，当你看到它时，说出下面的“Tizah Ashan Dal\'asha”。这个魔法将再一次削弱延伸穿过艾萨拉的长而不活跃的魔网线。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40266, '我看到了很多东西，巨大的黑暗不仅笼罩着这个岛，也笼罩着我们周围的一切。我的人民听从了更强大力量的命令，心甘情愿地跟随它进入黑暗。在我们灭亡之前，我们只不过是棋子。然而，$B$B我确实看到了比痛苦更多的东西，我看到了高多什食人魔的预言家，他是我曾经的老朋友。也许是他可以提供一些智慧，或建议如何继续下去，也许是他，谁有答案。$B$B伯乌克先知在戈尔多什高地和他部落的其他成员住在一起，你应该在遥远的北方的拉匹迪斯岛上找到他。戈尔多什高地位于其西北侧。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40283, '它可能看起来不像，$C，但我们正处于战区之中。徘徊在森林中的上层精灵与纳迦发生冲突，原因我不明白，我也不想。我知道的一件事是，他们对我们的前哨基地是个威胁。他们现在可能会互相争斗，但不会永远持续下去。我们应该趁他们虚弱的时候出击。前往埃德拉纳特废墟。杀死纳迦，消灭上层精灵。告诉他们，血拳点是不可忽视的。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40289, '最后一件事，俺求你拜拜死人，你帮俺好多，所以俺请你替俺拜拜咱死掉的朋友。俺把这剑用心修好，要好久才能搞的和新的一样。$B$B来咱一起，念出死掉朋友的名字，这样他的灵魂就可以和他战士老伙计一起了。你也能把他的勇士精神传递下去。$B$B他叫\'塔克加·深仇\'。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40295, '我们来到艾萨拉是为了从军团的腐败残余中恢复这些土地。然而，我们在这里发现的与预期的不同。你看，年轻的$R，恶魔腐败不是这里最大的问题。$B$B大地在呼救。某种邪恶势力已经在门纳尔湖附近定居。它们耗尽了地球的精华，消耗了魔法和自然。纳迦或萨提尔没有那么强大，他们做不到。另一方面，蓝龙飞行。拜托，去看看门纳湖发生了什么，艾萨拉的未来可能就在你的手中。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40355, '海军上将告诉我，舰队指挥官菲尔拉伦从湿地挑选了一名无名的龙喉者作为训练对象，并最终将领导我们的一艘战舰，因为他在兽人战场上的经验丰富。我已经很久没有被人这么侮辱过了！讨我欢心，你愿意吗？$B$B艾隆帕就在菲尔拉伦身旁，你可以在蛮荒海岸的三艘船之一找到他。向他发起挑战，把他的头颅给我带来！$B$B鲜血与雷鸣，胜利或死亡。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40384, '我们的月亮井充满了艾露恩圣光的纯净泉水。它们不像第一口永恒之井那样被污染。$B$B它们将恢复高等精灵的法力，但永远不会让他们获得使其他人陷入疯狂的邪恶力量。$B$B我已派遣女祭司阿鲁娜莎以及我们的一些石匠和小精灵开始建造月亮井。$B$B阿鲁娜莎将留在那里，看守着这口并，教导高等精灵如何按照我们的方式使用它。$B$BAnde\'thoras-ethil，$N，再次感谢你们在菲拉斯所做的事。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40395, '你发现这本书的状况很糟糕。仔细一看，你认出了书名：《水手的大胃指南》。$B$B似乎这本书被水浸湿后又被太阳晒干，可以想象，它在发现不能再看后，已经被主人遗弃了。$B$B你翻开书的末尾，眯起眼睛看着眼前乱七八糟的东西，然后脑海中浮现出了一个名字，而且还是一个熟悉的名字：葛瑞森.') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40577, '我会继续在废墟周围寻找，与此同时，你应该回到克罗格那里，并告诉他我们的发现。$B$B我们在这里已经无能为力了$N。尽管这可能意义不大，但我还是感谢你的帮助，Lok\'tar。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40640, '<纳兹看了你给他带来的文件。>$B$B喔哦，好家伙，最棒的安德麦。$B$B我记得那些日子。没有什么比地精的本性更糟糕的了，$N。上面的人总是会把其他人累死，其他的人呢？他们想当皮鞭，而不是被鞭打。没有什么比这更糟的，不是没有，是没有什么比这更糟的。$B$B这就是为什么相比之下工会要好得多，我们大多数人或多或少都能平等地生活。在这里地精的本性也一样，只是换了种方式和方法。不管怎样，我有办法。$B$B我需要你做最擅长的事情，出去杀死目标，然后把东西带回来换钱，简单得很。$B$B在石爪山脉，它们被称作“愤怒的悬崖风暴”，是一种会发射闪电的巨大蜥蜴。我需要它们的鳞片来制作缩小射线，它们可以提供我所需要的绝大部分电力，至于剩下的部分，我会让一些“最著名”的工程师来制造。五个就够了！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40685, 'Lok\'tar，$r！你听说这个消息了吗？陈.风暴烈酒已经回到卡利姆多了！陈.风暴烈酒是建立和保卫奥格瑞玛的一员，跟洛坎、凯恩和雷克萨一样！$B$B很多人正在前往棘齿城与他会面，也许你也会感兴趣，传言说他正在寻找一些东西，并可能奖励任何帮助他的人。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40726, '可恶的阀门，每一天我们的主水泵都在不断地泄漏，如果泰尔科营地要持续存在，它需要持续供应新鲜水源，无论泰拉兹或诺克罗特说什么。$B$B我们的许多备用零件都位于岛屿北部的比克斯尔仓库，但自从一切都崩溃以来，我们和他们之间的交通非常少。$B$B我需要你去那里，只需沿着道路一直向北走，寻找“备用密封阀门”，比克斯尔应该有很多，只需寻找一个带有这个名字标签的箱子，然后将它带回给我，简单吧？') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40729, '我的研究才刚刚开始，已经有如此多的可能性，让我头晕！$B$B你说你不知道我在说什么？我正在努力揭示巨大香蕉的秘密，传闻它们很久以前曾经在泰尔比姆岛上生长，直到它们被全部收割。$B$B现在只剩下神话和传说，但我会找到答案的！$B$B我的第一个线索来自东海岸外的小岛上生长的奇怪香蕉，但我并没有太多的运气，因为沿海都是鱼人，而我只是一个侏儒，也许你可以去那里，为我收集三个样本的“奇怪泰尔比姆香蕉”。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40731, '嗯，我陷入了困境，我所有的想法要么一文不值，要么失败了。肯定有我可以做的......$B$B<塔佐的眼睛重新亮起，但很快他又叹了口气。>$B$B实际上有件事，我刚刚想起来。我的一个“朋友”叫李萨，曾经在北方远处工作。当我们关系更好时，她曾告诉我看到过一个非常大的香蕉，太大了她搬不动。$B$B这一定就是我们要找的，但如果我们想要这个信息，我知道我得付出巨大的代价......你可以去泰尔科营地，代表我去说，不过，我真的没有什么金币，我知道她会要求金币。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40732, '又是你这只骡子，准备好工作了吗？$B$B我会坦诚，我可不想在泰尔科营地烧毁的时候留在这块岩石上，要想离开，我需要一些材料，那是金融岛上的地精找不到的。$B$B在整个丛林里有这些带翅膀的飞蛇。它们被称为“毒鳞飞蛇”，你看，它们体内有一种非常强效的囊袋，我就是在找这个毒鳞飞蛇囊袋。我们就要八个，给我八个，我就告诉你关于这个愚蠢大香蕉的事情') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40755, '我有一个需要请求的事情，对我来说非常重要。你知道“沉没成本谬误”的意思吗？在我的世界里，这完全是真实的。我花了多年的时间和大量的金币，研发了一台能够根据香蕉是否值得收集来进行分类的机器。它能够判断香蕉的成熟度、年龄以及各种因素，以确定是否值得我们花时间去收集。$B$B就是说，我派出去的那帮傻瓜迷路了，把它留在了这附近的西边营地。$B$B我没有很多人去浪费，让他们被毒蛇咬成碎片，所以为什么不由你来做呢？去找回“螺栓熔化器1000”，请小心地将它带回来，应该在西边的路上，一个小小的废弃营地里。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40758, '唉，我不愿意这么对你，孩子，但那个矮人居然把大部分的鼻烟“用”掉了，看来你有点运气不好。这显然不足以弥补你所寻找的零件的成本的一小部分，但我还有另一个请求，它可以支付剩下的部分。$B$B就说我有些客户想要为“科学”目的“研究”有毒材料。他们想要得到一份“枯萎精华”，这可以从东瘟疫之地的枯萎恐魔那里获得。所以，帮我弄到枯萎精华，这就可以支付剩下的部分，简单吧？') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40799, '他们还没有回复我！我的兄弟姐妹怎么看起来这么简单？多么令人气愤！$B$B<当她未能将其中一只雏鸟召唤到她身边时，她的耳朵会竖起，她会露出獠牙。>$B$B 我的山多会告诉我放下我的骄傲，我\' 我确定。他的方式始终是耐心的。我恳求你，$N，去找角鹰兽大师并请求他们对这些任性的孩子提出建议。不遗漏我的挣扎细节，尽管承认我需要他们的帮助让我很痛苦。$B$B等等！不要与卡里拉斯或菲尔德伦说话！我不能接受只能被视为优惠待遇的东西。$B$B 我强烈建议你前往鲁瑟兰村和阿斯特兰纳，我相信我曾经收到过来自奈杰尔角的信件，无论那是在哪里。石爪峰上的特洛伦我确信他会在这方面帮助我，但要注意他的……漫无目的的倾向。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40828, '<多尔万费力地敲着钥匙，随着时间的流逝，他的表情因失望而扭曲。>$B$B 我无法理解。 这是行不通的。 我相信我精通麦迪文的魔法，但可惜的是，事实证明我错了。 这个人拥有伟大的天赋，如果只是...$B$B但是我离题了。 我们必须修理钥匙，而且还有最后一种可能性出现在我的脑海中。$B$B 我需要一本稀有的书，由艾格文在很久以前写的，题为“魔法锁和钥匙的论文”。 自从达拉然毁灭后它就丢失了，但有传言称它现在的主人不是别人，正是维克多·奈法留斯勋爵……$B$B这是我们唯一的机会。 取回这本书。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (40847, '我们对该地区的情报很薄弱。 我们知道吉尔尼斯是一个孤立主义国家，但我们没想到它会陷入如此悲惨的境地。$B$B作为活人，我们很容易融入其中进行间谍活动。 我们其中一个人的名字是“格蕾塔·朗派克”，她在上一封信中报告说她已经渗透到一个名为格雷郡的定居点。$B$B寻找她并告诉她“夜女士，黎明时嘴里有金子”。 这就是暗语。 她会给你一份报告，其中的细节至关重要，你要把它带回来给我。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41068, '紫莲花是一种相对常见的材料，我们总是在各种不同的情境下使用它。你会对用这种草药能完成的工作感到惊讶！$B$B如果你能积累大量的紫莲花，我们可以用这种草药来交换一颗明亮梦境碎片。带给我八十朵紫莲花，我们可以随时进行交换。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41069, '黑莲花是一种稀有且极其稀有的草药，诺达希尔的德鲁伊将其用于非常重要的目的。 这里的大部分魔法都可以通过添加其魔法属性来放大！ 给我一朵黑莲花，我随时可以和你交换光明碎片。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41070, '我亲眼见证了自然腐化所带来的毁灭。费尔伍德就是这一残酷事实的鲜明证据。然而，这片林地保持纯净，这完全归功于伊斯维尔。$B$B<德鲁伊停顿了一下，他的头低垂在地，默哀了片刻，然后继续>$B$B然而，他的牺牲只触及了他最亲近的人。我们必须通过继续净化费尔伍德的腐化来纪念他的遗产。$B$B在这片森林的西南部，有一个古老的林地，充满了美丽和黑暗。在那里，你将面对疯狂树人令人心碎的景象。$B$B从这些树人的尸体中取得六根被他们的痛苦所污染的树枝。尽管它们受到污染，但这些树枝拥有潜在的力量。把它们带给我，我们将为它们的腐化本质注入新的生命。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (50004, '嘘...我有一个任务给你，看看我身后。我在铁炉堡附近抓到了这个喝醉的兽人间谍，明白吗？但是我想对他采取一点“创意性”的报复。如果你把他的头带给我，并确保完好无损，我会给你展示一些非常值得你去做的事情。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (50323, '最近发现一个恶棍，其行为极其恶劣，必须严惩！ 我们代表军队和皇室联合发布消除此人的命令。对于那些勇敢杀死相关罪犯的人来说，将会得到公正的奖励。名字是：。奖励：250点声望。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (50326, '我，格里兹罗！想要跟多雷酒！你！乡巴佬！西部！快过去！荒野！走！快！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (50332, '最近发现一个恶棍，其行为极其恶劣，必须严惩！ 我们代表军队和皇室联合发布消除此人的命令。对于那些勇敢杀死相关罪犯的人来说，将会得到公正的奖励。名字是：阿兹泰克。奖励：250点声望。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (55025, '我在这里快要发疯了。在亮水受到几发炮弹袭击后，我们被告知要待在屋檐下避难一段时间。我们已经被迫躲在避难所里几天了，我都快要发疯了！啊啊，要是有办法弄些酒来...等等，你可以去弄些酒。既然我们不能去，就去水手之家旅店给我弄来这些酒...咳咳...5瓶麦芽酒，3瓶壶装蜜酒，10瓶樱桃酒，10瓶波尔多酒') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (55041, '你听说过“知识就是力量”这句话吗？好吧，我的许多地精同族并没有听说过。我追求的是利用知识，并将其出售给那些有兴趣获取一些新技能的人。我寻找的着这本古老的书已经相当长时间了，书名叫做圣贤的智慧。一个名叫兰达斯的档案管理员在持有它。问题是，他不仅仅是一个手里拿着书的普通人，他也是达拉然的法师之一，想要得到它并不容易。他们对自己的东西非常保护，所以这就是我需要你帮助的地方。我最近得到了一些信息，说他在能俯瞰希尔斯布莱德田野和的高地上。找到他，把那本书拿给我。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (55042, '在我来到这个地方很久之前，我是风险投资公司一个相当有价值的员工。虽然那是很久以前的事了，那是另一个我，但如果有什么事情让我难以忘怀，那就是我得到的愚蠢绰号。当我还是一名工程师时，我被委托为石爪山设计一台超大型的伐木机。结果，另一个地精设计比我的好得多。我对此并没有意见，但让我有意见的是因为“我让他失望”而被工头希里克斯解雇了。他称我为“骗子”，现在这个绰号一直附着在我身上。这家伙罪有应得，会得到他的报应。你会在我曾经工作的老锯木厂外的风剪峭壁找到他。他是个老顽固，我怀疑他没有离开那里半步。给我带回他的戒指，就是他戴在中指上的那个超大尺寸的镶钉戒指。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (55050, '<小格瑞兹里克把手指放在胸口。>Lok\'tar!我是格瑞兹里克，部落之子，奥格瑞玛未来的战士！<这个孩子用他瘦弱的手臂做了个屈肌动作，他看起来几乎很可爱。>嘿，不要笑话我！拜托，我还有很长的路要走，但是保姆说如果我专心致志，我也会拥有像高阶督军一样的大斧头，或者说不定还能像战争酋长一样释放闪电！<格里兹利克模仿着用手施展法>无论如何，你看起来像一个无聊的老头，你不会和我玩，对吧？我可以请求你帮个忙吗？请把这个东西带给雷霆崖的托姆·狂暴图腾。上次他在这里的时候，他给我们带来了玩具，还教我如何使用木斧！顺便把它带上，他也想看看雷霆崖。你可以带着他，他更适合冒险。如果他想看世界，就让他去吧！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (60020, '不久前，卫戍们终于将娜迦赶出了索兰萨尔。不幸的是，这引起了一个强大的娜迦的注意，一旦她加入战斗，卫戍们很快就被她的魔法击退了。请找到并杀死这个怪，不能让她凭借着她的奥术魔法，变得更加肆无忌惮。我们最后一次见到她时，她就在附近的废墟。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (60104, '问候！你看起来像是一位勇敢的灵魂。如果我告诉你，我正处于彻底改变我们所知旅行方式的革命的边缘，你会怎么想？通过对法师使用的魔法符文进行一些巧妙的重新组合，我成功地制造出了一个装置，它能打开一个虫洞，可以用来将某人传送到世界另一边的某个地方。瞧！这就是将改变旅行方式的发明！我称之为“便携虫洞发生器”。现在唯一剩下的就是测试它……这就是你的任务。如果你愿意踏入由发生器创建的传送门，你应该会出现在另一侧，那里会有我的伙伴在等待着你。完成这个任务，我们将赠送给你一个这些装置，以表达我们的感激之情。祝你好运！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (70028, '“你在这里看到什么，$N？ 我会告诉你我看到了什么：一支没有了首领的漫游小队，简单而愚蠢的家伙，失去了他们的指挥官。 有时我会问自己，如果赫尔斯库姆没有…… 无所谓了。跌入恶魔之陷峡谷，你会看到大量燃烧军团的入侵者。 正如你所知，那里有一只强大的恶魔陨落，也因此得名，我想。你的任务很明确，但并不简单。 给他们制造混乱，削减他们的数量。 我期望你尽一切可能，别让一个活着的离开。 ”') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (70033, '“这是$N，你迄今为止最危险的任务，但我非常确信你会成功。$B$B你展现出了我很久没有见过的勇气，愿祖先指引你的脚步，保佑你平安归来。$B$B你有我的祝福和祖先的庇护。$B$B你站立的地方曾经站着一位伟大的战士，你也将走在他的脚步中，带着你心中的骄傲杀死他们！”') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (80103, '嗯，我想我们明白了为什么精灵会在这里。前方整个森林都着火了！而且肯定是地精做的。$B$B没有其他人会用那种能燃烧这么久的油！那是安德麦的货，孩子。侏儒不可能得到它。我不知道这个地方是怎么回事，但我不喜欢它。$B$B去那里带回一些油。也许你会找到一些关于我们到达这里之前发生的事情的线索。如果没有，至少我们自己的油供应又增加了！“') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (80220, '“你是$R，对吗？最近我看到很多你们的族人来到这里，在暴风城安家。$B$B在矮人区外围与运河接壤的地方，有一个带有你们族群旗帜的入口，你可以去那里见到他们，如果你愿意的话，与你自己的族人打个招呼。”') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (80392, '打扰一下，可以耽误您一点时间吗？$B$B我的名字是 利恩，您看起来像一位经验丰富的旅行者。 如果您不介意帮助我的话，我有一个任务要交给你，我自己的事情很忙，我需要将一个包裹带到这里东边的奎尔丹尼尔。$B$B只要在那里寻找一个精灵小屋，然后把它带到我的妹妹，我妹妹和我有相似的特征，但她有精灵血统。$B$BI 已将您的付款附加到包裹中，那么，您愿意帮我这个忙吗？“') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (80410, '对不起，$N。 我最近收到了一封来自塞纳里奥议会的奇怪信息，但它不是写给我的，而是写给你的。$B$B<雷恩递给你一封信，当你打开它时，信中只包含几个单词没有签名：“时间到了。在安道尔旅馆二楼见我。”>') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (80701, '读完后将其烧掉。$B$B$N,$B$B我衷心希望您身体健康，我希望我能亲自传达这封信，但您必须明白，我们喜欢保留这封信 保密。$B$B 我不确定您是否了解我们的组织做什么，或者我们是谁，但我们发现了有价值的信息，我们可能需要您的帮助。$B$B 在信封中，您将 找到一枚戒指，在您来拜访我们时将其放在手边，这将是您接受我们的使命并且信件已被烧毁的标志。$B$B 直到我们见面，马蒂亚斯·肖.') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (80740, '春节需要你的帮助！在庆祝活动期间，一个狡猾的萨特悄悄溜进来，偷走了我们最特别的烟花。这是我从藏宝海湾的地精那里弄到的一种特殊的烟花。他声称他从一位自称来自潘达利亚的旅行商人那里购买到的。  它的美丽会以龙形蛇状的形式覆盖整个月光林地的天空。你必须找回它！ 它原本是今年春节活动的最大惊喜。如果狂欢者们所说的是真的，这个萨特是受劳古斯·杰特之托而来的。 他是一个躲在黑暗深渊中的小偷以及狂热的教徒。取回我的东西，我将为你奉上属于你的奖励！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);  -- 
