INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (5481, '收集3根阴暗草，把它们交给布瑞尔墓地的初级药剂师霍兰德。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (5482, '收集10株末日草，把它们交给初级药剂师霍兰德。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- 
