INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (5544, '在东瘟疫之地搜索腐肉虫和腐肉吞噬者。杀了它们并收集它们的肉。当你收集到15块食腐虫肉块之后，就回到提里奥·弗丁那里。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- 
