INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (5961, '与东瘟疫之地的纳萨诺斯·凋零者谈一谈。据说他居住在玛瑞斯农场。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- 
