INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (7581, '到菲拉斯的厄运之槌去，从扭木广场的荒野萨特身上找到15份萨特之血，然后把它们交给腐烂之痕的戴奥。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (7604, '如果你愿意接受萨弗隆的设计图，请将瑟银兄弟会契约交给罗克图斯·暗契。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (7640, '使用驱魔香炉召唤恐惧谷中的灵魂。当你杀掉25个恐惧谷的灵魂之后，回到暴风城教堂区的格雷森·沙东布瑞克公爵那里复命。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (7703, '找到戈多克力量护手，并将它交给厄运之槌的克罗卡斯。$B根据克罗卡斯所说的，“传说”自称是王子的精灵托塞德林从一名戈多克食人魔手中偷走了那件神器。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (7722, '在大熔炉的熔渣之池中的某个地方，你可以找到工头玛托留斯偷走的秘密设计图：炽热助熔剂。找到这些设计图，把它们还给灼热峡谷的大铁匠博恩奈特。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (7729, '杀死15个黑铁工头和15个黑铁奴隶贩子。完成任务之后就回去找监工斯克兰格。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (7761, '真是个愚蠢的兽人。看来你需要找到那枚烙印并获得达基萨斯徽记才可以使用命令宝珠。$B$B你从信中获知，达基萨斯将军守卫着烙印。也许你应该就此进行更深入的调查。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (7787, '把风吻之刃交给德米提恩。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (7907, '当暗月马戏团来到镇上的时候，把野兽套牌交给他们。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (7927, '当暗月马戏团来到镇上的时候，把入口套牌交给他们。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (7928, '当暗月马戏团来到镇上的时候，把督军套牌交给他们。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (7944, '到贫瘠之地的哀嚎洞穴中去寻找你的财宝吧。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (7945, '到莫高雷的灰月洞穴去寻找你的财宝吧。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (8072, '从祖尔格拉布把以下权力珍宝带给盲眼法希尔：1条原始哈卡莱束带。你还必须在赞达拉部族中达到尊敬或更高的声望。$B$B盲眼法希尔在荆棘谷的尤亚姆巴岛上。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (8251, '为大法师克希雷姆收集10份闪光尘埃。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- 
