INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (8553, '与斯普罗格谈一谈。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- 
