INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (8598, '把勒索信交给塔纳利斯的纳瑞安。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- 
