INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (8736, '保护永夜港免受伊兰尼库斯的伤害。不要让守护者雷姆洛斯死亡。不要杀掉伊兰尼库斯。保护好你们自己。等待泰兰妲。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (8746, '找到驯鹿梅森。在你手头上的便笺中查找有关梅森下落的线索。$B$B当你找到它之后，往它身上洒一些驯鹿之尘，这样就可以让它摆脱任何束缚。$B$B解救梅森之后，把驯鹿之尘还给奥格瑞玛的凯玛德·考伯宾奇。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (8784, '把上古其拉神器交给隐藏在神殿入口处的龙类。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- 
