INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (8944, '将一条勇气腰带和一副勇气护手交给奥格瑞玛的莫克瓦尔。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- 
