INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (80740, '从黑暗深渊的劳古斯·杰特那里取回\'龙之烟花\'，然后返回月光林地的春节供应商处。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (6, '哈，你干掉他了!你为艾尔文森林做了一件好事，当然罗，你也获得了赏金。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (7, '干得好，$N。那些狗头人不过是些小贼和懦夫，不过如果他们数量太多的话，还是会对我们构成威胁。而且，暴风城要面临的威胁已经足够多了。$B$B我为你成功的清剿行动表示我的敬意。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (16, '谢谢，$N!如果你还想再交换的话就回来找我吧 !') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (33, '真是太辛苦你了!我已经等不及要去煮狼肉了……$B$B我这里有些东西你也许用得着……选一件吧!$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (37, '虽然这具尸体已经残缺不全，不过你发现尸体旁边的一块勋章上面刻着几个字:「步兵马拉凯·史东」。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (45, '你在尸体的脖子上找到一块金属勋章，上面刻着「步兵罗尔夫·哈特弗德」。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (62, '真是个坏消息。后面还会有什么?龙吗?我们必须在矿坑附近加派巡逻队。谢谢你的努力，$N。请等一下……我还有个任务给你。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (69, '斯塔文?听起来很耳熟。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (96, '这就是我要的证明，你做的得好，$N!$B$B我很高兴能够成为第一个向你祝贺的人，拿着这个……属于你的水之图腾。$B$B好好地利用它，祝你好运。$B$B离你的下一次试炼还有很长的时间，所以接下来你要好好地回顾你所学到的东西。纯洁的水不仅能让那些受伤的人恢复活力，也能产生更多其它的效果。如果你有时间的话，我建议你去找一个萨满训练师，他们或许能教你些别的咒语。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (107, '我很同情这对可怜的恋人，梅贝尔跟汤米.乔，我自己也年轻过，也轰轰烈烈地爱过一次。$B$B我一定得为他们做些什么!让我想想……') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (111, '我们两家是世仇，汤米和梅贝尔恐怕不会有什么结果，不过…也许我们可以想办法让他们聚一会儿。$B$B嗯，让我想想看能做些什么……') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (114, '哦……天啊!要欺骗我的家人让我很有罪恶感，但我对汤米.乔的情感却强烈的无法忽视。$B$B谢谢你，$N。只要一有适当的时机，我就会喝下这瓶药水，然后悄悄地去见我的爱人。$B$B请你拿着这个，这是我的一点心意。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (123, '嗯……我听说过这个「收货人」，不过不知道他到底在为谁干活。谢谢你把这个日程表送来，它会帮助我们解开这个谜团。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (169, '这实在是太棒了，$N!加塞尔佐格带着那帮畜牲为祸四方，杀了不少无辜的人。正义终究还是获胜了，这也是为暴风王国夺回要塞的第一步!') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (176, '哈!干得好!我还以为没人能干掉那个怪物呢!$B$B拿着这个，$N。谢谢你―这只豺狼人给我带来的麻烦足有黑石塔那么大!') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (179, '啊，太棒了!狼肉一定不错。哦，别着急，$N。我没有忘记当初的承诺，你看中了哪件就拿哪件吧。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (180, '邪恶的范高雷中尉终于死了?对这个歹毒的家伙来说，这也算是个解脱吧。你很勇敢，$C。我代表湖畔镇的人民对你的帮助表示感谢。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (211, '你成功了!巫妖阿拉基终于被打败了!$B$B你今天为联盟做出了巨大的贡献，$N。你的勇气和毅力是成为真正的英雄所必须具备的素质。请接受这个作为荣耀的象征，让所有看到它的人都知道你为联盟赢得了辉煌的胜利!') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (236, '非常好!这将有助我们，在不日即来的战斗中，燃起熊熊的战争烈焰。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (240, '啊哈!谢谢你，$N。这蛋糕真是太好吃了!$B$B请收下这些吧，这是我给你的报酬!$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (247, '$N，你已经杀死了梣谷狩猎所需杀死的三头野兽，你已经给我带回了它们死亡的证据。对你的力量和坚毅，我们毫不怀疑。猎人的血液在你的血管里流动，你理应得到赞颂!$B$B这是对你为部落做出的伟大贡献的奖励，愿你的祖先见证你的荣耀!$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (256, '呦!这是什么?你为什么拿着这个……$B$B这不是―天哪!这不是那个巨魔的脑袋吗?这就是我们正在通缉的恶棍!这是给你的奖赏，我代表塞尔萨玛镇感谢你。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (335, '好极了!这些真的是很好的样品!$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (339, '终于!凑齐第一章了!$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (340, '第二章也终于凑齐了!干得好!$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (341, '哟!干得漂亮，$N。第三章现在也终于齐了!$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (342, '好极了!我们现在有了完整的第四章了!$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (343, '冶金学?啊，当然，我们这儿有很多关于冶金学的书，我也很愿意帮助克里斯多夫修士完成他的演讲稿!那么……可敬的修士先生要的书名叫什么来着?$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (347, '哦，太好啦!我可以用这些矿石配制墨水了，这样一来我很快就可以抄完《金属的延展性》。$B$B谢谢你，$N!$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (351, '你把蛋形机器人给你的定位器放到小鸡机器人体内。$B$B里面传出了一阵叽哩咕噜的声音，然后小鸡机器人慢慢地站了起来。当这个机器能够移动之后，奥格索普的声音再次传了出来:$B$B「OOX-17/TN现在可以勉强运作了，但它需要一次大修!不过对你来说它太重了，你是背不动的……但是我想到个好办法。你能不能再帮我看着它一小贬?」$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (384, '喷香的麦酒已经酿好$B美味的猪排摆上餐桌$B$B管他三七二十一$B先动手抢一块再说!$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (407, '圣光保佑!总算有得吃了!这南瓜可真甜……$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (456, '你的任务完成得很好，$N。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (457, '你用实际行动证明了你对大自然的热爱，$N。像你这样年轻的$C一定会有光明的未来。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (459, '你为幽影谷中的生灵所做的一切都值得嘉奖，$N。$B$B尽管如此，我还是高兴不起来，因为你证实了我所担忧的事。如果劣魔是因为被魔苔影响而变成这样的话，熊怪们会变成什么样子也是可以想像的了。$B$B你必须到多兰纳尔去，能干的$C，你得去找知识渊博的德鲁伊阿斯瑞达斯·熊皮。他和我们一样关心森林的安宁。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (468, '你好，$C!你来这里是打算接下侦察任务的，对不对?非常好!$B$B我希望你的装备补给什么的都没问题，因为这次的「侦察」任务似乎并不如你想像得那么简单……$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (485, '你把蛋形机器人给你的定位器放到小鸡机器人体内。$B$B里面传出了一阵叽哩咕噜的声音，然后小鸡机器人慢慢地站了起来。当这个机器能够移动之后，奥格索普的声音再次传了出来:$B$B「OOX-09/HL现在可以勉强运作了，但它需要一次大修!不过对你来说它太重了，你是背不动的……但是我想到个好办法。你能不能再帮我看着它一小贬?」$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (518, '巨魔的血把白雪都染红了，不过在破碎岭的巨魔和他们的精神被完全压制并埋在大雪中之前，我们还不能停下来。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (532, '你在希尔斯布莱德英勇作战的事迹已经广为传播了。干得好，$C。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (549, '很好，$C。按照这样的形势，在这片土地上到处流窜的辛迪加很快就能被消灭。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (550, '你就是那个在希尔斯布莱德丘陵对联盟进行了致命打击的$C?你的英勇事迹早已传到幽暗城来了。$B$B只要你跟随着黑暗女王，继续在战斗中表现你的领导才能和长处，那么一定会前途无量的。$B$B虽然我们的主要威胁─巫妖王的天谴军团在北部的势力已经被不断削弱，但我们的战斗计画还在不断受到这些人类的阻挠。不过，你的表现已经说明我们能够打败人类，我们也必将打败人类和所有被遗忘者的敌人。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (566, '做得好，$N。瓦杜斯男爵一死，辛迪加的领导人就又少了一个。他们的抵抗也坚持不了多久了。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (597, '当然，我正等你呢，$C。让我看看你的发现……$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (618, '你把我的弯剑从奈古拉什那儿抢回来啦!我简直不敢相信这是真的，$N!自从见到你之后，我似乎就时来运转了呀，没错，肯定是这样的!$B$B谢谢你!以后，要是我能再搞到一条新船的话，你要出海就尽管来找我，我让你随便坐，你永远都是我最欢迎的客人!') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (636, '啊，你找到我了!$B$B求求你，善良的$g先生:女士;\r\n，我请求你帮助我。我被囚禁了，而囚禁我的人永远也不会释放我!') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (662, '太好了，这些宝贵的资讯安然无恙。藏宝海湾里的舰队指挥官看来可以放心了。干得不错，$N。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (679, '$N，你的同胞会为你感到骄傲的。我们面临的威胁已经大大地被削弱了，我坚信部落往日的繁荣定将在这片高地上重现。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (717, '祈伦托不用再为莱瑟罗峡谷里的囚犯们担忧了。我将把这个好消息报告给我的主人。卡萨斯无疑会很高兴的。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (738, '这具骷髅一定是可怜的埃格蒙德留下的。他的尸体四分五裂，只剩下了一副空架子。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (757, '你通过了大地之母祭仪的第一个试炼，部族将会以你为荣。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (763, '我的好友鹰风酋长写给我的信!啊，我能从这些符号中看出他对你的关心。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (776, '干得好!真是一次完美的狩猎!$B$B我会派人把那具尸体拉回来，这可以给我们提供充足的兽皮和肉食。$B$B你为你的族人立了一大功，$N。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (793, '黑龙军团仍是背叛了部落的黑石氏族的同盟，他们死罪难逃。既然布莱克拉席和赫玛图斯都已经死了，我们就可以把注意力转向西边，转向黑石塔。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (794, '你找到它了!干得好!$B$B你在燃刃集会所中所做出的努力无疑正是将这群家伙赶出试炼谷的关键一步。但我真正担心的是，他们也许对我们的土地有着更可怕的打算。$B$B当前我们还无法彻底看清他们下一步要干什么。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (883, '拉克塔曼尼在我们的语言里被称为「震地者」，它的步伐就像雷声一样铿锵有力。现在，它与你合二为一，它的勇气和稳健将与你同在。现在没什么你应付不了的局面了。$B$B大胆地向前走吧，$N。大胆地向前走吧，震地者。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (895, '啊，原来是这件事。你知道，我曾经在公海上看见过破浪号。那是一艘可怕的船，或者说是小艇……那些水手太特别了!$B$B不管怎么说，她划过水面的景象真是漂亮。我很高兴得知她那声名狼藉的船长不会再骚扰我的船只了。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (908, '这正是我需要的东西!深渊之核是个非常完美的资讯源，我可以从中获取许多资讯。不管暮光之锤在干什么―反正肯定不会是什么好事情―我和我的同事都会努力找出真相。$B$B你干得很好，大地之环非常感谢你对我们的帮助。同时，你也帮助了整个部落，因此你应该感到光荣。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (909, '这……这真是一个大发现，$N。$B$B你说你是从黑暗深渊的阿奎尼斯男爵那里得到这东西的?阿奎尼斯男爵一直以来都被认为是腐败的元素生物，这个球体将证明到底是什么腐蚀了它。如果最终证明是暮光之锤搞的鬼，那么我一点也不会感到吃惊，但是我们的研究还是可以搞清楚他们是怎么做的。$B$B感谢你把这个球体交给我，请接受大地之环最诚挚的敬意。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (921, '那么，你应该已经知道了海加尔山战役结局的第一部分了吧。你需要知道的还有很多，你会在穿越泰达希尔前往达纳苏斯的旅程之中逐渐了解到任务的其他部分。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (928, '啊，我明白了。你是被特纳隆派来的。好吧，那么，我们看来得有很多事情需要开始着手去做的，而且似乎没有多少时间留给我们了。$B$B我想，我们最好现在就开始。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (929, '海加尔大战之后，我们一度迷失了方向。诺达希尔尚未摆脱战火的威胁，而我们不朽的生命--我们族类的泉源!--也已不复存在。$B$B这时背叛者从监狱里逃出来为非作歹，而怒风尊师也消失无踪。一切进入黑暗时期。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (934, '在神谕之树面前……你会感觉到自己几乎能把智慧抓在手里。让我继续说下去……$B$B随着泰达希尔的成长，大德鲁伊去祈求巨龙的祝福，因为在古代，那些巨龙的地位远在诺达希尔之上。但是时间之王诺兹多姆拒绝祝福泰达希尔，反而斥责德鲁伊的傲慢。和诺兹多姆一样，雅立史卓莎也拒绝了德鲁伊们的要求，但是没有她的祝福，泰达希尔的成长就会受到不良的影响，后果难以预料……') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (983, '当你把蟹腿放进机器中，就听见齿轮开始磨合了。从传声盒里发出的巨大响声来判断，蟹腿应该是已经放在了正确的位置上。不一会儿，机器就开始发出嗡嗡的声音，还伴随着微弱的语音。$B$B「喂?喂喂?嗯……喂!你修好它了。我是维兹班恩!非常感谢你……嘿，你想不想再修修另一个传声盒?」$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (1001, '当你把蛇颈龙的眼球放进去之后，传声盒发出一阵噪音，然后再次被启动了。短暂的沉默以后，你听见一个熟悉的声音。$B$B「螃蟹酒是最棒的……」*打嗝*$B$B「什么?哦，你修好了传声盒?哇塞，你太厉害了。你愿意修理另一个传声盒吗?」$B$B你听到了液体倒入杯中的声音，然后是咕咚咕咚的喝水声。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (1002, '传声盒突然开始工作，你能听见清晰的磨牙声从里面传出来。$B$B「啊，你成功了!真是好消息……那么……你为什么不继续下去呢?哦!除非你还想再接下一个任务!」$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (1049, '《堕落者纲要》!我都快要开始怀疑这本书到底是否真的存在了!$B$B你为雷霆崖的牛头人做出了杰出的贡献，$N。我们永远不会忘记你的奉献。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (1103, '啊……看来你准备好了……$B$B我会把需要的东西放在火盆上，这样你也能和水灵交谈了。$B$B不要惧怕与精神世界的灵魂对话……提夫知道一两个关于如何使用灵契的诀窍。$B$B来吧，和我一起到神殿去和那些水灵谈谈，我的$G兄弟:姐妹;。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (1127, '啊，太好了!这是你的报酬。$B$B为了表彰你优秀的表现，我还有些额外的小奖励给你……$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (1147, '哈!$N，溅到你身上的那些脓液让你变得更好看啦!那些该死的虫子让你现在浑身都散发着臭气，别靠科多兽太近，你会吓得它们四散狂奔，或者直接把它们给惹火了。$B$B从你身上的气味就可以知道你已经完成了任务，感谢你，$N。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (1154, '这就是我提到的书。希望你能正确回答我的问题……除非你忘了研究它的内容。$B$B准备好之后就来找我，我将向你提出一个问题。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (1218, '啊，就是这个!你马上就可以吃到沼泽炖肉了!') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (1245, '好得很!这东西倒是蛮有趣的。乔贞和德拉维拉上我确实是选对人了。$B$B看来迪菲亚兄弟会正在很卖力地完成他们的计画。嗯……这是什么?「拳」? 这名字有点耳熟呀。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (1253, '嗯，我可不是制造武器和护甲的专家。我知道它们的用途，可是不懂如何制造。$B$B这个盾牌和一般盾牌没什么区别，只是旅馆的大火在上面留下了些痕迹。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (1318, '喔……你是真正的大王!我这辈子都从来没有看见过它!看来上面的油都要干了……也许那个可恶的精灵把它偷走之后就再也没用过它。好吧，我要对他说哈哈哈哈哈!$B$B看这里─护手上的标志是一个很古老的魔法印记，据说比戈多克巨魔的历史还要久远。好吧，作为戈多克的队长，我们曾经学习过一种知识─如何将印记还原并将力量重新注入护手中!$B$B我会为你这么做的，大王!给你，拿着护手，永远统治我们吧!') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (1322, '我可不喜欢这么大的蜘蛛，因为我不能一脚把它们给踩扁。$B$B谢谢你找来这些，$N。看我剥开毒囊，把毒液滴到盾牌上……$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (1480, '嗯，这些符文确实是某种语言，$N，某种古老的语言。它们似乎与艾瑞达语有点类似，但仍然与其相去甚远。如果我没有看错的话，这是某种契约……你看这里，没错……这个符文正是一个恶魔的签名:阿兹雷索克领主。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (1504, '干得好，$N。研究一下这份古卷，它将告诉你如何将你刚才击败了的虚无行者再次召唤出来。$B$B你应该知道我对你抱有很高的期望，而你也从没有辜负过我，至少到当前为止是这样的。$B$B不过，无论是什么事情都不要看得太重，你必须以平常心来看待这些事，就像每天早上起床洗漱一样简单而自然地做好它们。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (1526, '当你将馀烬投入碗里之后，一团白色火焰随即燃起。你能感受到灵契的神奇力量在你体中流过，也能看到火光在你面前舞动。$B$B你将火炬的前端伸进盆里，它立刻就被点燃了。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (1688, '苏伦娜很有天赋，但仅靠这个就想掌握更多的术士魔法还远远不够。看着她的大好天赋被白白浪费掉确实很让人遗憾，但有时候这是必要的。$B$B我希望我在你身上倾注的心血会产生不同于此的结果。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (1899, '很好，这比我预计中能从安德隆那里搞出来的情报多得多。给我点时间，在我给你委派下一个任务之前，让我好好地读上一遍。\r\n') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (2199, '你真是太好了，我高兴得都要哭了……说真的，真是太感谢你了，我的朋友。$B$B现在，我可以告诉你，你手里的项链是我最得意的作品之一，但是用于禁锢其中魔法力量的三块宝石已经不见了。很久以前，我为一位圣骑士打造了这条项链，当时他正要去清除荒芜之地一个名叫奥达曼的挖掘场里的「邪恶势力」。$B$B但是……那个圣骑士死在了奥达曼，这只是我噩梦的开始。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (2242, '这是个悲惨的消息，$N。蔓延于黑海岸一带的森林与河流的疾病似乎已经开始侵袭我们的家园了。$B$B你做得很好，但这儿已经没有什么你能做的事情了。拿着这把匕首吧，这是你为泰达希尔效力所得到的报酬。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (2259, '是时候让你出去闯荡闯荡了，$N，一个神秘的未知世界在等着你。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (2278, '按照石头守护者的指引，你完全了解到了土灵、矮人和石腭怪的起源和历史。一阵轻微的嗡嗡声从圆盘中传出。石头守护者说:$B$B「圆盘已经集成完毕。请再次触摸诺甘农圆盘，获取属于你的资料拷贝。」$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (2300, '你是准备好开始工作了呢，还是想在我们开始前先打个盹儿?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (2583, '野猪的力量让你更加强大了，$N!你相信自己可以和那些野猪一样强韧吗?$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (2584, '我必须提醒你，$N，不要想把我的药剂混在一起。你最后使用的药剂的药性总是会替代在这之前所使用的药剂，所以别用了这个又用那个，白白浪费宝贵的药剂。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (2601, '这简直是奇迹，$N!我可以让你欣赏一下红石蜥蜴的内部构造。$B$B如果你对这种药物有兴趣的话，我也可以为你多做一点……当然，不是免费的。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (2603, '非常出色!我要立刻开始工作了。也许我能找到一种包治百病的方法!$B$B啊，对了，当然还有你的报酬─如果你想要更多砂囊口香糖的话，就回到我这儿来，继续帮我收集原料，然后我就可以帮你再做几份。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (2604, '也许有一天我可以分离出这种药物中的活性酵素，然后用它制成更有效的药物。不过，现在你只能用我现在做出来的这种东西。如果你需要更多口香糖的话，就回来找我吧。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (2751, '沃姆什的血脉就要断了，不过它的传说还将继续!$B$B你已经证明自己是个名副其实的铁匠，$N。对铁匠来说，最好的奖赏就是看到自己所造的武器和护甲沾上敌人的血!$B$B但愿你所铸造的胸甲都能在战场上浸染你的敌人的鲜血!$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (2766, '你把蛋形机器人交给你的定位器放到机器小鸡体内。$B$B里面传出了叽哩咕噜的声音，然后小鸡机器人慢慢地站了起来。当这个机器人能够移动之后，奥格索普的声音再次传了出来:$B$B「OOX-22/FE现在可以勉强运作了，但是它需要一次大检修!对你来说它太重了……但是我想到个好办法。你能不能再帮我看着它一会儿?」$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (2772, '整个世界都将在被你踩在脚下，$N!你的靴子将让你傲然挺立，而且再也不会被扫堂腿暗算啦!$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (2781, '正义终于得到了伸张!你重拳打击了可恶的游牧民!斯科比斯汀死了，我们现在只需把那些游牧民赶离加基森的水井就大功告成了!\r\n\r\n以加基森水力公司的名义，我很高兴将这笔奖金颁给你。你为我们作出了很大的贡献。\r\n') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (2841, '我知道你可以的，$N!另一方面，索维克也有自己的疑虑。$B$B<诺格清了清嗓子>$B$B既然现在我们手里有了蓝图，那么我们早晚可以弄明白地精的钻探设备有何革新之处，然后将它们用于我们自己的伐木机。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (2875, '啊，安德雷的脑袋。我早就知道他会被审判的!\r\n\r\n非常感谢你，$N。现在，如果你在这里签个字，我就可以为你支付报酬。\r\n\r\n别担心字体太小的问题。这里面没有对你不利的条款，而且……我不认为有什么放大镜可以帮助你阅读这些字。\r\n') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (2940, '那你想借《菲拉斯的历史》这本书?$B$B让我想想……$B$B我允许你借这本书，$N，但你先得为我做件事。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (2946, '当你触摸底座的时候，奥达曼的迷你白金圆盘在背包里嗡嗡作响，闪闪发光。一种熟悉的刺痛感涌过双手，另一个石头守卫的形像在奥丹姆大门前出现了。$B$B「您好，我是入口的护卫者。您的圆盘缺失了正确的入口盘，奥丹姆圆盘。请将所需的圆盘和你手中的圆盘合在一起，然后重新进入。谢谢。」$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (2953, '超级清洁器5200型动了起来，它剧烈地晃动着。在机器里面，覆盖在物品表面的污垢正在被清洁工具研成粉末!$B$B超级清洁器5200型停止了运转，熟悉的「叮」的声音过后，机器的盖子猛地打开了，里面摆着一只精心包装过的，扎着蝴蝶结的小靶子。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (2954, '充满了力量和权威的声音从石头卫士的口中发出:$B$B「当你再次接触底座的时候，你的圆盘将回到你手中。你必须先得到奥丹姆圆盘，把它们与已有的圆盘组合起来，然后你才能进入奥丹姆城。」$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (2966, '当你触摸底座的时候，奥达曼的迷你白金圆盘在背包里嗡嗡作响，闪闪发光。一种熟悉的刺痛感涌过双手，另一个石头守卫的形像在奥丹姆大门前出现了。$B$B「您好，我是入口的护卫者。您的圆盘缺失了正确的入口盘，奥丹姆圆盘。请将所需的圆盘和你手中的圆盘合在一起，然后重新进入。谢谢。」$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (2991, '啊，耐克鲁姆的勋章。据说这枚勋章使那个巨魔变得长生不老，但这种奖励是有代价的。我希望找到一种获得勋章力量的方法，同时避免它的……讨厌的负面效应。\r\n\r\n你帮了我一个大忙，$N。我会遵守我的承诺。\r\n') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (3105, '随着你的力量不断增强，你会受到诱惑─你必须记住要控制自我。我不会骗人─魔法的腐化作用会影响到所有研究它的人，尤其会影响到那些与扭曲虚空里的生物打交道的人。你要保持耐心、谨慎……不过也不要压抑自己的雄心壮志。\r\n\r\n等你变得更强大的时候就回到我这里来，我会向你传授更多的术士技艺。\r\n') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (3367, '当杜里奥斯遭到枪击的时候，这封信掉了下来。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (3370, '菲拉派你来的?好吧，让我们来看看那块她避而不谈的裂片……$B$B<玛斯雷往那块裂片里看了一眼。>$B$B哦……我不能……好吧。$B$B$N，感谢你把这个送到我这里，但我还是建议你不要提到这块裂片，这些事情应该由塞纳里奥的德依鲁们自己来面对的。$B$B这么说吧，翡翠梦境中的东西与我们想像中的并不一样……$B$B也许在未来的某一天，我们的命运会再次交会。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (3373, '你把宝石放入精华之泉中。$B$B「感谢你，凡人，你已经─不……不，不可能!不!这个可恶的古神的堕落力量已经污染了绿龙军团的精华之泉的圣洁!不，不要，我感到自己的精华正在从我的身上剥离!痛苦!我感到一个永恒的梦魇已经控制了我……」$B$B「凡人，我求求你!去找绿龙族的一员来阻止这一切……帮帮我……我被拴在黑暗之中……永远陷于痛苦……请不要再折磨我了……」$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (3377, '我可以在这只笼子里听天由命，但祈祷文必须要被发现!$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (3381, '两根羽毛，正如我所要求的那样。这要求并不高吧。$B$B准备好了?说出这句话，然后我们就出发。$B$B哦，你还是要小心自己的行为……我的主人不会对白痴客气的，但是他对那些能够取悦他的人会非常的热情。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (3402, '考维克被干掉了?真是让人兴奋的一天啊，$N!这些年来，这个恶棍一直都在从事黑市交易，欺压全世界老实交易的辛苦商人。$B$B你理应为这个成就获得一份奖励!一份丰厚的奖励!$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (3453, '还有一个最终的任务等着你去完成。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (3454, '你用双手抓住别炬，一阵阵的憎恶和愤怒瞬间流过了你的身体。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (3511, '调剂将为我们的武器提供必要的成分。接下来，我们还需进行最后一个步骤来完成武器的锻造。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (3521, '感谢伊露恩，你这么快就收集到了这些原料!\r\n\r\n稍等一下，我马上就配好解药。\r\n') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (3522, '这是什么，$N?\r\n\r\n哦，我就知道迪兰妮亚能帮我的!\r\n\r\n<埃沃隆喝下解药>\r\n\r\n我总是在惹麻烦，而迪兰妮亚总是会设法帮助我。\r\n\r\n我感觉好多了，但是我要在这里休息一会，直到我感觉完全恢复之后再离开。好吧，其实我是希望你帮我从这些可恶的树林蜘蛛中清出一条路来……\r\n') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (3525, '贝尼斯特拉兹匆忙离开，只留下一只燃烧的火盆。当你盯着火苗看时，你的脑海中浮现出了一只有着超大翅膀的红色巨龙。耳畔响起贝尼斯特拉兹沙哑的声音。$B$B「你成为我所希望的英雄了。你摧毁了这些野兽的屠杀场。我对人类的信任度又重新建立起来了。收下这个吧，这是你作为英雄应得的奖赏。」$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (3602, '你在艾萨拉的任务已经完成了，$R。现在我必须为你的下一步冒险铸造必需的东西。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (3625, '<加尔文擦了擦他额头上的汗。>$B$B没有比这更能对付恶魔的武器了，$N。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (3630, '啊，一个追寻工程学真谛的年轻工程师，一个探求地精工程学奥秘的求知者!好吧，我的朋友，请原谅我的敏感和激动。我们现在的情况仍然十分糟糕，但是有你这样对工程学的真知孜孜以求的技师加入我们的行列，这仍然是让我很高兴的!\r\n') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (3632, '啊，一个追寻工程学真谛的年轻工程师，一个探求地精工程学奥秘的求知者!好吧，我的朋友，请原谅我的敏感和激动。我们现在的情况仍然十分糟糕，但是有你这样对工程学的真知孜孜以求的技师加入我们的行列，这仍然是让我很高兴的!\r\n') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (3640, '欢迎你的加入，$N!你即将接触到艾泽拉斯大陆上最先进的工程学结构图。\r\n\r\n既然你致力于这门科学，那么现在让我们来检验一下你在地精工程学方面的本事，然后帮助你设计一整套发展计划，让你尽可能地发挥你的地精工程学天份!\r\n') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (3642, '欢迎你的加入，$N!你即将接触到艾泽拉斯大陆上最先进的工程学结构图。\r\n\r\n既然你致力于这门科学，那么现在让我们来检验一下你在地精工程学方面的本事，然后帮助你设计一整套发展计划，让你尽可能地发挥你的地精工程学天份!\r\n') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (3825, '干得太棒了，士兵!太让我惊讶了!我会因此获得勇气勋章的，呃，我的意思是，你会因此而获得丰厚的奖励!$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (3903, '啊，维里副队长让你来找我?他是个勇敢而热心的人，但是职责所在，他不能离开北郡修道院，所以也没法帮我的忙……\r\n\r\n你能帮帮我吗?\r\n') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (3906, '这不可能……绝对不可能……派隆的毁灭只是个开始，在黑石山脉的深处隐藏着更加邪恶阴险的堕落源泉。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (3907, '<桑德哈特抓起库尔尼亚石板。>$B$B拉格纳罗斯……在这里……$B$B部落的长老对黑石山脉散发的堕落气息感到恐惧是有道理的。一个上古诸神的统帅!它在我们的世界中出现了!我们必须重新评估自己在卡加斯的地位了。现在，我们必须决定是要留在这里继续作战，还是因为这个新的发现而怯懦地逃走。$B$B不要再贸然探索黑石山脉了，$N。一个比世界上任何事物都要邪恶的力量就居住在那个火焰燃烧的深渊中。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (4083, '宝石悄无声息地落入杯子的底部……$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (4186, '我觉得情况会更加糟糕……$B$B<所罗门镇长看着你。>$B$B看来湖畔镇的命运落在你的肩头上了。$B$B<你注意到所罗门镇长的眼睛湿润了。他开始哭泣。>$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (4322, '有趣的消息……你找到了遗失的情报，对吗?$B$B那么……它在哪里呢?$B$B哦，我想你应该获得奖励。<麦克斯韦尔元帅双手拢在嘴边作喇叭状。>$B$B快点做好准备吧!$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (4361, '<麦格尼愤怒地用他的拳头砸向王座的扶手。>$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (4503, '太好了，这些鳞片非常合适。我想我一定可以用这些鳞片让我的机器飞起来!\r\n\r\n谢谢你!\r\n') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (4509, '我很高兴你把这个消息带给我，但是我不确定这到底会为我们带来什么好处。部落忽视了一切联盟之外的威胁，如果索尔看到现在这种严重的事实的话，也许他会采取一些行动，但是他被各种杂务困扰着，根本看不到这些。那些笨蛋认为我们在担心着想象中的威胁，而他们所关心的才是我们真正面临的危机!\r\n\r\n你已经亲眼目睹这个威胁，$N。我们必须继续投入击败异种蝎的行动!\r\n') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (4542, '还有更多的坏消息!这些半人马太过分了!他们袭击了我的一个补给车队，一个活口都没留下。这是赤裸裸的暴行，他们一定会受到惩罚的!$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (4603, '超级清洁器5200型动了起来，它剧烈地晃动着。在机器里面，覆盖在物品表面的污垢正在被清洁工具研成粉末!$B$B超级清洁器5200型停止了运转，熟悉的「叮」的声音过后，机器的盖子猛地打开了，里面摆着一只精心包装过的，扎着蝴蝶结的小靶子。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (4604, '超级清洁器5200型动了起来，它剧烈地晃动着。在机器里面，覆盖在物品表面的污垢正在被清洁工具研成粉末!$B$B超级清洁器5200型停止了运转，熟悉的「叮」的声音过后，机器的盖子猛地打开了，里面摆着一只精心包装过的，扎着蝴蝶结的小靶子。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (4740, '嗯，干得好!奥伯丁的人们要是知道今晚终于可以睡个安稳觉的话，肯定会非常欣喜的。\r\n\r\n你是正义的伸张者，$N。为此请收下这个作为回报。\r\n') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (4742, '<维埃兰的影像模糊了一下。>\r\n\r\n<你所收集的东西都消失了。>\r\n\r\n未铸造的晋升徽印已经准备就绪，该进行最后一步了。\r\n') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (4743, '当心，我要施展最后的保护咒语了。\r\n\r\n<维埃兰的眼睛变成了两团火球。>\r\n\r\n晋升徽印铸造完成了……\r\n\r\n你要明白，我给这件神器中加入了一些强大的保护结界。在情况最危急的时候，当一切看来都已经无法挽回的时候，红龙军团的力量将会帮助你。\r\n') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (4770, '什么!?如果我知道波卡?捷山要独自进入风巢的话，我会把他拴在图腾上面!他的父亲勉强才允许他和我一起来千针石林，我们来这里是为了研究这片美丽的土地上的各种生物。\r\n\r\n非常感谢你给予波卡的帮助，希望这个能够替你阻挡各种的不幸之事。\r\n') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (4783, '棒极了，$N。一切进展顺利。在你继续寻找最后两件物品的时候，我将对这些东西做一下处理。准备好了吗?$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (4841, '为了表示我的感谢，请拿着这个，$N。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (4974, '你给了黑石氏族致命的一击，$N。他们的领袖已死，黑石军团将再度陷入混乱之中。$B$B为了表示对你的敬意，卡林多的部落成员都将得到奖赏!$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (4982, '你成功了!只要雷克斯洛特得到这些图纸，他就会忘记他本想对我做的那些可恶的事情。$B$B$N，你是我的英雄!$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (4985, '「我感觉到那些灰熊已经被杀死，它们的痛苦已经结束。我……我还有一件事情要求你。我把它写在……写在这根树枝上，因为我感到我将要离开此地了。$B$B确实……我要走了。再次谢谢你，朋友……这块被诅咒的土地上的生灵都安息了……现在该轮到我了。」$B$B这位德鲁伊发出了一声沉重的叹息，然后从他的喉咙中传出一阵咯咯声。他的躯体一动不动地躺在了小屋的地板上。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (5047, '活着?衣服起作用了?哦!$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (5050, '你把半个好运符咒还给那个亡魂。她看了看它，然后期待地看着你。$B$B「亲爱的，你把你的半个好运符咒放哪里了?除非我们的两半都放在一起，否则我们是不可能团聚的。亲爱的……你能看到我吗?」$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (5051, '你把组合好的好运符交给珍妮丝·菲尔斯通的鬼魂。当她一抓住它，你观察到她体内即刻发生了变化。她那空气般的形体微微发光，并用明亮但忧伤的眼睛看着你。$B$B「你让我得到了自由……我不再需要这个好运符了。请你收下它，它或许会带给你像我一样的慰籍。」$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (5058, '一本打开的日记放在你的面前，发黄的书页上写着如下的文字:$B$B「哈洛德变成了这个样子，我不知道接下来会发生什么事。把他拖进我能找到的唯一可以关住他的地方之后，我已经心力憔悴了。我把钥匙藏在身上，祈祷能渡过这个难关……$B$B我希望能离开这里，但我需要钱。我想我们的东西都在那个柜橱里……现在我想起来了，哈乐德是不是把柜橱的钥匙藏在自己身上了?$B$B我要先休息一下，现在我实在是太疲倦了。」$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (5066, '欢迎你来到瘟疫之地，英雄。这里是艾泽拉斯最危险的地区之一，更糟糕的是，在我们北边和东北边的广袤土地上，到处都潜伏着天谴军团的势力。面对联盟的召唤，你毅然赶来履行自己的职责，这让我感到非常高兴!\r\n\r\n如果你已经准备要上阵杀敌了，那么，在瘟疫之地有足够多的敌人，你想杀多少就杀多少。\r\n') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (5090, '欢迎你来到瘟疫之地，英雄。这里是艾泽拉斯最危险的地区之一，更糟糕的是，在我们北边和东北边的广袤土地上，到处都潜伏着天谴军团的势力。面对联盟的召唤，你毅然赶来履行自己的职责，这让我感到非常高兴!\r\n\r\n如果你已经准备要上阵杀敌了，那么，在瘟疫之地有足够多的敌人，你想杀多少就杀多少。\r\n') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (5091, '欢迎你来到瘟疫之地，英雄。这里是艾泽拉斯最危险的地区之一，更糟糕的是，在我们北边和东北边的广袤土地上，到处都潜伏着天谴军团的势力。面对联盟的召唤，你毅然赶来履行自己的职责，这让我感到非常高兴!\r\n\r\n如果你已经准备要上阵杀敌了，那么，在瘟疫之地有足够多的敌人，你想杀多少就杀多少。\r\n') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (5122, '你找回勋章了!现在我可以离开这个教堂去继续履行我的职责了。\r\n\r\n我的职责就是去杀死那个帮助腐蚀了我和许多兄弟姐妹的野兽，瑞文戴尔男爵!\r\n') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (5126, '<罗拉克斯大笑了起来。>$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (5143, '你带来了最好的贡献，大自然会顺应你的要求。在我向你传授了部族制皮的技艺之后，你的作品将成为自然本身力量的体现。$B$B要学会部族制皮，你只要跟我交谈，我就会把我所掌握的知识都传授给你。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (5148, '你带来了最好的贡献，大自然会顺应你的要求。在我向你传授了部族制皮的技艺之后，你的作品将成为自然本身力量的体现。$B$B要学会部族制皮，你只要跟我交谈，我就会把我所掌握的知识都传授给你。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (5166, '你还没有理解吗?这次旅程本身就是你的终点。你感觉不到战争留下的伤痕吗?你所经受的痛苦呢?$B$B你幸存了下来，并且变得更加强大，这件胸甲只是你能力的微不足道的体现。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (5167, '他们会在你出现的时候闻到同类的味道，$N。以他们自己的恐惧为武器击溃他们吧!$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (5217, '干得好，$N。炼金师艾伯塔顿不用费什么工夫就可以对这东西进行分析，然后制造出可以中和瘟疫的药剂。如果能把足够的解药散播到空气中，我们就有可能削弱这个地区的天谴军团。\r\n\r\n毫无疑问，这是一场持久而严酷的考验，我们需要不断的攻击这些瘟疫之锅，把我们的药剂倒入锅中。只要我们能坚持下去，在全面的战争开始的那一天，我们就会对天谴军团占有压倒性的优势!\r\n') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (5220, '啊，这些对研究来说已经足够了。干得好，$N!\r\n\r\n现在，事态已经在我们的掌握中了。我们需要制造一系列试剂，当这些试剂与瘟疫之锅中已有的物质结合之后，那些原有的毒素就会被中和。\r\n\r\n我们只有把解药直接倒进瘟疫之锅里才能达到这种效果。炼金师艾伯塔顿对这类事情有更深的了解，所以你最好尽快找他谈话。\r\n') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (5223, '干得漂亮，$N!我们现在可以用这三口瘟疫之锅来对付天谴军团了。如果科尔苏加德对这些地方的控制力不像现在这样强大的话，我敢说你已经把它们全都关掉了!\r\n\r\n炼金师艾伯塔顿将对中和这口锅中的毒素的问题进行研究。现在，控制西瘟疫之地的最后一口瘟疫之锅的时机终于到来了!\r\n') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (5226, '恭喜你，$N，你已经为我们打开了最后一口瘟疫之锅!炼金师艾伯塔顿将很快找到中和这口锅中的毒素所需的试剂。\r\n\r\n至于你，我敢肯定瓦罗菲斯特指挥官会亲自向你表示感谢。没有你，我们反抗天谴军团的斗争决不会有这么大的进展。谢谢你，英雄!\r\n') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (5243, '干得好，$C。你已经证明了在宽容别人的同时，你会勇往直前地消灭科尔苏加德的爪牙。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (5261, '确实如此。我正在找人帮我捕猎那些狼!你要帮我吗?\r\n') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (5305, '你确定这是你想要的吗?成为打造战锤的铁匠?记住，你将永远都不能再打造刀剑和战斧了。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (5342, '好极了!现在，我掌握了巴洛夫家族的权力和财富!\r\n\r\n<阿莱克斯扔给你一只大口袋。>\r\n\r\n你这肮脏的$r，这是你应得的。\r\n') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (5507, '太好了!你对银色黎明做出的贡献必将永载史册，$N。你完成了我的要求，现在我很高兴能为你提供我们的披肩。只要你一直保持在银色黎明中的声望，你就可以从任何银色黎明军需官那里购买到这些披肩。$B$B我的$g兄弟:姐妹;\r\n，为了银色黎明而战!') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (5522, '啊，很好。你根本不知道你在为谁效力，对吗?但是你现在将会知道真相。不要害怕─我不是那个所谓「主人」的仆从。我是莱尼德·巴萨罗梅，银色黎明的高层官员。$B$B我欺骗了丁奇，让她派你来到我这里，并把龙蛋送了过来。看来我的计谋成功了，如果龙蛋落到了它原本应该被送去的地方，一股巨大的力量就将落入邪恶势力的手中。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (5542, '干得好，$N。来，休息一下。让我们吃点东西，然后谈谈以前的事情吧!$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (5544, '愿圣光永远照耀着你!祝福你，年轻的$R。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (5621, '你出色地为伊露恩完成了任务，因此我感谢你。$B$B请你收下这件袍子，这是我对你的感谢。它标志了你已经在我们当中赢得了自己的位置。如果你愿意的话，请带着荣耀穿上这件袍子吧。$B$B愿艾露尼与你同在，伊露恩与你同在，$N，再次谢谢你。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (5742, '弗丁的救赎是一个困难的任务，你准备好了吗?$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (5848, '<提里恩看到画以后几乎崩溃了。>$B$B<他开始像疯了一样掩面哭泣。>$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (5903, '这些就足够了，$N。谢谢你。看看它们……密密麻麻地抱成一团。我都有点为十字军感到难过了，但是为了让他们得不到那座伐木场，我们必须这样做，对吗?\r\n') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (5921, '「就此开始，自然之父塞纳-马恩省留斯。就此开始。」\r\n\r\n德迪利特伸手在空中迅速地作了几个手势，一道微弱的光环罩住了他。\r\n\r\n「你要领悟的第一种自然的力量就是熊的力量。我将指引你理解这种力量对德鲁伊所具有的意义，但是从现在起，你必须信奉并宣扬这一信条，永不改变!」\r\n') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (5922, '「就此开始，自然之父塞纳-马恩省留斯。就此开始。」德迪利特伸手在空中迅速地作了几个手势，一道微弱的光环罩住了他。「你要领悟的第一种自然的力量就是熊的力量。我将指引你理解这种力量对德鲁伊所具有的意义，但是从现在起，你必须信奉并宣扬这一信条，永不改变!」') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (5923, '年轻的德鲁伊，很高兴你在此踏入正途。现在是你大步迈向更广阔世界的时候了。\r\n\r\n我们都向往着为自然效力。动物和植物是我们的朋友，也是我们力量的泉源。我们选择为它们，也是为守护自然的平衡而奉献自己的一生。作为进入这个世界的第一步，你首先要学习的是的熊之道，以及肉体和心灵所蕴含的力量。\r\n\r\n准备好了!\r\n') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (5929, '在你回到德迪利特面前的时候，他在自己面前的空气中画了一个无形的符记。一股力量光环笼罩着这位微笑着的德鲁伊。\r\n\r\n「我感受到了你的智慧，年轻的$r，在我们第一次见面的时候它并没有体现出来。你的眼神体现出了你的力量和求知欲─虽然这种意愿还没有集中起来。现在你要学会如何集中你的力量，并适应熊的天性，让它为你所用。」\r\n') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (5930, '在你回到德迪利特面前的时候，他在自己面前的空气中画了一个无形的符记。一股力量光环笼罩着这位微笑着的德鲁伊。「我感受到了你的智慧，年轻的$R，在我们第一次见面的时候它并没有体现出来。你的眼神体现出了你的力量和求知欲─虽然这种意愿还没有集中起来。现在你要学会如何集中你的力量，并适应熊的天性，让它为你所用。」') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (6028, '格雷戈做得很好。他跟热砂企业打交道已经有些日子了，在哥布尔的谈判「艺术」方面俨然成了个专家。虽然哥布尔只对付钱最多的人表示忠诚，但是他们也明白并且尊重外交的价值。这样他们才能不断有新的顾客……\r\n\r\n不管怎么样，银色黎明需要你的帮助。请收下这个，谢谢你。\r\n') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (6061, '我已收到来自大地之母的指示，你做得很好。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (6064, '我知道，我知道……你想知道下一个任务是什么，对吧?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (6147, '这些傻瓜!我的计谋成功了!等着吧，$C。我们就要发动无情的攻击了!$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (6184, '第一个任务很简单，$N。进去，然后出来。侦察……$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (6185, '拉戈尔。弗雷多。特伊恩。都……死了……$B$B<弗林特紧紧抓住闭记。>$B$B他们在哪里?你有没有发现关于这个混蛋的更多消息，就是凋零者?$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (6344, '对，我是要找一个跑腿的帮我把包裹送到黑海岸去，你愿意帮我吗?\r\n') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (6389, '哈哈!谢谢你，$N!你做到了!我父亲的灵魂可以安息了，我也能安安宁宁地过日子了。\r\n\r\n再次感谢你。要是有什么我可以帮忙的地方，请尽管开口。\r\n') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (6501, '我早该猜到的……黑龙公主奥妮克希亚。真令我恶心……$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (6566, '你准备好接受这个任务了吗?$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (6568, '<米兰达拿着便笺看了看，然后笑了笑。>$B$B他最近怎么样了?我说的是罗卡洛。哦，过来，不要感到奇怪。这张信纸是故意留着空白的，其中包含了罗卡洛的意图和想法。从其中的内容来看，无疑是罗卡洛故意这么做的。如果你被抓了或者被杀了的话，其中的资讯也不会泄露!$B$B哦，不要介意!米兰达会帮你的，$R。我欠酋长的情。$B$B<米兰达微笑着。>$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (6601, '那只是单纯龙与龙之间的对话，$N，热空气多过于实际有用的资讯。牠们那些龙就只会采取豹而不实或者激进的行动。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (6846, '啊，命令下来了!他们说我可以随时发动攻击，那么……就现在吧!') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (6961, '吼吼，你好啊。我是冬天爷爷，作为熏木牧场的良好成员……我这里有「一应俱全的东西，包括所有熏木牧场精心为您准备的货物」，希望你度过一个愉快的冬幕节。\r\n\r\n如果你在这一年表现得很好的话，你将在冬幕节这一天收到来自于熏木牧场的礼物。哈哈。\r\n') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (7001, '我希望那些收集山羊皮的家伙具有与你一样坚定的决心，$N。$B$B按照这种速度，我们的兽栏很快就将爆满!$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (7002, '干得好，士兵。当我收集到足够的皮毛时，我会通知你的。$B$B继续好好干吧!$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (7063, '笼罩着冬幕的传奇与故事在这几年中已经慢慢地由广为人知变得较为隐密了。当我察觉到哥布尔们为了他们自己而正在帮忙提倡这个节庆时，我们族人的反应至少在某种形式上对于保住这些传说是有帮助的。\r\n\r\n你想要越过物质并且学习我们的过去是值得敬佩的特质，年轻的$C。我向你博学的天性致敬。\r\n') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (7169, '国王也已经听闻了你的英雄事迹，$C。继续为雷矛部族作战吧!$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (7281, '你的英雄事迹不会被埋没，$N。$B$B我必须抓紧时间来拯救他。我必须马上联系希瓦娜斯!$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (7361, '啊，虽然这只是数千个头颅中的一个，但是不管怎么样，你干得很出色。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (7383, '在神谕之树面前……你会感觉到自己几乎能把智慧抓在手里。让我继续说下去……$B$B随着泰达希尔的成长，大德鲁伊去祈求巨龙的祝福，因为在古代，那些巨龙的地位远在诺达希尔之上。但是时间之王诺兹多姆拒绝祝福泰达希尔，反而斥责德鲁伊的傲慢。和诺兹多姆一样，雅立史卓莎也拒绝了德鲁伊们的要求，但是没有她的祝福，泰达希尔的成长就会受到不良的影响，后果难以预料……') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (7402, '不要把这个告诉任何人，我们要把这些牙齿磨成上好的粉末，然后用这些粉末制作神奇的生发剂。这种东西在地精中非常流行!$B$B<诺雷格.雷矛下士向你眨了眨眼。>') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (7485, '嗯……冷静一下。正如我所承诺的那样，这里是给你的秘药。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (7486, '海达克西斯的声音从水面上传来……$B$B「选择最适合你的那件吧，$N。希望它可以在你和水元素的敌人作战时保护你。」$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (7507, '你原本可以在黑市上把这本书卖个好价钱，$N。尤其是保护这本书的封印已经被破坏，这使得任何具备必要知识的研究者都可以了解书中包含的屠龙秘密。$B$B也许我们应该给你一份丰厚的奖励……好吧，你必须付出巨大的努力才可以获得这份奖励。$B$B<莱德罗斯对着你咧嘴笑着。>$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (7509, '<莱德罗斯低声吟唱着一些你无法理解的咒语。>\r\n\r\n正如我所承诺的，$C，你的精灵之剑，奎尔塞拉。\r\n') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (7604, '很高兴和你做生意，$N!$B$B我谨代表瑟银兄弟会祝你在寻找萨弗拉斯的路上一路顺风!$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (7621, '牧师，你将要经历一严格的试炼，它将检验你学过的所有技能。$B$B我建议你听听我要说的故事。$B$B你要注意，你必须独自完成这个任务，所以我建议你与你的盟友保持一定的距离。任何来自外界的帮助都将导致严重的惩罚。$B$B命运引领你来到了这里。倚仗圣光的力量，为荣耀而战吧。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (7640, '干得好，$N。我们必须对那些躲藏在黑暗中的邪恶力量进行审判，这是我们应该极力完成的职责。你已经完成了牺牲和对恐惧谷灵魂的审判。$B$B你的下一步将是对一匹堕落的战马的灵魂进行牺牲和审判，它现在是死亡骑士达克雷尔的坐骑。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (7649, '干得好，$C。$B$B<博学者莱德罗斯从书中撕出一页。>$B$B我相信你会发现这个配方很有用的。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (7650, '干得好，$C。$B$B<博学者莱德罗斯从书中撕出一页。>$B$B我相信你会发现这个配方很有用的。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (7651, '干得好，$C。\r\n\r\n<博学者莱德罗斯从书中撕出一页。>\r\n\r\n我相信你会发现这个配方很有用的。\r\n') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (7703, '喔……你是真正的大王!我这辈子都从来没有看见过它!看来上面的油都要干了……也许那个可恶的精灵把它偷走之后就再也没用过它。好吧，我要对他说哈哈哈哈哈!$B$B看这里─护手上的标志是一个很古老的魔法印记，据说比戈多克巨魔的历史还要久远。好吧，作为戈多克的队长，我们曾经学习过一种知识─如何将印记还原并将力量重新注入护手中!$B$B我会为你这么做的，大王!给你，拿着护手，永远统治我们吧!$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (7729, '15.9磅!这一定是沾在衣服上的血液重量的最新记录!恭喜你，$C!$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (7783, '你再次将荣耀带给了部落，$N。死亡之翼的儿子已经不复存在了。当然，邪恶者兴风作浪。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (7785, '愿你在征途中受到护佑，愿主人为你的努力而祝福你。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (7786, '即使在梦中，我也没有想到会有这么一天。\r\n\r\n看吧，凡人!\r\n\r\n见证比这个世界还要古老的力量!\r\n\r\n见证这个曾经面对过泰坦和神灵的王者!\r\n\r\n复苏吧，我的主人!摆脱你的枷锁和束缚!复苏吧!\r\n') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (7787, '请你不要伤害我!拿着这把剑!拿着它!给德米提恩一个改过的机会!') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (7789, '<沙塔尔.碎颅发出兴奋的怒吼。>$B$B他们还能支撑多久?还要让多少联盟的渣滓牺牲在部落的面前才能让他们退却?只有时间可以说明一切，$C……') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (7792, '喔，毛料。我会确保所有人都知道你的慷慨捐赠。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (7810, '啊，我的朋友!仅有一件饰品是不能成为竞技场高手的!现在是证明你实力的时候啦!$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (7838, '你让竞技场的地面洒满了鲜血，我很高兴能宣布你成为竞技场的大师!') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (7874, '<沙塔尔.碎颅发出兴奋的怒吼。>$B$B他们还能支撑多久?还要让多少联盟的渣滓牺牲在部落的面前才能让他们退却?只有时间可以说明一切，$C……') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (7875, '<沙塔尔.碎颅发出兴奋的怒吼。>$B$B他们还能支撑多久?还要让多少联盟的渣滓牺牲在部落的面前才能让他们退却?只有时间可以说明一切，$C……') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (7876, '<沙塔尔.碎颅发出兴奋的怒吼。>$B$B他们还能支撑多久?还要让多少联盟的渣滓牺牲在部落的面前才能让他们退却?只有时间可以说明一切，$C……') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (7927, '现在你已经集满了整套传送门套卡。把它还给我们会让你和暗月马戏团之间建立永不断裂的联系。请允许我将一张更强大的暗月卡片回送给你做为酬谢你的一份薄礼。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (7928, '现在你已经集满了整套督军套卡。把它还给我们会让你和暗月马戏团之间建立永不断裂的联系。请允许我将一张更强大的暗月卡片回送给你做为酬谢你的一份薄礼。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (7930, '拿去吧，拿去吧!一个最适合$G国王:皇后;的奖品!恭喜你，我的朋友!$B$B如果你有更多奖券想要兑换，请告诉我!只要暗月马戏团还在这里，我就会兑换你的奖券。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (7936, '拿去吧，拿去吧!一个最适合$G国王:皇后;的奖品!恭喜你，我的朋友!$B$B如果你有更多奖券想要兑换，请告诉我!只要暗月马戏团还在这里，我就会兑换你的奖券。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (7940, '拿去吧，拿去吧!一个最适合$G国王:皇后;的奖品!恭喜你，我的朋友!$B$B如果你有更多奖券想要兑换，请告诉我!只要暗月马戏团还在这里，我就会兑换你的奖券。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (7945, '你快速搜查了树桩，找到一只带锁的小带锁箱!似乎你已经找到财宝了!$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (7981, '拿去吧，拿去吧!一个最适合$G国王:皇后;的奖品!恭喜你，我的朋友!$B$B如果你有更多奖券想要兑换，请告诉我!只要暗月马戏团还在这里，我就会兑换你的奖券。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8042, '我们会再见面的，$C。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8043, '我们会再见面的，$C。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8044, '祖尔金都会羡慕的，战士。去吧，征服你的敌人!') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8046, '去吧，你必须打败我们的敌人，$C。即使这意味着要借助圣光的力量。$B$B<金罗克浑身战栗。>') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8047, '去吧，你必须打败我们的敌人，$C。即使这意味着要借助圣光的力量。$B$B<金罗克浑身战栗。>') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8050, '$N，你要坚持不懈地奋力战斗。夺魂者会试图汲取你求生的意志。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8051, '$N，你要坚持不懈地奋力战斗。夺魂者会试图汲取你求生的意志。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8052, '给他们迎头痛击，让哈卡尝尝失败的滋味……') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8060, '太令人惊讶了……你能感觉到魔精的力量在这些珍宝中涌动吗?在古拉巴什帝国统治一切的时代，权力珍宝被作为流通货币。现在，赞达拉将利用珍宝中隐藏的魔精对抗哈卡的第二次崛起!\r\n\r\n你做得很好—你是赞达拉部族的朋友。依照我们的承诺，幻术师裹布是你的了!\r\n') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8080, '你拿到资源了!干得好!我会把这些资源送到我们的军需官那里，然后让他迅速把它们配置给我们的军队。$B$B谢谢你，$N。事实上，不断地完成这样的任务将是获得最终胜利的关键要素。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8081, '啊，你抢到了更多的资源木箱!没有资源补给的联盟肯定会一败涂地的!$B$B感谢你，$N。你的努力已经为我们所知，并且也为瓦里玛萨斯所知。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8102, '$C，这块坠饰上镶嵌的卡亚罗之石来自南海的卡亚罗山脉。卡亚罗山脉地带分布着许多活火山，那里的地质地形不断发生剧烈的变动。$B$B随着你与赞达拉巨魔的关系日益密切，卡亚罗之石的力量也会增强。利用这块石头的力量打败我们的敌人吧。就像卡亚罗山脉那样:迅速、致命、富有爆炸力……') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8106, '请收下这块坠饰，$C。运用它的力量消灭我们共同的敌人。$B$B戴在你脖子上的坠饰蕴涵着一段历史。科赞原本是赞达拉帝国的领土。但是地精的贸易大亨玷污了此地，将我的兄弟姐妹赶了出来。$B$B科赞现在是地精主城幽坑城的属地;\r\n但是在科赞被玷污之前，它曾是一片伟大的土地。即使在今天，我们仍将科赞看作神圣的地方。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8107, '请收下这块坠饰，$C。运用它的力量消灭我们共同的敌人。$B$B戴在你脖子上的坠饰蕴涵着一段历史。科赞原本是赞达拉帝国的领土。但是哥布尔的贸易大亨玷污了此地，将我的兄弟姐妹赶了出来。$B$B科赞现在是哥布尔主城幽坑城的属地;但是在科赞被玷污之前，它曾是一片伟大的土地。即使在今天，我们仍将科赞看作神圣的地方。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8108, '请收下这块坠饰，$C。运用它的力量消灭我们共同的敌人。$B$B戴在你脖子上的坠饰蕴涵着一段历史。科赞原本是赞达拉帝国的领土。但是哥布尔的贸易大亨玷污了此地，将我的兄弟姐妹赶了出来。$B$B科赞现在是哥布尔主城幽坑城的属地;但是在科赞被玷污之前，它曾是一片伟大的土地。即使在今天，我们仍将科赞看作神圣的地方。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8111, '看到这些海藻了吗?它们产自南海。我们往其中添加了一点魔精和魔法，它就成为一件非常有用的饰品。$B$B你是个德鲁伊，这对你来说相当容易。把它戴在你的脖子上，想像一下大自然、松鼠或是所有你们会喜欢的东西。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8112, '看到这些海藻了吗?它们产自南海。我们往其中添加了一点魔精和魔法，它就成为一件非常有用的饰品。$B$B你是个德鲁伊，这对你来说相当容易。把它戴在你的脖子上，想像一下大自然、松鼠或是所有你们会喜欢的东西。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8113, '$N，旅途愉快。继续取哈卡和他的爪牙的性命吧。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8118, '看看吧，$N。巫毒的力量更加强大了，不是吗?让原始的力量流遍你吧。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8124, '啊，你抢到了更多的资源木箱!没有资源补给的联盟肯定会一败涂地的!$B$B感谢你，$N。你的努力已经为我们所知，并且也为瓦里玛萨斯所知。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8142, '年轻人$C，你进步神速。或许是该让你加入塞拉利卡―赞达拉的精英组织了。数千年来，我们一直充当着赞达拉帝国的刺客，但是长期以来我们都很懒散松懈，这使得哈卡的力量不断扩张。当我们再次面对哈卡大军的时候，却没了巨魔同盟的支持。你和你的盟友必须帮助我们消灭血神和他的爪牙!$B$B带上这个坠饰，它会助你一臂之力的。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8143, '年轻人$C，你进步神速。或许是该让你加入塞拉利卡―赞达拉的精英组织了。数千年来，我们一直充当着赞达拉帝国的刺客，但是长期以来我们都很懒散松懈，这使得哈卡的力量不断扩张。当我们再次面对哈卡大军的时候，却没了巨魔同盟的支持。你和你的盟友必须帮助我们消灭血神和他的爪牙!$B$B带上这个坠饰，它会助你一臂之力的。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8144, '这是我们最后一次在塞拉利卡的庇护下进行交谈。你已经知道自己该做什么了。带上坠饰继续杀戮吧，绝不能让哈卡离开祖尔格拉布。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8146, '在赞达拉，猎人是倍受尊崇的职业。最好的猎人都要转至漩涡边缘接受考验。$B$B他们从海洋中心采摘一种名为漩涡之藤的海藻，然后将其编织成坠饰。这种坠饰在附魔后可以提高猎人狩猎时的准确度和力度。$B$B现在，我将一串漩涡之藤编织成的坠饰交给你。随着你与赞达拉的关系日益密切，我还会进一步强化坠饰。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8147, '在赞达拉，猎人是倍受尊崇的职业。最好的猎人都要转至漩涡边缘接受考验。$B$B他们从海洋中心采摘一种名为漩涡之藤的海藻，然后将其编织成坠饰。这种坠饰在附魔后可以提高猎人狩猎时的准确度和力度。$B$B现在，我将一串漩涡之藤编织成的坠饰交给你。随着你与赞达拉的关系日益密切，我还会进一步强化坠饰。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8148, '年轻的$C，旅途才刚刚开始。或许有一天你会去大漩涡看看世界的中心。$B$B愿力量和坚韧与你同在!') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8154, '你拿到资源了!干得好!我会把这些资源送到我们的军需官那里，然后让他迅速把它们配置给我们的军队。$B$B谢谢你，$N。事实上，不断地完成这样的任务将是获得最终胜利的关键要素。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8155, '你拿到资源了!干得好!我会把这些资源送到我们的军需官那里，然后让他迅速把它们配置给我们的军队。$B$B谢谢你，$N。事实上，不断地完成这样的任务将是获得最终胜利的关键要素。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
