INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8194, '哈哈，皆大欢喜!$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8251, '干得好，$N!秘法飞弹的说服能力总能让我感到惊叹。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8286, '我担心的事情还是发生了。新的危机已经来临。我的守护工作结束了……$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8294, '<沙塔尔.碎颅发出兴奋的怒吼。>$B$B他们还能支撑多久?还要让多少联盟的渣滓牺牲在部落的面前才能让他们退却?只有时间可以说明一切，$C……') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8297, '你拿到资源了!干得好!我会把这些资源送到我们的军需官那里，然后让他迅速把它们配置给我们的军队。$B$B谢谢你，$N。事实上，不断地完成这样的任务将是获得最终胜利的关键要素。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
