INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8300, '啊，你抢到了更多的资源木箱!没有资源补给的联盟肯定会一败涂地的!$B$B感谢你，$N。你的努力已经为我们所知，并且也为瓦里玛萨斯所知。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8305, '你可以感觉到这颗水晶的周围散发出巨大的悲伤。这股力量非常强大，你几乎以为自己会因悲伤而死在这里了$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8411, '这些是我需要的元素。我们谈谈吧。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8415, '很好，$C!让我们看看你的力量。\r\n') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8492, '你成功了$g小伙子:小姑娘;\r\n!我们会将那些铜锭堆放好并立刻做成有用的战器。就是有你这样的人努力才让我觉得为联盟效力是骄傲的。做的好，士兵!') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8495, '燃烧平原那里一定是个寒冷的天气。看这里，是$N，而且$g他:她;\r\n给我带来了一个礼物。20个铁锭!正是我一直想要的。$B$B我真的万分感谢你，$N。你是自己也是联盟的荣誉。现在离开这里去收集更多战争需要的东西吧。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8499, '喔，谢谢你，$C!谢谢你!这样就完成了20个，还有无法估计的数量要收集。你赢得联盟的感谢，你的努力会得到应有的奖励。等你收集更多的瑟银锭再次与我交谈吧。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8500, '很好，$C!做的很好。我会看着那些瑟银锭被放入机器并在铁匠和工程师的手上变成军队的补给。再次谢谢你，如果你有更多瑟银锭记得拿给我。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8512, '谢谢你慷慨的捐献，$N。我会让相关人士知道你的名字，这样高权者就会知道你为战争做的努力。看来我们好像永远都需要更多的轻皮。快点回来找我。\r\n') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8514, '天啊，你真的带了很多中皮来$g先生:女士;\r\n!我会将你的名字和功绩列在清单上。有你的帮忙我们很快就能将中皮收集好了!$B$B谢谢，$N!') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8520, '你提供的装备完美地符合我的要求，$N。我就是需要像你这样有才干的制皮师。$B$B你靠自己的能力赢得了蛮皮头盔的制作方法。现在我将这个图样送给你，希望你能从中受益。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8522, '你会因为这次任务的坚毅不拔受到表扬的，$C。我要把这些绷带收好，然后再和你谈谈有关收集更多符文布绷带的可能性。\r\n') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8545, '这对我们二个而言是个好的开始，$N。我又可以将这20个秘银锭放入库存清点数量了。我会记得把你的名字写在旁边，这点你可以放心。大家都会因为你的协助而感到高兴的。 \r\n\r\n你要记得回来找我因为你应该知道我们还需要更多的秘银锭。\r\n') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8549, '我们的努力让我们离战争越来越近。谢谢你努力帮忙收集这些宁神花。我保证它们会有很好的用途，而且你的贡献会被大家所认同的，$N。如果你还有意愿的话，请带更多的花回来给我。在那之前，愿大地之母指引你。\r\n') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8576, '先处理当务之急，$N!我们必须搞清楚艾索雷葛斯到底在石板上写了什么。$B$B你说他叫你做一个奥金浮标而这只是个概要图吗?可是他会用龙语写还真奇怪。那个讨厌的老家伙知道我看不懂这乱七八糟的文字。$B$B如果有用的话，我需要我的水晶球护目镜，一只500磅的鸡和〝龙语傻瓜教程〞第二卷。不需要按照顺序。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8580, '祈祷吧，朋友!希望我们能拯救诺格!$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8581, '这不是开玩笑吧，$C?你这么快就帮比雷凯基带火焰花来了吗?比雷凯基现在就要算算它们的数量!你让比雷凯基感到很开心，他会告诉大家$N是有史以来最棒的火焰花收集者。比雷凯基等不及开战了。现在我们真的把希利苏斯的天空点亮了，对吧$g兄弟:姐妹;\r\n?!') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8582, '很好。干得漂亮，$C。$B$B现在玛克林死了，我们至少知道天谴军团的行动被延缓了。黑暗女王对你的行动表示感谢，并希望给你一份礼物作为奖励。$B$B尽管我们不清楚天谴军团在剃刀高地的影响范围，但我敢肯定，我们很快就会揭穿他们的阴谋。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8612, '你真是个好厨师，$N。那些瘦狼排让我口水直流;\r\n我想如果少了几个应该不会被发现吧。总之，做的好。我会确定有人记录下你的贡献。如果你又有更多瘦狼排，你知道在哪里可以找到我。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8626, '你做的很好，$N。你已证明你不是普通的人类。$B$B我把这些东西给你，相信它们可以帮助你击败万恶的其拉虫人。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8656, '我没想到你会回来，$N。$B$B你已达到比最不朽的生物还伟大的命运。$B$B杀死克苏恩不只拯救了整个艾泽拉斯，你还削弱了超乎你能理解的宇宙大事。$B$B收下这个胸甲做为光荣的象征和伴随你行为而来的重担。$B$B愿它的力量能在等待着你的挑战中协助你，弑神者!$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8657, '你成功了!双子帝王的耳语停止了。$B$B收下这个奖励。看它一眼就会在其拉的心中注入恐惧…这会让他们想起死去的领导者还有杀死他们的人类。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8659, '我用你带来的材料和其拉虫人的鳞片制成了这套肩铠，凡人。希望它们能给你适时的保护也能让我们的敌人尝到恐惧的滋味。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8666, '我没想到你会回来，$N。$B$B你已达到比最不朽的生物还伟大的命运。$B$B杀死克苏恩不只拯救了整个艾泽拉斯，你还削弱了超乎你能理解的宇宙大事。$B$B收下这个胸甲做为光荣的象征和伴随你行为而来的重担。$B$B愿它的力量能在等待着你的挑战中协助你，弑神者!$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8699, '我会帮你把戒指上的宝石换下来。你会发现效果会变的比较……协调。\r\n') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8729, '干得好，$N。我将马上重新制作流沙权杖。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8733, '幽光沉默着，除了有时会发出一些低沉的哼声。真古怪，它可以借由思想与你沟通。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8735, '你准备好了吗?我们即将乞求庇护的世界准备好了吗?我不知道…我对玛法里恩有一定的职责，职责与荣耀…$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8736, '他已经获得了救赎，$N。他现在回到梦境中去纠正他所犯下的错误了。伊兰尼库斯对于玛法里恩和我的父亲来说是很强大的盟友。$B$B这些装备是给你的，$N，这是伊瑟拉亲手交给我的。你将在和异种虫群的战斗中用到它们。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8743, '在甲虫之锣的下方悬挂着一颗特别的水晶，也许是龙类所留下的?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8765, '很好，$N。如果你改变心意，我会在这里帮助你。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8766, '很好，$N。如果你改变心意，我会在这里帮助你。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8788, '这个礼物看起来好像已经被稍微摇晃过了几次。上面的标签写着:$B$B给最特别的$R$C。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8790, '好好使用这个物品，$N。让他们尝尝自己附加在别人身上的痛苦。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8843, '非常好!你肯定做出了巨大的牺牲才能获得这些荣誉徽章，为此你将得到充分的肯定。正是许许多多像你一样的冒险者让一切都变得不同的。$B$B如果你还有更多荣誉徽章的话，尽管来找我，我很高兴能为你做点什么。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8845, '非常好!你肯定做出了巨大的牺牲才能获得这些荣誉徽章，为此你将得到充分的肯定。正是许许多多像你一样的冒险者让一切都变得不同的。$B$B如果你还有更多荣誉徽章的话，尽管来找我，我很高兴能为你做点什么。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8857, '哦，我会利用这块甲壳雕刻出栩栩如生的小鸡的!干得好，$G小伙子:姑娘;!\r\n') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8859, '太棒了，时间刚刚好!干得好，$G小伙子:姑娘;\r\n!') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8904, '果然是真的。真是不可思议。怎么会发生这种事?让我想想。这后面一定有什么原因。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8922, '太好了!我正好需要它!\r\n\r\n你说是德莉娜派你来的?\r\n') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8923, '太好了!我正好需要它!\r\n\r\n你说是莫克瓦派你来的?\r\n') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8966, '你做了一件很棒的事，$N。一个灵魂得到了安息，但是如果我们想把这一切做个了断，就还有很多事要做。$B$B不幸地是，我不知道有着右半块护符的人死去的地点。不过不要害怕;我生前是个玩票性质的占卜师，所以我有另一个任务要给你，就是让我们查出最后一块护符的位置。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8967, '谢谢你让依萨利恩的灵魂得到安息，$N。现在，或许她会从她的女神那里得到平静。但是，如果我们要解决这个困境，前方还有许路复用作等着我们。$B$B不幸地是，我不知道有着右半块护符的人死去的地点。不过不要害怕;我生前是个玩票性质的占卜师，所以我有另一个任务要给你，就是让我们查出最后一块护符的位置。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8968, '我想，让这两个人的灵魂安息是最好的吧，虽然我并不喜欢他们。无论如何，我们有了该有的东西，这绝对是值得高兴的事!$B$B不幸地是，我不知道有着右半块护符的人死去地点。不过不要害怕;我生前是个玩票性质的占卜师，所以我有另一个任务要给你，就是让我们查出最后一块护符的位置。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8990, '谢谢你让依萨利恩的灵魂得到安息，$N。现在，或许她会从她的女神那里得到平静。而现在我们也有了重新组合的护符!但是前方还有最艰难的考验等着我们。$B$B为了让火盆调合好以召唤瓦萨拉克领主，还有几样物品需要收集，请带到这里给我。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8991, '我想，让这两个人的灵魂安息是最好的吧，虽然我并不喜欢他们。无论如何，我们有了该有的东西，而且护符也重新组合了!但是前方还有最艰难的考验等着我们。\r\n\r\n为了让火盆调合好以召唤瓦萨拉克领主，还有几样物品需要收集，请带到这里给我。\r\n') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (8992, '做的好，$N!科尔莫克不是那么坏的巨魔，至少他活着的时候不是，所以我希望他能得到应有的安息。现在我们有了完整的护符!但是前方还有最艰难的考验等着我们。$B$B为了让火盆调合好以召唤瓦萨拉克领主，还有几样物品需要收集，请带到这里给我。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (9001, '我会想念你的，$N。我欠你很大一份人情;\r\n我想我永远也无法报答你。$B$B希望你喜欢你的新头饰和胸甲，也希望它能保护你很长一段时间。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (9003, '我会想念你的，$N。我欠你很大一份人情;\r\n我想我永远也无法报答你。$B$B希望你喜欢你的新头饰和胸甲，也希望它能保护你很长一段时间。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (9022, '就因为这个勋章，这个诅咒才会降临到我们身上。瓦萨拉克领主显然知道如何掌握仇恨。$B$B我们会尽力找到剩下的碎块 - 希望是在我面临最终的死期之前。不过在那之前，让我们先来看看你的奖励。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (9034, '让他们再次尝到恐惧的滋味，$C。让他们感受不到仁慈。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (9039, '在最后一场战役中，我目睹莫格莱尼用这双靴子踩碎那些半死不活的人的头颅。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (9042, '记住，手腕是全身第五脆弱的部位!保护你的手腕，它们就绝对会保护你的手肘 - 或许啦。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (9050, '这些东西制作的非常划算，但是请小心，如果你太常让它们溅水的话是会生锈的。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (9055, '当你穿上这件护甲，你就会发现你的人开始改变。你会有不可思议的杀人能力。或许，甚至有一点嗜血。$B$B先说好我不会对你卷入的任何混乱负责……$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (9061, '腕甲准备好了。好好使用吧!') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (9075, '腕甲准备好了，$N。$B$B<林布拉特鞠躬。>') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (9081, '他们穿在你脚上很适合。对了，你最近没有再去提尔之手了吧?') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (9093, '你的梦行者腕甲准备好了，$N。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (9120, '我一生中从不期望见到这个东西……$B$B<蒙托神父好像开始流口水。>$B$B喔太好了，你会得到奖励的，亲爱的$g小男孩:小女孩;\r\n。你会得到丰厚的奖励。拿去。快!') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (9126, '你工作的很快，$N。快的跟狐狸一样……嘿，我有跟你说过我在理发厅四重唱的日子吗?$B$B提醒我最近找一天跟你说那个故事。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (9233, '他在纂写这本手册的时候一定是发疯了吧!我和欧玛利安－我们可是贼世至尊呢!$B$B总而言之，这也为我们开创了新的契机，$N。我现在可以制造更多新样式的物品了－当然，要付一点工资和材料费。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (9250, '大法师已经死了。$B$B别为他们的死而哀伤，$N。这一切都是命。就好像你手握守护者之杖也是命中注定……') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (9295, '多悲哀啊。这些话语，清楚的是要传达给某个士兵深爱的人，只是它永远也到不了目的地了。里面写的事情是多年前发生的;\r\n我不确定原本的收件者是否还活着。$B$B不过，还是有希望。有他写的名字和讯息，我大概可以找到那户人家 !需要一点时间调查，不过暴风城的图书馆员还欠我个人情……$B$B谢谢你把这个带来给我。有你的帮忙，我们终于能让某人的心灵得到平静。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (9299, '多悲哀啊。这些话语，清楚的是要传达给某个士兵深爱的人，只是它永远也到不了目的地了。里面写的事情是多年前发生的;\r\n我不确定原本的收件者是否还活着。$B$B不过，还是有希望。有他写的名字和讯息，我大概可以找到那户人家 !需要一点时间调查，不过暴风城的图书馆员还欠我个人情……$B$B谢谢你把这个带来给我。有你的帮忙，我们终于能让某人的心灵得到平静。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (9300, '多悲哀啊。这些话语，清楚的是要传达给某个士兵深爱的人，只是它永远也到不了目的地了。里面写的事情是多年前发生的;\r\n我不确定原本的收件者是否还活着。$B$B不过，还是有希望。有他写的名字和讯息，我大概可以找到那户人家 !需要一点时间调查，不过暴风城的图书馆员还欠我个人情……$B$B谢谢你把这个带来给我。有你的帮忙，我们终于能让某人的心灵得到平静。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (9320, '拿去吧，$N。在那里要小心。我们的数量没有那么大，不能容许太多人阵亡。$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (9367, '太好了!如果那些营火真的如你们所说的那样炽热的燃烧着，看来我们今年指派的火焰管理者都很尽责。谢谢你帮我去调查;来，收下这个做为我一点小意思。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (9388, '啊，所以它们真的还在燃烧。我很高兴;时间没到之前那些火焰不能熄灭。你做的很好，$N。收下这个和我的祝福。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (9389, '你回来了，也见过大陆上翠绿色的火焰了。你觉得怎么样呢?确切的说，那是一种罕见又美好的景象。不过，我知道，还是要有实质的奖励比较好……那么拜托你，收下这个做为奖励。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (20001, '马克斯韦尔是个聪明人，他的选择是公正的。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (20002, '你设法恢复了他们，破烂不堪，但仍然。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (20004, '这是一项简单的任务，它将证明你自己灵魂的颜色。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (20005, '非常好。你似乎准备好了。$BA去   之前的一条建议。像你这样的人，像我这样的人，我们总会被遗忘。记住这一点：这个世界上的人们永远不会记得你的名字，他们永远不会记得你的脸。但他们会永远记住你的事迹。$B ') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (39986, '我明白了，$n。也许贝壳币确实不需要征税。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (39987, '“你给我带来了这些？哎呀，你怎么知道我喜欢朗姆酒呢！你真是太贴心了。不过我们还是保密吧，好吗，$n？最近大祭司出台了一些愚蠢的规定，说什么要避免诱惑、不可纵酒之类的，巴拉巴拉巴拉。”') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (39988, '“你为什么把这个装满金币的袋子交给我？这是什么意思？过度征税？你想贿赂我来推翻法律？！”') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (40004, '$B$B有一支相当大的格诺人部队在那里扎营，从你告诉我的情况来看，他们很难对付。你已经证明了自己的价值，现在我要履行我的承诺。温特莱克斯的力量是你的！ ') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (40113, '死了？所有人？这个.. 这是我的错，因为我没有听从神灵的警告。$B$B他们将作为部落真正的战士而被铭记。但是盘子呢，n美元？告诉我我们没有白白牺牲朋友的生命。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (40115, '这只能说明我们还有很多东西需要学习。在你战斗过的守门人和大门上的新锁之间，我们似乎有我们的工作要做。我只能想象奥丹姆里面隐藏着什么秘密。但是，$n，这是另一个时间的故事。你为我们所做的超出了你的想象，为此，我永远感激你。我知道总有一天我们不得不再次向你寻求帮助。在那之前，我希望你能用这个来补偿你为帮助我们所做的一切。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (40120, '我必须非常感谢你所付出的努力。你让我们在这里更容易，但我觉得你必须再做一件事。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (40121, '随着时间的推移，该地区的自然平衡将得到恢复。我代表我自己和我的妻子非常感谢你。拿着这个，传家宝。愿它为你服务。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (40122, '啊，安西雷姆派你来的。好。很久以前，我给他转发了一封信，似乎这种神奇的干扰变得越来越强大。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (40174, '是的，干得好，小伙子。这一切都是为了船员的利益，是吗？') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (40175, '该死，看看这个美女，这么漂亮的岩石。来，给你点银子，谢谢你辛苦帮我弄到它。有些人真的应该学会不要在公共场合炫耀他们昂贵的石头，你永远不知道谁会去找他们，呵呵。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (40295, '多少？这比我们预期的还要糟糕。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (40299, '它确实像传说中所说的那样闪耀。$B$禁止这种规模的成就只能被奖励所掩盖。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (40395, '我的一本书？哈，我不是读者...$B$B可以吗？') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (40640, '干得好，孩子，你又搞定了！') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (40755, '我真是太高兴了！干得好，你的帮助节省了我大量的时间，正如你所知，时间就是金钱，尤其在这种情况下。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (40757, '<杰比不满地看着一小堆鼻烟。>$B$B嗯，这确实令人失望。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (40781, '啊，非常有趣！冰巨魔称之为“冬之灵”，也许它可能是某种元素生物。地精的版本相当明显，我怀疑甚至不算是传说，而矮人的版本...嗯，我对此非常熟悉。但不用再谈论这些，现在开始精彩的部分，哦呵呵，是的！') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (40821, '我感觉到你来找我，并且你知道我到底是谁。 看来我的过去终于追上了我，我必须承认我并不感到惊讶。 $B$B花点时间考虑一下你要说的话的严重性。 如你所见，我的一生充满了胜利和悲剧。 我亲眼目睹了伟大王国的没落，亲眼目睹了人们以权力之名所犯下的暴行。$B$B如果你在这里质问我过去的罪恶和我所犯的许多错误，那么我不会反击。 我会接受任何可能发生的后果。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (40828, '我不相信。 《魔法锁与钥匙论》，由可敬的艾格文本人撰写。在我自己的手中，经过这么长时间。$B$B请允许我仔细阅读这本古老文本的页面。我确信其中包含的知识已经过时了 麦迪文在锻造这把钥匙时使用了风化的页面。通过研究该书中概述的技术和方法，我们应该能够复制该过程并修复它。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41067, '似乎只有几页是完好的。 遗憾的是，这本书在这个州对我们没有用处。$B$B还有一个地方可以存放这样的书，但多年来没有人踏足那里。 卡拉赞图书馆...') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41069, ' 嗯，这里一切似乎都很顺利，非常感谢您对我们工作的帮助，在这里，拿着这个。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41070, '您的仁慈之举为铁树森林中饱受折磨的树人灵魂带来了安慰。 为此，我永远心存感激。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41137, '“我感觉到你来找我，而且你知道我到底是谁。看来我的过去终于追上了我，我必须承认我并不感到惊讶。$B$B花点时间考虑一下 你要说的话的严重性。你看，我的一生充满了胜利和悲剧。我目睹了伟大王国的没落，也目睹了人们以名义犯下的暴行 权力。$B$B') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (41148, '<你将头饰放在了墓碑上。墓碑上的铭文写着：“杜林·钢翼——多兰和西格伦挚爱的儿子。愿你的狮鹫引领你飞向最高的天空。”>') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (50004, '妈妈总是说，“不浪费，才不会缺少！”我真的对此铭记在心，并开始“改用”一些我能够伪装成的生物。地精、狗头人、穴居人...诸如此类的东西。什么，你觉得我不能像这个兽人一样吗？也许我不能，但你肯定可以。如果你足够聪明，世界上还有很多其他的伪装可供选择。你只需要去找到它们。带上这些笔记，祝你在这场唱哑剧的游戏中好运。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (50305, '好...在你浪费食材去尝试烹饪之前，让我告诉你一件事，最后能端上桌的东西，与你准备的调料有关，而不是与拆火的数量有关。嗯，但无论如何，烹饪，都需要火......') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (50326, '啊！！雷酒！好酒！') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (55042, '<沙艾克 将戒指套在自己的手指上咯咯地笑起来>最后，那个白痴得到了他想要的东西。也许现在人们不会再用这个名字来称呼我了！') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (60020, '谢谢你，那些娜迦凭借着强大的领袖在这肆无忌惮地攻击，没有了领头羊，他们将更容易被击败。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (70001, '干得好，$N，真的非常出色。你赢得了成为我的徒弟的位置，作为你的第一课，你必须阅读这本书。你团队的生存取决于你能够尽可能地提供补给。$B$B记住，你不能掉以轻心！在某些情况下，口渴可能是你最大的敌人。$B$B现在去学习吧，我的最新徒弟。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (70028, '很好。 尽管他们的数量众多，我们的武器永不休息，但我们会因为对生存的强烈渴望而战胜他们的征服计划。来吧，我有几样保存下来作为报酬。 选择你认为最适合的吧。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (70033, '你做到了许多人做不到的事情，$C，从今天起自豪地行走吧。 $B$B这位老兽人被过去所提醒，但从现在开始，他将憧憬未来。 $B$B我会焚烧这个头颅，并向我们的部落提及你是杀手，但祖先告诉我，你的道路只是开始，我亲爱的朋友。 $B$B我真心希望你有一天能找到你所追寻的东西。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `OfferRewardText_loc4`) VALUES (70053, '你是说它们的尺寸更小？这可以解释它们的饥饿感。$B$B然而，什么会让它们这么早离开巢穴，为什么它们全部离开巢穴？$B$B<瓦格思考了一会儿，然后转向你。>$B$B这是说好的报酬。我会进一步调查。') ON DUPLICATE KEY UPDATE `OfferRewardText_loc4` = VALUES(`OfferRewardText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (5, '哦？有我兄弟的东西？爽！幸运之光今天可算照到我身上了！') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (6, '你找到加瑞克.帕德福特了吗?我们终于可以摆脱这个恶棍了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (7, '你的猎杀行动进展如何，$N?你清剿那些狗头人败类了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (16, '在田地里工作很容易让人口渴，我一直想要喝点清凉的泉水。$B$B如果你有的话，我愿意和你做个交换。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (23, '啊，$N─我正想着你呢!你的狩猎行动怎么样了?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (24, '再次欢迎你，$N!你是来向我展示你完成狩猎的证明的吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (33, '嘿，$N。我有些饿了……你拿到硬狼肉了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (39, '你好，$N。你拿到汤玛斯对东艾尔文森林的报告了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (52, '你杀掉那些狼和熊了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (62, '你有什么要报告的吗，$N?你去过法戈第矿坑了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (76, '你好，$N。你有什么要报告的吗?去玉石矿坑察看过了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (87, '你好，$N。你找到我的项链了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (96, '你回来了，太好了!$B$B你的银松森林之旅怎幺样?花了不少时间吧?$B$B我很难判断你是否在那里获得了成功，因为已经有如此多的地方彻底堕落了。你所做的一切在邪恶的力量面前还是显得微不足道，但是即便是微小的胜利，有时都会和重大的胜利一样重要。净化那里的水对于你和所有的萨满都很重要。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (97, '嗯，$N?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (107, '斯通菲尔德的字条?我有好几年没有见到她了!不知道她到底有什么事……') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (110, '你好，很高兴再见到你，$N。我能为你做什么?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (111, '我都等不及去看朋友们的反应了！$B$B他们肯定猜不到！') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (114, '你把我的信带给汤米.乔了吗?他有说什么吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (117, '快点，朋友，动作要快$B要酿更多的酒来卖$B有人要酒呀没人要菜 $B一捆蛇麻草，就够酿酒来') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (131, '你好啊，$N。派克吃到我做的午餐了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (142, '$N，你收集到什么情报没有?找到那个信差了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (163, '啊，$N！回来的这么快？你肯定又被野兽追了吧？别在意你经历的那些周折，终究它们会让你更强大！$B$B……至少，你也没变得更差') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (169, '有什么事吗，$C?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (176, '没错，霍格一直让我们倍感头疼。你有关于他的消息?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (179, '那些狼好对付吗?它们的狂牙利爪没有伤到你吧?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (180, '你有什么事吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (211, '你已经接到我指派的任务了，$N。你拿到巫妖的骨匣裂片以作为完成任务的证明了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (216, '你参加对蓟皮熊怪的战斗了吗?只要我们两座基地之间的道路畅通无阻，我们占领整个梣谷的机会就可以大大增加。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (218, '$N!日记拿回来了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (232, '你好，我能为你做些什么?你是为了皇家药剂师学会的事情而来，还是仅仅来这里随便逛逛?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (233, '嗯?你有东西交给我?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (236, '嗯哼?你是不是被部落打败，馀烬被抢走了，只能蹲在路边哭?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (243, '嗯，我能帮你做些什么吗?你显然有事要找我帮忙，但也许我并不会帮你。你是否考虑到了出现这种情况的可能性?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (246, '请原谅，$N，我们有太多的事情要处理。如果你没什么事情要报告的话，我就去忙其他的事了。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (256, '我的马似乎还是一直受到惊吓，在夜里我也还是会听见那该死的狼嚎。拜托你，$N，把那些豺狼人都干掉!') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (264, '这块石头摸上去冰凉刺骨，但是显然没有人照看。这里遍地都是垃圾，棺材顶上的雕刻布满了又深又长的缺口，周围的植物长得比坟墓还高。$B$B没人关心是谁被埋在这儿。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (286, '你拿到雕像了没有?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (299, '你找到那些石板碎片了吗，$N?它们是阿度斯碎片、莫德尔碎片、高尔姆碎片和奈尔鲁碎片……') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (333, '你带来了巴格雷先生的信?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (334, '要买衣服吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (340, '我们仍然需要第10页，第11页，第14页和第16页才能完成第二章，$N。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (341, '你找到第18页，第20页，第21页和第24页了吗?只有找到了这些我们才能凑出完整的第三章。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (342, '我们只需要三页就能完成完整的第四章，$N。你找到第25页，第26页和第27页了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (347, '你找到瑞斯班矿石了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (351, '发现目标!你赫然看到石头上躺着一只……机器小鸡?!从机器小鸡中传出了声音:$B$B「太好了，你干得不错!这确实是我的母体，根据我的检测判断，它需要进行一定的启动动作才能够重新飞回藏宝海湾进行修理。请把定向器放到母体机器人里，剩下的它自己会去搞定!」') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (354, '你把阿加曼德一家人的尸体带来了吗?这群该死的野兽被彻底消灭了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (357, '$N，你拿到那本书了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (362, '你找到代弗林了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (366, '你的主人把你派来实在是愚蠢之极，我再也不会做天谴军团的奴隶了!') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (373, '嗯?我能帮你做些什么吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (379, '怎么样，那些游牧民有没有「自愿」把废土水袋交给你呢?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (381, '那些笨蛋……他们只会自掘坟墓，却从来都乐此不疲。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (437, '你击败了奈塔拉什了吗，$N?我们若要成功地击败腐皮豺狼人，就必须先干掉这个女妖。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (439, '$N，你回来了。你的调查有结果了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (440, '你好，$N。来布瑞尔有什么事吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (445, '找我有什么事吗，$C?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (449, '你找到那两个亡灵哨兵了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (451, '来幽暗城有什么事，$N?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (456, '快去完成这个任务，$N。在减少了夜刃豹和草刺野猪的数量之后再向我回报。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (457, '你的任务还没有完成，$N。杀死7只癞皮夜刃豹和7只草刺野猪后再回来找我。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (459, '为了证明我的怀疑，$N，请交给我8块魔苔。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (461, '就是这儿!没错!让我靠近点!') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (479, '我们必须迅速行动，彻底破坏掉他们的计画，否则，我们将失去整个银松森林的控制权。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (480, '动作快一点，$N!我们没多少时间了!') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (485, '发现目标!你赫然看到石头上躺着一只……机器小鸡?!从机器小鸡中传出了声音:$B$B「太好了，你干得不错!这确实是我的母体，根据我的检测判断，它需要进行一定的启动动作才能够重新飞回藏宝海湾进行修理。请把定向器放到母体机器人里，剩下的它自己会去搞定!」') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (506, '你好，$C!你找到高迪尔了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (513, '你看不见我正忙着吗，$C?黑暗女王坚持要在北裂境来的天谴军团压倒我们之前再制造一场瘟疫。南方的人类越来越有威胁，时间对我们来说是最宝贵的东西。你最好不是要拿什么鸡毛蒜皮的事情来烦我!') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (518, '你的任务还没有完成，$N。我要不要把你不称职的表现报告给沙琳德拉呢?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (521, '什么?你有什么要报告的?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (530, '你砍下他的手了吗，$N?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (532, '你干得怎么样了?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (543, '你好，$N。小心别踩在我的外套的下摆上，这身套装可是刚做的。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (545, '你去消灭达尔然遗迹周围的巡逻队了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (547, '你拿回我的剑了吗，$N?如果高级执行官达萨利亚知道我这么蠢，一定会把我吊死的。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (549, '除了在这儿站着，你就没什么别的可以做的了，$C?作为一个高阶执行官，我还有很多重要的事要做，没闲工夫对着你这张坑坑洼洼的脸打发时间!') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (556, '找到石雕了吗，$N?魔导师很想揭开其中的奥秘。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (566, '啊，$N。你是不是杀掉了瓦杜斯男爵来拿赏金的?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (581, '$C。给我血顶部族的獠牙，以此来证明你确实猎杀了他们。$B$B快把你的战利品给我看看。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (586, '虽然我的眼睛鼻子耳朵全都给煮没了，但我还是能感觉到你在害怕。$B$B哈哈!你就是死也不可能完成这个任务……') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (590, '不错啊，朋友……干得真不错。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (596, '血顶部族总有一天会被我们暗矛部族彻底粉碎!你把他们的项链拿回来了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (598, '劈颅部族将我们拖入了战争中，他们定会遭到诅咒!你完成任务了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (618, '把我的弯剑抢回来没有，$N?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (619, '这是一条已经被遗弃了很久的救生艇。小艇的两舷上布满了划痕，油漆的字迹已经显得很斑驳了:$B$B「斯莫特的复仇」') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (676, '我连斧头都没时间磨，更别说离开哨所去杀那些整日与部落为敌的野兽了。$B$B你看起来连最基本的作战经验都没有，更别说是个学有所成的$C了，你来找我干嘛?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (679, '我看你的勇气最终还是消退了。我的直觉似乎是对的:你一直都是在虚张声势而不具备真正的实力。$B$B要嘛带着野兽的头颅回来见我，要嘛就永远都别回来。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (717, '虽然很久以来黑龙的监狱一直被强大的魔法力量所保护着，但我们还是不能让布莱克拉席和赫玛图斯有任何逃脱的机会。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (744, '这个头饰无疑是给我兄弟的最好的礼物。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (753, '看来你是刚从平原那边回来的吧。你带我母亲的口信来了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (754, '不要耽误时间，$N。冰蹄之井的污染一定要尽快清除!') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (757, '你完成力量祭仪了吗，$N?我要求你通过杀死部族之敌―刺背野猪人来证明你的英勇。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (758, '雷角之井的水仍未得到净化，$N。你必须马上完成净化仪式!') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (760, '最后一口井还是又臭又脏，$N。你不能松懈!') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (763, '欢迎来到我的村庄，$C。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (770, '你好，$N。你在平原上的狩猎进行得如何?你听到鬼嚎的吼叫声了吗……?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (771, '等你收集到水井周围的水井石和大树下的琥珀颗粒之后，我就可以为你准备先知之水了。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (776, '你找到阿兰其亚了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (786, '半人马一直都是部落的心头大患，我们决不能让他们的进攻计画得逞!') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (792, '要想证明你的确选择了与火刃氏族为敌，那么你首先必须杀死那些邪灵劣魔。完成了这个任务之后再回来向我复命。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (793, '很少有敌人像龙那样可怕，也很少有龙像布莱克拉席和赫玛图斯那样残忍。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (794, '你完成任务了吗，$N?你把燃刃勋章带回来没有?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (806, '$N，你找到费索了吗?我们必须把费索和其他火刃氏族的余孽从我们的领土上清除掉!') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (825, '只要我们能搞懂人类是如何使用那些奇特的机器的，我们将来就更有希望在战场上击败他们。$B$B这些新的知识会让部落变得更加强大。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (831, '你没看到我正忙着吗?没什么要紧的事情就别来打扰我……') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (843, '巴尔莫丹矮人的到来让很多无辜的牛头人失去了生命，或者被迫离开了他们世代生活的家园。我们必须夺回自己的领地!') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (845, '你杀掉多少斑马了?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (848, '$N，你找到这些孢子了吗?我必须制造一种药剂送给雷霆崖的同事，而这种药剂正需要这种孢子来配制……') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (851, '$N，你找到维罗戈了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (855, '$N，你的任务完成了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (861, '你好，找我有事吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (862, '$N，找到足够多的掘地鼠了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (863, '我能帮你吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (869, '$N，你拿到那些迅猛龙的头了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (870, '$N，你去过遗忘之池吗?有没有发现什么?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (877, '你去过死水绿洲了吗?在死水绿洲的湖水下有地缝吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (885, '你有一种新的决心，$N。一种来源于痛苦的决心……$B$B你承受着瓦希塔帕恩之死的痛苦吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (890, '$N，你有什么要托运的吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (895, '有什么事吗?我能帮你什么吗?有需要托运的货物吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (899, '我又想起了家人的残肢断臂，想起了那熊熊燃烧的家园……我的家园。$B$B我要让那些野猪人血债血还!') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (908, '你找到深渊之核了吗?没有它的话，我们就无法得知暮光之锤究竟在那里做什么。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (909, '啊，又见面了，$N。我正在像往常一样观察海洋的波涛。什么风把你吹到这里来了?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (913, '任务完成了吗?你杀掉雷鹰了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (921, '月井里的水源自永恒之井，这个蕴涵着强大的魔法能量的古代源泉曾给我们的世界带来的巨大的恐慌。$B$B德鲁伊们充分利用月井的特性来修行，而哨兵们则将它视为月神伊露恩的祭坛，但是无论是谁，都不许再使用魔法。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (922, '你好……$B$B请问你有事吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (924, '恶魔之种仍然存在，我能感受到它的魔力……') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (927, '$N!你有东西给我吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (928, '你好，$C。是什么事让我们能在此愉快地会面呢?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (929, '你好，$N。完成你的任务了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (934, '神谕之树、大德鲁伊和德鲁伊们一起密切关注着泰达希尔的成长。但是虽然我们有了一个新家，但我们还没有重新得到不朽的生命。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (968, '你好，$G先生:女士;。$B$B你对我的书感兴趣吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (992, '欢迎回来，初级勘探员$N!你完成我交给你的任务了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (1013, '你找到那本书了吗，$N?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (1062, '巨木谷就在西北边，$N。去吧。把恐惧深深地烙入这群破坏大地的地精心里吧!') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (1065, '你好啊，有什么事吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (1068, '树灵们正因为它们的同胞被无情屠戮而恸哭，$N。你必须马上把伐木机XT:4和XT:9毁掉，否则，恐怕石爪山将永远不得安宁。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (1086, '如果风险投资公司在那里确实有一座空港的话，你就必须找到它，$N。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (1087, '看，在这里想要引导魔法就像是用竹篮打水一样。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (1088, '当我的主人吩咐我来石爪峰的时候，我一直希望能消灭那些暗夜精灵……那些占据了我们古老而神圣的艾萨拉圣殿遗迹并玷污了它的蠢货……可是奥达努斯居然从我手里溜走了。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (1090, '小心，巡逻兵和工人经常会在这一带走动，要是我们被抓住可就惨了。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (1103, '你有灵契吗，我的$G兄弟:姐妹;?$B$B我知道另一个人在打败那个堕落的水灵之后有了麻烦―似乎他等得太久，最后因为不耐烦而离开了。我不希望看见这样的事情再次发生，为此我决定继续等在这里，直到确信没有人再需要我的帮助为止。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (1104, '喂!你找到毒液了吗??') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (1105, '我兄弟的新燃料设计进度很快，这让我感到十分焦急。我要尽快开始制造龟壳燃料箱的工作了。$B$B$N，你弄到龟壳了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (1110, '$N,你在闪光平原上到处搜过了吗?弄到足够的零件了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (1112, '你去过棘齿城了吗?取必零件了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (1127, '你搞到赞吉尔的药剂了吗，$N?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (1131, '你打败邪恶的钢齿土狼了吗，$N?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (1153, '我又见到那些旅人了─他们连一块矿石也不卖给我。我唾弃他们，因为他们不愿为酋长效力。$B$B这些旅人会像懦夫一样在战场上死去，而不会像所有部落的勇士一般在战场上奋勇作战。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (1154, '你研究完这本书之后就把它给我拿来，在你归还书之后，我才会向你发问。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (1164, '杀光他们，把他们的头拿来!') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (1184, '$C，你还没去千针石林吗?我希望马上就能听到来自摩克塔的消息。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (1189, '你能相信普兹克居然在赛车里加了一桶沙吗?我车座下面放着一桶沙还怎么挂到最高档?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (1204, '你找到分叉的舌头了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (1218, '啊，调味料!给我们的生活来那么一丁点调味料是大有好处的……你说是吧?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (1221, '$N，你拿到蓝叶薯了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (1239, '你还有别的事要报告，$N?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (1253, '你在树荫旅店的废墟里找到什么证据了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (1262, '你是从尘泥沼泽的蕨墙村过来的?纳泽尔过得如何?他在那里的生意又如何?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (1273, '你找到雷瑟了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (1276, '你好啊，$C。我能帮你什么忙吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (1318, '哈哈，你还没有找到它，是不是，老大?也许那只是一个故事……很难相信那个可恶的精灵居然可以从我们戈多克的大王身边偷走东西!') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (1321, '你找我，$C?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (1322, '你找到蜘蛛的毒囊了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (1358, '你有个包裹要给我?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (1361, '你的任务还没有完成，$N。我要不要把你不称职的表现报告给沙琳德拉呢?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (1364, '来守望堡有什么事吗，$R?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (1366, '你收集了多少半人马的耳朵啦，$N?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (1393, '保险箱的钥匙孔里填满了黑色树脂，看来是不可能打开的。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (1434, '有一个牛头人同伴警告我说，萨特的内心世界可能与它们的外表截然不同。他相信它们并不是表面上看起来的那么简单，也许是邪恶扭曲了它们的本性，但我是看不见这些事情的。$B$B我只是看见了它们无情地屠戮弱小，不惜一切地追寻黑暗的力量。$B$B我将继续履行歼灭它们的职责，直到酋长给我新的指示。在那之前，我不会对它们有丝毫的同情。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (1485, '控制住你用魔法召唤出来的生物是非常重要的一件事情。你得弄清楚，学习术士的魔法与行事之道并非是什么有趣的事情，若是在你做好准备之前，就教导你过于高深的知识是会让你丢掉性命的。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (1486, '我对这些生活在洞穴中的变异生物身上的皮非常感兴趣。你弄到足够的皮了吗，$C?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (1487, '$N，我们这些纳拉雷克斯的信徒需要你的帮助。我们的人数随着领袖陷入了他扭曲的梦魇而不断地减少。因此，我们已经没有足够的力量去对付那些占据了洞穴的堕落生物了。$B$B我请求你，$C，进入那些洞穴，把那些该死的变异生物都杀光吧!') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (1489, '你师傅们把你派到这里实在太蠢，因为我再也不是天灾的奴隶了！') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (1491, '我要的哀嚎香精在哪里?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (1492, '你是想搭下一班船呢，还是你有什么东西要送?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (1501, '你找到维尔加石板了吗，$N?没有它的话，我是不会和你说任何事的。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (1504, '虚无行者是一种强大的生物。我现在还清晰地记得当年我与它战斗时的情景，$N。经过了这么多年，我的虚无行者已经很少与我发生冲突了，我想这也许是它想让我放松警惕的缘故吧。$B$B牢牢记住这一点，$N。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (1515, '啊啊啊……有人来救我了吗……') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (1526, '火盆只有你的三分之一高，看起来没什么特别，只是在光滑的金属围栏上刻有文字。整座火盆都没有任何风化侵蚀的痕迹，摆在顶端的小碗摸上去十分冰凉。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (1527, '嗯，这不是$N吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (1535, '我正在准备交给你下一项任务。你装满水囊了吗?$B$B我知道这些野猪人会拼命保护他们的水源，即便是一滴水对他们来说也是一笔巨大的财富。偶然降临贫瘠之地的毛毛细雨对他们而言也不啻为一场盛筵。他们将水视为神圣之物，因为它是如此稀少。你明白了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (1581, '你好，$N。你弄到我要的药剂了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (1598, '要我自己去把书从图书馆里偷来实在是太丢人现眼了，他们那帮蠢货可真是帮我大忙了。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (1657, '你把我们的「礼物」送给南海镇的居民了吗?$B$B<黑暗召唤者雅恩卡邪恶地笑了起来。>') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (1679, '你把酒调换了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (1688, '即使是睿智的长者有时也会被年轻貌美的女人迷惑，$N。你得牢牢记住这个忠告。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (1689, '在你制服虚无行者之前，我没办法教你怎么控制它。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (1803, '也许你所追寻的东西只是一团空气，$N，但真相往往就隐藏在最夸张的谣言之中。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (1898, '你好。我能帮上你什么忙吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (1899, '你成功了吗，$N?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (1918, '哦，你需要什么吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (1954, '你拿到地狱火宝珠了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (1956, '你去过奥达曼了吗，$N?把那个黑曜石守卫干掉了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (2160, '嘿，伙计!快进来，坐在火堆边来上一大杯好麦芽酒暖暖身子吧!') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (2161, '你好，$C。欢迎来到剃刀岭!') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (2205, '有事吗，$C?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (2242, '你有关于塞希尔的事情要报告吗，$N?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (2259, '你好，$N。我一直在期待着你的到来。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (2278, '石头守护者的声音如此雄浑，你在聆听他的叙述的时候感到灵魂的震撼:$B$B「你必须首先达成圆盘的输入融合要求。一旦你满足了这个要求，你就可以获得一份可携式的资料存储资料。请先确认你已经完全阅读过该资料库中所存储的资讯。」') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (2300, '你去哪儿了，$N?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (2381, '不管怎么样，你现在看来还是完好无缺的。你找到我要的宝藏了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (2499, '你找到奥肯斯古尔了吗，$C?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (2603, '不要浪费我的时间，$N。我们没什么可以讨论的─除非你已经找到了我要的东西。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (2604, '不要浪费我的时间，$N。我们没什么可以讨论的─除非你已经找到了我要的东西。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (2751, '青铜，$N!更多的青铜!!') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (2758, '你能成为下一个被加尔文亲自训练的铁匠吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (2764, '不要打扰我，我正在为全山谷的锻造冠军赛加紧训练呢。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (2766, '发现目标!你赫然看到石头上躺着一只……机器小鸡?!从机器小鸡中传出了声音:$B$B「太好了，你干得不错!这确实是我的母体，根据我的检测判断，它需要进行一定的启动动作才能够重新飞回藏宝海湾进行修理。请把定向器放到母体机器人里，剩下的它自己会去搞定!」') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (2842, '我在她身上倾注了毕生的心血，但在运输结束之前，我们的德莱尼水晶没有了。这真是奇耻大辱。谁知道呢，或许做只小鸡生活会更好?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (2940, '你找到了什么吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (2946, '这个看起来很眼熟的底座从滚烫的沙子里突了出来。这其中一定有什么原因……') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (2953, '超级清洁器5200型等待着清理脏兮兮的东西，它需要三枚银币才能启动!') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (2954, '在进一步发展之前，你必须知道石头卫士要让你干什么……') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (2964, '很好，很好，你正是我要找的$r……$N，探险者协会永远的朋友和盟友!卡尼克已经把事情大体上跟你说过了，对吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (2965, '$N，我很高兴你能过来与我进行交流。贤者图希克跟我说过你在奥达曼的冒险历程，我相信我这里有些新的资讯要告诉你。你应该可以找到对我们都有利─并且我们都感兴趣的秘密。$B$B我要继续说下去吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (2966, '这个看起来很眼熟的底座从滚烫的沙子里突了出来。这其中一定有什么原因……') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (2967, '欢迎回来，$N。那张圆盘对你有用吗?或者它根本就是个没用的东西?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (2968, '随着风吹过，变化的迹象开始散播。你是不是想要知道我对奥丹姆的看法呢?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (2977, '欢迎回来，$N。那张圆盘对你有用吗?或者它根本就是个没用的东西?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (3095, '啊，你来了，很好。我听说有一些人也逃脱了「死亡」，并纷纷涌入镇子里。或许我们有一天会重归安宁。$B$B你应该感谢希瓦娜斯，她给了你自由……心灵和肉体的自由。虽然你仍遭受着瘟疫的折磨，但你现在至少可以随自己的心愿来去了。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (3369, '我能帮你什么忙吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (3370, '我能帮你什么忙吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (3373, '当你接近伊兰尼库斯告诉你的精华之泉的时候,他的声音再次出现在你的脑海中。$B$B「是的，凡人，这个精华之泉将会救赎我留在这颗宝石内的心智中未污染的部分。将宝石放在泉水中，然后让绿龙族的魔法净化我身上的堕落和污染元素。只有这样我才能得到真正的解脱，只有这样绿龙军团才能够获得管理阿塔莱的权利。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (3375, '要制作另外一个瓶子，我需要一瓶法力药水、一块煤和一些蜂蜜饮料。$B$B另外，还需要很多很多的耐心。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (3377, '请允许我讲完我的故事。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (3381, '我仍然在这里执行主人吩咐的任务。我其实可以随便要求你提供什么东西来做为见到主人的代价，但是现在，我只要求每个旅人提供两根羽毛来完成我精美的箭。$B$B如果你不够小心的话，我可是会提价的。六枚金币听起来怎么样?$B$B就这样了，我现在就要求那么多。小心行事，我会暂时把价格保持在现在的水准。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (3402, '想要看看我的商品吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (3454, '火炬在空中悬浮着。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (3511, '你回来了!我真惊讶，$R。你知道那个恶魔真正的名字了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (3521, '请去收集我所说的那些原料，$N。埃沃隆需要我们的帮助。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (3528, '你打败了哈卡的化身了吗，$N?他的精华被封入我给你的卵中了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (3602, '邪恶的力量不会停下脚步来等你，蠢货。当你被干掉之后有的是事件来休息。现在，把水晶交给我。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (3630, '嗯嗯，你有什么事要我帮忙吗?很显然，我有的是时间，因为我的家乡现在正笼罩在一片辐射云里，而我却站在这里无所事事。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (3632, '嗯嗯，你有什么事要我帮忙吗?很显然，我有的是时间，因为我的家乡现在正笼罩在一片辐射云里，而我却站在这里无所事事。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (3634, '嗯嗯，你有什么事要我帮忙吗?很显然，我有的是时间，因为我的家乡现在正笼罩在一片辐射云里，而我却站在这里无所事事。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (3640, '如果你签署了这份文件并把它交给我的话，那事情就这么定了。\r\n\r\n我接下来要告诉你的是，签署这样一份保密协议是非常严肃的事情。我签了一份，我们的其它成员也都签了。你将要加入这个幸运的团体了，工程师$N! ') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (3642, '如果你签署了这份文件并把它交给我的话，那事情就这么定了。\r\n\r\n虽然我有时候会因为诺姆瑞根的问题对组织产生异议─特别是对那个愚蠢的技工大师欧沃斯巴克─但是，保密协议高于一切!你必须签署它，然后一生都要遵循它。 ') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (3823, '你的军服还没有沾上足够的血，士兵!') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (3825, '完成任务了?你有没有把当时的场景画下来?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (3861, '小鸡用它那双黑暗而凌厉的眼神盯着你，等着你给它喂食。$B$B「咕咕嘎!$B$B咕咕……咕咕……咕咕。」') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (3904, '你拿回我的葡萄了吗，$N?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (3906, '元素仍然处于混乱之中，$N。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (3907, '整个大陆很快就会被烈焰吞噬，快一点行动，$N!') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (3924, '你拿到说明书了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (4021, '你拿到旗帜了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (4082, '你回来了?你很有毅力，所以我当然要把任务交给你来完成，$N。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (4083, '鬼灵之杯在空中飘浮着，缓慢地上升和下降……就好像一颗将死的心脏在跳动。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (4123, '你拿到山脉之心了吗?对我来说，它是无价之宝。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (4186, '有没有伯瓦尔那里的消息?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (4263, '那个恶魔死了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (4322, '$N，你看起来一副精疲力尽的样子。也许你应该在火堆旁找个位子好好休息一下。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (4361, '你找到他了?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (4509, '他们都是笨蛋，$N!他们甚至没有想到在自己的周围潜藏着多么可怕的威胁，他们对联盟的仇恨最终会导致我们的毁灭!我不知道除了把他们直接丢到其中一个蝎巢以外，还有什么关于异种蝎威胁的证据可以给他们?\r\n\r\n对不起，你有什么消息要给我吗? ') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (4542, '你有什么事，$C?紧急通知?这是给我的?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (4603, '超级清洁器5200型等待着清理脏兮兮的东西，它需要三枚银币才能启动!') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (4604, '超级清洁器5200型等待着清理脏兮兮的东西，它需要三枚银币才能启动!') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (4641, '对于一个强大的战士来说，再厚的蝎壳都不值一提。下手强劲利落，你就会发现那些壳很脆的。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (4729, '基布雷尔正在和奥普斯激烈地争执着。>') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (4740, '你好，$C─今天哨兵部队能为你提供什么帮助吗?你是来询问 有关莫克迪普的赏金事宜的吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (4742, '勇气和耐心就是一切，$C!') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (4743, '不要浪费时间，凡人。奈法利安正在努力将他的邪恶散播到整个世界。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (4764, '你找到扣环了吗，$N?我的主顾愿意出大价钱买它。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (4784, '很快就好了，$N。我向你保证。我制作的披风绝对符合你的要求，它能使你在战斗中占尽上风。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (4841, '快一点，$N，我知道你还没有完成我交给你的任务。猎杀那些半人马，然后我就会给你一份奖励以表示感谢。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (4904, '萨利亚我好想你……') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (4974, '<索尔低吼着。>') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (4982, '找到了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (4985, '我听到你的脚步声了，$N。我的视力已经消退，但我仍然能感觉到周围的事物。你让那些受尽疾病折磨的灰熊安息了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (5002, '啊，$N。好久不见了。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (5047, '什么事?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (5064, '你找到恐怖图腾族到底在做什么了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (5088, '你杀死邪恶的毒蛇阿利卡拉了吗，$N?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (5122, '这个小教堂给了我抵抗内心中的腐化力量。如果离开这里，我就会变成一个死亡骑士。但是有一枚勋章，信仰勋章，它可以给予我离开这里所需的力量。\r\n\r\n$N，请帮我拿回这枚勋章。它被狂热的玛洛尔看护着，他是血色十字军的一员，居住在西斯坦索姆的血色十字军堡垒深处。 ') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (5143, '在你期望学习如何利用大自然提供的材料制作皮甲之前，你必须对它有所贡献。让我看看你为大自然奉献了什么吧，它会回报你的。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (5148, '在你期望学习如何利用大自然提供的材料制作皮甲之前，你必须对它有所贡献。让我看看你为大自然奉献了什么吧，它会回报你的。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (5166, '你做出了明智的选择，$R。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (5167, '这样一件东西以前从未被铸造出来过!') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (5212, '有些人说我担心太多了，我对他们说，「是你们太掉以轻心了!」') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (5213, '我们就快要揭开这种新的活性瘟疫的秘密了!') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (5214, '我受不了了，$N!你必须帮帮我!我要死了!') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (5217, '欢迎回到相对来说还算安全的冰风营地，$N。你在瘟疫之锅那边有什么进展要汇报吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (5230, '欢迎回到相对来说还算安全的亡灵壁垒，$N。你在瘟疫之锅那边有什么进展要汇报吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (5284, '<埃隆努斯正忙于将金币整理成堆。>') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (5305, '他的围裙!在哪儿?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (5342, '确保我得到这笔财产，你也不会吃亏的。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (5361, '你带来了什么消息，$C?啊—你是说我兄弟托送的消息?好吧，把报告给我吧!') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (5386, '当我想到油炸的血肚鱼时，我的蹄子便开始发痒，口水都快流下来了……你搞到鱼了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (5504, '啊，高尚的$C!你带来我所要求的银色黎明勇气勋章了吗?只要你把它们交给我，我就可以向你提供各种各样的披肩了。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (5505, '好了，给你，$N——这就是骷髅钥匙。我很确定它能打开通灵学院的大门。不过只有一个办法能检验它，我说，你就别在我这浪费时间了。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (5507, '啊，高尚的$C!你带来我所要求的银色黎明勇气勋章了吗?只要你把它们交给我，我就可以向你提供各种各样的披肩了。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (5511, '好了，给你，$N——这就是骷髅钥匙。我很确定它能打开通灵学院的大门。不过只有一个办法能检验它，我说，你就别在我这浪费时间了。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (5513, '啊，高尚的$C!你带来我所要求的银色黎明勇气勋章了吗?只要你把它们交给我，我就可以向你提供各种各样的披肩了。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (5522, '你就是那个去过黑石塔的$R，是吗?你弄到我要的东西了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (5542, '不要同情那些恶魔之犬，$C。它们是令人憎恶的东西!') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (5544, '你慢慢就会习惯它的味道的，$N。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (5621, '我们的真言术:韧这个法术非常强大，$N。它可以让我们的同伴承受更多的攻击，让他们在任何情况下都能生存得更久。但是我们的治疗更加无与伦比，世界上没有比牧师更加强大的医者了─你要牢记这些。你的力量足以轻易改变一场战斗的走向。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (5722, '尸体') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (5724, '你找到什么东西了吗，$N?我想知道为什么她的族人要做出无谓的牺牲，任何有关的线索都会对我们很有帮助的。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (5726, '你拿到了徽记吗，$N?$B$B它将是你渗透到火刃氏族中去的重要工具，我认为他们是部落的最大威胁，也是我们刚刚得到的和平的最大威胁。$B$B你会发现，当人类或是兽人受到贪欲和权力驱使时，他们会干出多么可怕的事情来。那些阴暗的勾当和隐藏的敌人终将露出真面目来。你将发现自己置身于一场你从未想像过的战争中。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (5727, '嗯，$C?他相信我们了没有?要不然就是事情比预计的更加糟糕?$B$B向尼尔鲁证明你的价值，这样我们就更容易进入暗影议会。我们可以利用他提供的大量情报找到真正的幕后主使。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (5741, '你拿到圣光权杖了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (5742, '朋友，请你坐下听听我的故事。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (5848, '画，$N。你找到画了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (5929, '只有当巨熊之灵让你回来的时候，你才可以回来。除非获得了它的祝福，否则你的训练是无法继续的。 ') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (5930, '只有当巨熊之灵让你回来的时候，你才可以回来。除非获得了它的祝福，否则你的训练是无法继续的。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (6026, '相信烟鬼吧，$C。你所能得到的奖励值得你费一番周折。那些银色黎明的家伙在付钱的时候可是非常吝啬的。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (6027, '啊，$N!很高兴再见到你。你拿到上古之书了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (6061, '练习你的技能，$N。去驯服成年平原陆行鸟。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (6064, '别担心，$G小子:小姑娘;!你要多多尝试才能知道自己该怎么做。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (6082, '你驯服蝎子了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (6147, '什么?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (6184, '你来得正好。很高兴见到你，$N。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (6185, '你真应该去格里安·斯托曼那儿报到。他是人民军的领袖，这是个专门负责保卫西部荒野的人民军组织，我敢说你是能帮他一些忙的。一般来说，你可以在哨兵岭的石塔周围找到他，那地方就在西部荒野中部的路边上。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (6283, '血怒撕裂者是个肮脏的生物!你可以在焦炭谷西部的山岭中找到她。$B$B只要干掉了她，血怒鹰身人就会乱作一团……然后我们就可以把它们完全消灭掉!') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (6301, '战争带来的持续破坏，还有那些想要从木材贸易中牟利的商人都深深地刺痛了我。我们所能做的就是尽量治愈大自然，种植盖亚之种，用新生的森林来抚平大地的创伤。你弄到我要的盖亚之种了吗，$C?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (6324, '$N，你回来了。你从幽暗城带来我们所需的物资了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (6342, '你是从泰达希尔来的?告诉我，那里的渔业近况如何?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (6381, '你所种下的种子将使得森林更加强大，使它可以抵御那些足够杀死所有新生命的堕落能量。它们将不断生长，防止死亡和破坏继续在这块土地上蔓延。$B$B你种下所有的盖亚之种了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (6481, '如果我们不能尽快解决威胁的话，也许我们会丧失整个石爪山地区。任何魔法都无法与土灵的力量抗衡。当高戈罗克清醒时，他的力量将因长期沉睡而减弱，你必须利用这个机会……去吧，$N!') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (6482, '你看见我的兄弟卢尔了吗?他几天前进入了森林，一直都没有回来……') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (6501, '我感到了你身上散发出的邪恶气息，$R。是什么让你被这种气息笼罩?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (6503, '我等待着你杀死先驱者的消息，$N。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (6522, '你有什么事，$N?如果你不断来烦我，那你一定是有什么你以为很重要的事情。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (6544, '托雷克被派去执行突袭银翼哨站的任务了，他取得胜利了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (6561, '愿大地之母与你同在，$N。$B$B世界和平是我们的目标。大地之母对整个世界有一个宏伟的计画，我们都在其中扮演了某种角色。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (6563, '搜寻水晶的工作进行得如何，$N?你有见到纳迦在采集它们吗?祖先保佑，希望我们能找到纳迦收集这些东西的原因。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (6564, '什么事，$N?你需要什么吗?对于纳迦正在收集的那些水晶，我还知之甚少。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (6566, '耐心点，$N。注意听!') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (6568, '我很少在这里见到部落来的$R。你给米兰达带什么来了?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (6601, '这是什么，$N?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (6621, '你击败了穆戈特酋长了吗，$N?你拿回他的图腾了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (6629, '你把格鲁迪格·暗云和他的手下都干掉了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (6822, '胜利在熔火之心向你招手，$N。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (6846, '我的军队已经整装待发，准备攻击。只要诺雷格.雷矛中尉一声令下，我们就会发起冲锋!') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (7001, '没有你的帮助，霜狼氏族的狼骑兵就无法获得足够的坐骑来进行作战。你干得很好!') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (7002, '在我们的一些战士帮助兽栏管理员捕捉巨狼的同时，其他人还需要去找一些将它们变成坐骑所必需的东西，比如缰绳和坐鞍。$B$B你必须去猎捕这个地区的山羊，也就是那些与雷矛骑兵的坐骑很相似的山羊!$B$B杀了它们，把它们的皮交给我。只要收集到足够多的羊皮，我们就可以开始为骑手们制作坐具了。霜狼部族的狼骑兵很快就将再次驰骋在战场上!') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (7061, '我敢打赌莫高雷以及谦卑的雷霆崖都非常欢迎你，朋友。我对选择去关注王国，人民以及其传说的人一直都非常的感兴趣，这就是你站在我面前的原因吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (7169, '整个基地中都在传颂你在战场上英勇拼杀的事迹!你对我们的敌人造成了沉重的打击，把他们杀得四散逃窜!为此，你在雷矛部族中的军阶获得了提升。$B$B这就是你的新徽记。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (7281, '他一定非常痛苦，因为只有他独自活着，而他的兄弟已经升华到了一个完美的境界。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (7361, '他们想要灭绝我们?他们自己才应该被灭绝。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (7383, '神谕之树、大德鲁伊和德鲁伊们一起密切关注着泰达希尔的成长。但是虽然我们有了一个新家，但我们还没有重新得到不朽的生命。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (7402, '放松一点，士兵。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (7485, '我的耐心让你免受痛苦。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (7488, '你拿到了网了没有，$N?我们必须驱散它所汇集的魔法能量!') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (7507, '啊，我们最伟大的书籍中的一卷。它已经遗失很久很久了。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (7604, '我们之间有商业往来吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (7637, '你好，高贵的圣骑士!我已经准备好了我最珍贵的香炉，里面放入了最新鲜的薰香并施以祝福三次供你使用。你的捐献不但将帮助我们在铁炉堡制作一个新的香炉，还可以用于购买食物来帮助我们的人们。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (7639, '欢迎回来，$N。你得到驱魔香炉了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (7640, '很高兴再次见到你，$N。你在恐惧谷的工作完成了?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (7646, '你已经走到了这一步，$N。你为它所做的一切牺牲都将为你带来伟大的成就。我可以向你保证这一点。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (7651, '你找到了一本书!') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (7703, '哈哈，你还没有找到它，是不是，老大?也许那只是一个故事……很难相信那个可恶的精灵居然可以从我们戈多克的大王身边偷走东西!') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (7781, '难以置信!') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (7783, '我真希望当你挥出最后一击干掉那头野兽的时候，我能在现场亲眼目睹这一切，$N。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (7785, '你会帮助他从那永恒的牢狱中解脱出来吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (7786, '即使要毁灭整个世界都在所不惜!') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (7787, '<德米提恩看到你的时候蜷缩成了一团。>') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (7789, '敌人的鲜血就是我们的荣耀的象征，你做得很出色。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (7792, '只要捐赠60块毛料，银月城就会全体认同你的慷慨行为。$B$B假如你现在身上有足够的毛料，我就可以收下它们。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (7838, '嘿，傻大个!给我12个竞技场大师饰物，你就可以成为古拉巴什竞技场的宗师!') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (7874, '敌人的鲜血就是我们的荣耀的象征，你做得很出色。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (7875, '敌人的鲜血就是我们的荣耀的象征，你做得很出色。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (7876, '敌人的鲜血就是我们的荣耀的象征，你做得很出色。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (7905, '我的朋友，我能帮你什么忙吗?你有需要兑换的礼券吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (7926, '我的朋友，我能帮你什么忙吗?你有需要兑换的礼券吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (7927, '看来你集满一整套传送门套卡了!恭喜你!') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (7928, '看来你集满一整套督军套卡了!恭喜你!') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (7930, '靠过来，靠过来!如果你想要兑换暗月马戏团奖券，尽管开口吧!你可以用奖券兑换各种不同面值的神奇又梦幻的奖品。不要害羞了，来试试看吧!') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
