INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8165, '虽然在破坏阿拉索联军的补给线方面，污染者做得已经很不错了，但是联盟还在继续对阿拉希盆地进行攻击。我们必须向盆地增派部队，并夺回更多的资源。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8193, '今天下午2点到4点，我们会有一场比赛，看谁是最厉害的钓鱼达人!你只要能率先从荆棘谷海岸的特定水域中钓出40条可口鱼来，就能赢得钓鱼大师的称号!这些鱼群是很容易找到的，你只需留意水面的动静就可以啦!$B$B即使你不是第一个钓到40条鱼的参赛者，我的学徒也会按每5条一定价格的方式向你收购你钓到的鱼。$B$B啊呀，你还犹豫什么，可口鱼游得很快的!') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8194, '虽然比赛冠军已经出来了，但是我仍然会以合理的价格收购你钓到的鱼。怎么样?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8251, '你找到粉末了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8286, '安纳克罗斯回来了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8294, '敌人的鲜血就是我们的荣耀的象征，你做得很出色。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8297, '你拿到资源木箱了吗，$N?如果没有足够的资源，阿拉索联军的士兵可没有办法好好干一仗……') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8298, '虽然在破坏阿拉索联军的补给线方面，污染者做得已经很不错了，但是联盟还在继续对阿拉希盆地进行攻击。我们必须向盆地增派部队，并夺回更多的资源。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8300, '虽然在破坏阿拉索联军的补给线方面，污染者做得已经很不错了，但是联盟还在继续对阿拉希盆地进行攻击。我们必须向盆地增派部队，并夺回更多的资源。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8411, '元素在那?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8415, '只有圣骑士能承担我给予的任务。你就是我要找的人吗? ') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8492, '你收集好那20个铜锭了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8493, '又回来了$C?太好了!我们还需要大量的铜锭，为了准备安其拉之战，请尽你所能地帮我收集铜锭，这些铜锭是要用来建造蒸汽坦克跟旋翼机，$B$B我们为了安其拉战役，真的还需要更多铜锭，你愿意帮帮我们吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8494, '如果你收集到那20个铁锭，我可不想发现你把它们都藏起来了!') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8495, '这么快就回来了?不要让我再重新评估对你不好的看法$C，你让我觉得很感伤。那么，你知道我们仍然没有足够的铁锭供应武器、护甲、蒸汽坦克和搜寻故障所有需要的东西。你觉得你可以在去祖尔格拉布的路上，或是你们这些孩子现在鬼混的地方带回另一批20个铁锭吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8499, '哦，我兄弟让你送来的货?太棒了!我今天运气真好!') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8500, '你能主动关心联盟需要什么东西，这真是太好了。除了现在正在收集的各种物资之外，我们还需要大量的瑟银锭，我将负责这方面的收集。所有的瑟银都将用于制作各种战争必需的物资，特别是用来制造一个军团的蒸汽坦克，准备进攻希利苏斯。你能帮帮我吗，$C？') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8503, '这不是真的!我从来没有将这些堆积物上面的荆棘藻去除过。有人可能会认为它几乎就是经济利义下有效的万灵丹。*咳咳*你不会正好有我们先前谈的荆棘藻吧?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8505, '你有我要的紫莲花草药了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8509, '那是什么?大声的说出来，$C!你拿到我要的阿萨斯之泪吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8512, '很高兴再见到你，$N。显然我们需要更多轻皮来制作各种战争要用的东西。如果你能再帮我带来10张轻皮就太完美了。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8514, '是的$G先生:女士;，看来当前我们已经收集了很多中皮。但我们需要更多的中皮。我可以向你保证这很好用;一块也不要浪费。我知道这个数量很庞大，但如果你愿意，我可以借由你的帮忙让我的配额减少一点。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8516, '没错，存货仍然不够。$N，我们仍未达到理想的目标。想想我们能用重皮做的所有东西!各种护甲和武器。蒸汽坦克的零件和步枪瞄准器!工程学护目镜，而且如果到最后我们还有剩下，可以把它们交给部落的齐柏林飞艇!$B$B你会为我带更多的重皮回来吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8518, '我非常惊奇有那么多无私的人将私欲抛于一旁。$C，我还需要收集更多的亚麻绷带，直到完成我的指标。你是否可以再帮我收集一些亚麻绷带呢？') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8520, '我需要那些外套和头罩，另外还需要一株野葡萄，然后我就会把蛮皮盔帽的制作方法告诉你。$B$B防护头部的装备是冒险者们垂涎已久的，无论是简单的头带还是一顶密闭的盔帽，无论其外观如何，制造有价值的头部装备的道理是恒久不变的。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8522, '日子一天天过去，我们也继续向前走。$C，你有那些符文布绷带了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8523, '又是讨论紧急事件的时候了，$C。我再次感谢你之前所作的努力;不是每个人都能如此无私奉献。但是我们仍然很多事要完成。$B$B$N，你可以再去收集符文布绷带并拿回来这里给我吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8526, '你拿到所有的烤迅猛龙肉了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8528, '我有信心你很快就会带着我们讨论的斑点黄尾鱼回来。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8529, '如果你愿意我想派你再去捕一批斑点黄尾鱼，$N。我想你有了第一次的经验，这次捕鱼一定会更快更容易。你愿意吗？') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8533, '这么快就回来了？你很快就会成为一个真正的矿工了，$C。那么，你已经知道怎么钻孔了；我需要你出去帮我挖掘一堆铜矿，熔解它们做成铜锭再带回来给我。我知道你能办到，问题是，你愿意吗？') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8543, '很好，我看的出你对这场战争很用心。我有点期盼战争可以赶快开始，我想你应该也是一样，$C。当战争开始时一定会是很光荣的。部落这在希利苏斯沙漠的尘土上奔驰着，手上拿着武器，冲锋陷阵在无数的虫群之中。总有一天将会取得极大的荣耀!$B$B哈!但是首先我们需要锡锭。真有趣，这样的小东西却可以带来巨大的不同，你说不是吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8546, '太好了，很高兴你出现在这。你之前帮过我，现在我再次需要你的帮忙。我们仍然需要更多的秘银锭;\r\n需要制作很多护甲和武器还有其他东西来歼灭那些安其拉的虫子。$B$B所以如果你是个真正的朋友，你就会为我带回来更多的秘银锭。我会一直收下你的秘银锭直到达到我们的配额。你现在就可以给我一些吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8549, '这么快就带着宁神花回来了吗，$C?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8578, '熔火之心啊?我希望我的护目镜还完好如初!') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8580, '你完成了样本收集工作吗?拯救诺格刻不容缓!') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8582, '你找到大使了吗，$N?他死了吗?$B$B我们承受不起让天谴军团在卡林多建立据点的威胁。现在我们陷入了两面作战的境地，这足以说明他们已经对我们构成了足够的威胁。$B$B你告诉我的事情中唯一让我感到乐观的事情就是那个野猪人的首领看起来还未被腐蚀。她肯定知道天谴军团可能会带来巨大的力量，但如果她同意接受他们的条件，贫瘠之地并不会真正成为她的地盘。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8626, '你把我要的东西都带来了吗，$N?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8656, '在安其拉的住所里，可怕的克苏恩在睡眠中等待着。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8657, '你有带我要的材料吗，$N?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8659, '你收集好我要的材料了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8666, '在安其拉的住所里，可怕的克苏恩在睡眠中等待着。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8699, '你帮我把戒指和材料带来了吗，$N?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8729, '时间在不断流逝，勇士。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8733, '(幽光哼了一声。)') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8735, '(雷姆洛斯陷入沉思。)') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8743, '甲虫之锣嗡嗡作响，给你一种不安的感觉。坚强起来，$N。一旦甲虫之锣被敲响，安其拉的大门就将被打开。$B$B从这扇大门之后涌出来的将会是混乱和毁灭。保护你的人民!') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8748, '如此巨大的奉献真是少有。你已证明了你的意志坚定，$N。你会因为勇敢的守护着我们的世界而获得重赏。$B$B将你的徽记之戒交给我，这样我才能强化它的附魔。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8749, '如此巨大的奉献真是少有。你已证明了你的意志坚定，$N。你会因为勇敢的守护着我们的世界而获得重赏。$B$B将你的徽记之戒交给我，这样我才能强化它的附魔。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8750, '如此巨大的奉献真是少有。你已证明了你的意志坚定，$N。你会因为勇敢的守护着我们的世界而获得重赏。$B$B将你的徽记之戒交给我，这样我才能强化它的附魔。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8757, '相当出色，小家伙。你吃了不少苦才获得青铜龙军团的青睐。你的奉献令人印象深刻。$B$B塑能师的徽记之戒将会大大提升你的魔法和自然能力。$B$B提高警觉，一旦你选择了你的道路，就无法回头了。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8758, '如此巨大的奉献真是少有。你已证明了你的意志坚定，$N。你会因为勇敢的守护着我们的世界而获得重赏。$B$B将你的徽记之戒交给我，这样我才能强化它的附魔。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8760, '如此巨大的奉献真是少有。你已证明了你的意志坚定，$N。你会因为勇敢的守护着我们的世界而获得重赏。$B$B将你的徽记之戒交给我，这样我才能强化它的附魔。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8763, '这台「冬青保存机」第一眼看起来还满坚固的，但是经过仔细的检查之后，你发现它上面有些地精式的改造。不过，你的烹饪技能使得你可以理解它这台机器是如何运作的。$B$B机器里面已经有了新鲜的冬青了－－你只需要提供一些石中盐跟5个金币就可以让这台机器运作起来。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8765, '勇士，如果你决定走上另一条道路，请将你的徽记之戒交给我并从我们的安其拉敌人那里带回一堆甲虫。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8766, '勇士，如果你决定走上另一条道路，请将你的徽记之戒交给我并从我们的安其拉敌人那里带回一堆甲虫。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8790, '你会将他们击败并让我们脱离这些束缚。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8799, '这台「冬青保存机」第一眼看起来还满坚固的，但是经过仔细的检查之后，你发现它上面有些地精式的改造。不过，你的烹饪技能使得你可以理解它这台机器是如何运作的。$B$B机器里面已经有了新鲜的冬青了－－你只需要提供一些石中盐跟5个金币就可以让这台机器运作起来。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8843, '完成了自己的任务并得到荣誉徽章的冒险者可以把他们的徽章交给我，你每次把10枚徽章交给我，我都可以用它们来显着提升你在铁炉堡的声望。当然，我也接受单枚徽章的交换申请，但是这对于声望的提升效果就会逊色许多。虽然我们不会忘记每一位冒险者的努力，但是贡献越大，回报就越大。$B$B如果你有足够的荣誉徽章要给我的话，随时来找我。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8845, '完成了自己的任务并得到荣誉徽章的冒险者可以把他们的徽章交给我，你每次把10枚徽章交给我，我都可以用它们来显着提升你在暴风城的声望。当然，我也接受单枚徽章的交换申请，但是这对于声望的提升效果就会逊色许多。虽然我们不会忘记每一位冒险者的努力，但是贡献越大，回报就越大。$B$B如果你有足够的荣誉徽章要给我的话，随时来找我。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8857, '嗯?你发现了什么?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8859, '朋友，你穿那双靴子看起来有些笨拙。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8861, '你好啊，$C!你是来雷霆崖参加新年庆典的吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8867, '你找到那些发射器了吗，$N?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8904, '我的担心是对的吗?我们的白痴守卫克服了没?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8923, '你想跟我谈谈吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8992, '我欣赏你，$N，如果你能带着完整的护符回来的话。如果没有，那么，请快点完成别浪费时间，我向你保证!') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (8999, '依照我们的约定，你准备好交出你的野性之心装备来换取全新的野兽之心风帽和外衣了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (9003, '依照我们的约定，你准备好交出你的虔诚装备来换取全新的善洁王冠和长袍了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (9022, '你回来了，我从你的眼睛里看出来你有很多话想跟我讲，$N。让我们先处理好你的奖励。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (9034, '纳克萨玛斯握有古老的邪恶，$N。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (9039, '纳克萨玛斯握有古老的邪恶，$N。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (9042, '纳克萨玛斯握有古老的邪恶，$N。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (9050, '纳克萨玛斯握有古老的邪恶，$N。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (9061, '纳克萨玛斯握有古老的邪恶，$N。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (9075, '你把我要的东西带来了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (9081, '赶快把材料带给我不要再浪费我的时间了，$C。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (9093, '材料虽然昂贵，但你很快就不会放在心上了。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (9120, '祝福圣光!你拿着什么邪恶的东西，$g小男孩:小女孩;\r\n?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (9126, '我可以指引你去骷髅遍布的地方，$C。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (9233, '这跟我想的是一样的吗?$B$B＜维尔海姆流口水貌。＞') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (9248, '(达纳苏斯语)报上名来?喔，请原谅我，$N。我没有认出你来。你拿到权杖了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (9320, '除了我们其他的补给外，我们还有很多很有用的极效法力药水。你拿八个墓地符文来我就会给你一瓶。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (9367, '火焰都发烫着吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (9388, '庆典结束之前火焰都不能熄灭!') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (9389, '你完成你的任务了吗?') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (39986, '我想在适当的情况下，我可能会改变主意。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (39987, '穷人有福了，慷慨的人有福了。向神圣之光教堂捐款，是为了确保你在来世的幸福。你是来捐款的吗，$n？') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (39988, '你需要什么，市民？') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (40003, '来，我的朋友，坐下来吸一口。这是非常值得的。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (40113, '你回来了。你发现了什么？') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (40115, '你好吗，我的朋友？') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (40120, '你让森林变得更安全了吗，朋友？') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (40121, '那个野兽，幽灵追踪者，你消灭他了吗？') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (40122, '你好，$R。很高兴在这样一片破旧的风景中看到一张友好的面孔。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (40174, '已经做完了，伙计？') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (40395, '我永远焦躁不安。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (40640, '它们把你电晕没？') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (40667, 'Lok-regar no\'gal, $r.欢迎你。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (40755, '那么，你有什么好消息吗，$c？') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (40757, '你找到那个一无是处的小偷了吗，给他伸张了正义了吗？$B$B最好的情况是，你把我的东西都找回来了吧？') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (40781, '你已经和他们交谈过了吗？') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (40828, '据信，维克多·奈法留斯勋爵居住在黑石山，在那里他对黑石兽人军队以及其他可怕而令人厌恶的生物行使权力。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (41148, '这肯定就是多兰跟你说过的那块墓碑了。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (50305, '搞到肉了吗？') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (50326, '他在西部荒野的匕首岭那...嘿，你拿回来了吗？') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (55042, '找到他了吗？') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (60020, '如果让她们掌握了奥法之力，任何人都将无能为力。') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (70033, '把他的头颅给我，我会将其放在火上！') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (80100, '你知道他们都说什么：“时间就是金钱，我的朋友。”') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
INSERT INTO `locales_quest` (`entry`, `RequestItemsText_loc4`) VALUES (80380, '“时间紧迫，伙计。在这场大型盛会之前，我不能浪费剩下的时间，这样我就可以用我惊人的辣蟹蛋奶酥来给那个家伙一个惊喜。这里的烹饪比赛异常激烈，让人为了胜利而做出疯狂的举动，$N，但我总是抢先一步。”') ON DUPLICATE KEY UPDATE `RequestItemsText_loc4` = VALUES(`RequestItemsText_loc4`);  -- 
